## 2. `server.js` — App Setup, Middleware & Error Handling

```javascript
/**
 * server.js
 *
 * This file bootstraps the Express application, configures middleware,
 * mounts routes, and defines global error-handling behavior.
 *
 * Design choices explained:
 * - express.json() parses incoming JSON request bodies so we can read req.body
 * - We use a 4-parameter error middleware (err, req, res, next) which Express
 *   recognizes as an error handler. It must be registered AFTER all routes.
 * - In-memory storage uses a plain array because this is an educational example;
 *   in production you would replace this with a database driver.
 */

const express = require('express');
const bookRoutes = require('./routes');

// ---------------------------------------------------------------------------
// Application setup
// ---------------------------------------------------------------------------
const app = express();
const PORT = process.env.PORT || 3000;

/**
 * Middleware: Parse JSON request bodies.
 * Without this, req.body would be undefined for POST/PUT requests.
 */
app.use(express.json());

/**
 * Simple logging middleware — prints method, URL, and timestamp for every request.
 * Useful for debugging and understanding request flow.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler
});

// ---------------------------------------------------------------------------
// Mount routes
// ---------------------------------------------------------------------------
/**
 * Register all book-related routes under the /books prefix.
 * The route file exports an Express Router, which is a mini-app that handles
 * its own routing logic. This keeps server.js clean and modular.
 */
app.use('/books', bookRoutes);

// ---------------------------------------------------------------------------
// GET /stats — Aggregate statistics endpoint
// ---------------------------------------------------------------------------
/**
 * Returns summary statistics about the in-memory book collection.
 *
 * @route  GET /stats
 * @access Public (no auth required for this educational example)
 *
 * Example response:
 * {
 *   "totalBooks": 5,
 *   "averageRating": 7.4,
 *   "genres": { "Fiction": 2, "Science": 1, ... },
 *   "booksByAuthor": { "Author Name": 3, ... }
 * }
 */
app.get('/stats', (req, res) => {
  // Access the in-memory store via the routes module's shared reference.
  // In a larger app, this would live in a dedicated service layer.
  const books = bookRoutes.getBooks();

  if (!books || books.length === 0) {
    return res.json({ totalBooks: 0, averageRating: 0, genres: {}, booksByAuthor: {} });
  }

  // Compute statistics using Array.reduce for efficiency (single pass).
  const stats = books.reduce(
    (acc, book) => {
      acc.totalBooks += 1;
      acc.averageRatingSum += book.rating;
      acc.genres[book.genre] = (acc.genres[book.genre] || 0) + 1;
      acc.booksByAuthor[book.author] = (acc.booksByAuthor[book.author] || 0) + 1;
      return acc;
    },
    { totalBooks: 0, averageRatingSum: 0, genres: {}, booksByAuthor: {} }
  );

  // Round average rating to one decimal place for readability.
  stats.averageRating = parseFloat((stats.averageRatingSum / stats.totalBooks).toFixed(1));
  delete stats.averageRatingSum; // Remove intermediate value from response

  res.json(stats);
});

// ---------------------------------------------------------------------------
// Global error-handling middleware (MUST be last)
// ---------------------------------------------------------------------------
/**
 * Express error-handling middleware.
 * Any route or middleware that calls next(err) will land here.
 * This centralizes error formatting so clients always receive consistent JSON.
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err.message);

  // Default to 500 Internal Server Error for unexpected issues.
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    success: false,
    error: {
      message: err.message,
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    },
  });
});

// ---------------------------------------------------------------------------
// Start the server
// ---------------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Try: curl http://localhost:${PORT}/books`);
});
```

