## 3. `routes/index.js` — All Route Definitions

```javascript
/**
 * routes/index.js
 *
 * Contains every REST endpoint for the /books resource plus shared state.
 *
 * Why a Router? Express Routers let you group related routes and apply
 * route-specific middleware (e.g., ID validation) in one place. This file
 * exports both the Router instance AND the in-memory store so server.js
 * can access the data for the /stats endpoint.
 */

const express = require('express');
const router = express.Router();

// ===========================================================================
// In-Memory Data Store
// ===========================================================================
/**
 * The books array serves as our "database."
 *
 * Why an array? For this educational example, a plain array is simple and fast.
 * Each book object has:
 *   - id:        Unique identifier (auto-incremented integer)
 *   - title:     Book title (string)
 *   - author:    Author name (string)
 *   - genre:     Genre/category (string)
 *   - rating:    Numeric rating from 0–10 (number)
 *   - createdAt: ISO timestamp of creation (string)
 *
 * In production, you would replace this with a MongoDB/PostgreSQL driver.
 */
const books = [
  { id: 1, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', genre: 'Fiction', rating: 8.5, createdAt: '2024-01-01T00:00:00Z' },
  { id: 2, title: 'A Brief History of Time', author: 'Stephen Hawking', genre: 'Science', rating: 9.0, createdAt: '2024-01-02T00:00:00Z' },
  { id: 3, title: 'Dune', author: 'Frank Herbert', genre: 'Sci-Fi', rating: 8.8, createdAt: '2024-01-03T00:00:00Z' },
];

/** Next ID counter — simple auto-increment for educational purposes. */
let nextId = 4;

// Export the store so server.js can read it for /stats
router.getBooks = () => books;

// ===========================================================================
// Helper: Custom Error Classes
// ===========================================================================
/**
 * Base error class for all API errors.
 * Extends built-in Error and adds a statusCode property.
 */
class ApiError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.name = 'ApiError';
  }
}

/** Thrown when a requested resource does not exist. */
class NotFoundError extends ApiError {
  constructor(resource) {
    super(`${resource} not found`, 404);
    this.name = 'NotFoundError';
  }
}

/** Thrown when client input fails validation. */
class ValidationError extends ApiError {
  constructor(message) {
    super(message, 400);
    this.name = 'ValidationError';
  }
}

// ===========================================================================
// Helper: Validation Functions
// ===========================================================================
/**
 * Validates that a book object has all required fields with correct types.
 *
 * @param {Object} book - The book data to validate.
 * @throws {ValidationError} If any field is missing or invalid.
 */
function validateBook(book) {
  const errors = [];

  if (!book.title || typeof book.title !== 'string' || book.title.trim() === '') {
    errors.push('title is required and must be a non-empty string');
  }
  if (!book.author || typeof book.author !== 'string' || book.author.trim() === '') {
    errors.push('author is required and must be a non-empty string');
  }
  if (!book.genre || typeof book.genre !== 'string' || book.genre.trim() === '') {
    errors.push('genre is required and must be a non-empty string');
  }
  if (typeof book.rating !== 'number' || book.rating < 0 || book.rating > 10) {
    errors.push('rating is required and must be a number between 0 and 10');
  }

  if (errors.length > 0) {
    throw new ValidationError(errors.join('; '));
  }
}

/**
 * Validates that the :id parameter is a positive integer.
 * Used as route-level middleware for all /books/:id endpoints.
 */
function validateId(req, res, next) {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id) || id < 1) {
    return next(new ValidationError('Invalid book ID: must be a positive integer'));
  }
  req.bookId = id; // Attach validated ID to request for use in handlers
  next();
}

// ===========================================================================
// GET /books — List all books (with optional filtering)
// ===========================================================================
/**
 * Returns a list of all books. Supports query parameters for filtering:
 *   - genre:    Filter by exact genre match (e.g., ?genre=Fiction)
 *   - author:   Filter by author name substring (case-insensitive)
 *   - minRating: Filter books with rating >= this value (0–10)
 *
 * @route  GET /books
 * @param {string} [req.query.genre]       Exact genre filter
 * @param {string} [req.query.author]      Author name substring filter
 * @param {number} [req.query.minRating]   Minimum rating filter (0-10)
 *
 * @example
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Sci-Fi&minRating=8"
 */
router.get('/', (req, res) => {
  let result = [...books]; // Clone array to avoid mutating the store

  // Apply filters only if query parameters are provided.
  if (req.query.genre) {
    result = result.filter(book => book.genre.toLowerCase() === req.query.genre.toLowerCase());
  }
  if (req.query.author) {
    const authorLower = req.query.author.toLowerCase();
    result = result.filter(book => book.author.toLowerCase().includes(authorLower));
  }
  if (req.query.minRating) {
    const minRating = parseFloat(req.query.minRating);
    if (!isNaN(minRating)) {
      result = result.filter(book => book.rating >= minRating);
    }
  }

  res.json({
    success: true,
    count: result.length,
    data: result,
  });
});

// ===========================================================================
// GET /books/:id — Get a single book by ID
// ===========================================================================
/**
 * Returns a single book object matching the given ID.
 *
 * @route  GET /books/:id
 * @param {number} req.params.id - Book ID (validated by validateId middleware)
 *
 * @example
 *   curl http://localhost:3000/books/1
 */
router.get('/:id', validateId, (req, res) => {
  const book = books.find(b => b.id === req.bookId);

  if (!book) {
    // NotFoundError will be caught by the global error handler in server.js.
    return next(new NotFoundError('Book'));
  }

  res.json({ success: true, data: book });
});

// ===========================================================================
// POST /books — Create a new book
// ===========================================================================
/**
 * Creates a new book from the request body and returns it with a 201 status.
 *
 * @route  POST /books
 * @body {string}  title     - Book title (required)
 * @body {string}  author    - Author name (required)
 * @body {string}  genre     - Genre (required)
 * @body {number}  rating    - Rating 0–10 (required)
 *
 * @example
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","rating":9.2}'
 */
router.post('/', (req, res) => {
  // Validate input before touching the store.
  validateBook(req.body);

  const newBook = {
    id: nextId++,
    ...req.body,
    createdAt: new Date().toISOString(),
  };

  books.push(newBook);

  // 201 Created is the correct status for resource creation.
  res.status(201).json({ success: true, data: newBook });
});

// ===========================================================================
// PUT /books/:id — Update an existing book (full replacement)
// ===========================================================================
/**
 * Replaces all fields of an existing book with the provided data.
 * Use PATCH if you want partial updates instead.
 *
 * @route  PUT /books/:id
 * @param {number} req.params.id   - Book ID to update
 * @body {string}  title           - New title
 * @body {string}  author          - New author
 * @body {string}  genre           - New genre
 * @body {number}  rating          - New rating (0–10)
 *
 * @example
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby (Updated)","rating":9.0}'
 */
router.put('/:id', validateId, (req, res, next) => {
  const bookIndex = books.findIndex(b => b.id === req.bookId);

  if (bookIndex === -1) {
    return next(new NotFoundError('Book'));
  }

  // Validate the incoming data.
  validateBook(req.body);

  // Preserve the original ID and createdAt; replace everything else.
  const updatedBook = {
    ...books[bookIndex],
    ...req.body,
    id: req.bookId,
    createdAt: books[bookIndex].createdAt,
  };

  books[bookIndex] = updatedBook;
  res.json({ success: true, data: updatedBook });
});

// ===========================================================================
// DELETE /books/:id — Delete a book by ID
// ===========================================================================
/**
 * Removes a book from the store and returns a 204 No Content on success.
 *
 * @route  DELETE /books/:id
 * @param {number} req.params.id - Book ID to delete
 *
 * @example
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', validateId, (req, res, next) => {
  const bookIndex = books.findIndex(b => b.id === req.bookId);

  if (bookIndex === -1) {
    return next(new NotFoundError('Book'));
  }

  // Remove the book in-place.
  books.splice(bookIndex, 1);

  // 204 means "success but no response body" — standard for DELETE.
  res.status(204).send();
});

// ===========================================================================
// Export the router
// ===========================================================================
module.exports = router;
```

