## Arquivo 2: `src/models/book.js`

```javascript
/**
 * @fileoverview Modelo de dados para livros com armazenamento em memória.
 *
 * Escolha da estrutura de dados:
 * - Usamos um Array simples (`books`) porque o conjunto de dados é pequeno e
 *   educacional. Arrays oferecem O(1) para append (push) e O(n) para busca,
 *   o que é aceitável para centenas de registros.
 * - Para produção com milhares/milhões de livros, substituiríamos por um Map
 *   (O(1) lookup por ID) ou banco de dados relacional/NoSQL.
 * - Cada livro é um objeto plain com campos tipados e validação básica.
 */

/**
 * Array em memória que armazena todos os livros da API.
 *
 * Por que array e não objeto? Arrays preservam a ordem de inserção (útil para
 * listagens paginadas) e são mais intuitivos para operações como filtragem com
 * map/filter/reduce. Um Map seria melhor se precisássemos de lookup O(1) por ID,
 * mas perderíamos a ordenação natural.
 */
const books = [];

/**
 * Contador global para geração automática de IDs sequenciais.
 *
 * Usamos um contador em vez de UUIDs porque:
 * 1. IDs numéricos são mais legíveis em logs e URLs
 * 2. Sequenciais facilitam testes educacionais (previsibilidade)
 * 3. Em produção, usaríamos UUID v4 ou Snowflake para evitar colisões
 *    em sistemas distribuídos
 */
let nextId = 1;

/**
 * Classe que representa um livro no sistema.
 *
 * A classe encapsula a validação de campos obrigatórios e tipos,
 * garantindo integridade dos dados antes da inserção na memória.
 */
class Book {
  /**
   * Cria uma nova instância de livro.
   *
   * @param {string} title - Título do livro (obrigatório, não vazio)
   * @param {string} author - Autor do livro (obrigatório, não vazio)
   * @param {string} [isbn] - ISBN do livro (opcional, formato livre)
   * @param {number} [year] - Ano de publicação (opcional, deve ser positivo)
   * @param {string} [genre] - Gênero literário (opcional)
   */
  constructor(title, author, isbn = null, year = null, genre = null) {
    /** @type {number} ID único gerado automaticamente pelo sistema */
    this.id = nextId++;

    /** @type {string} Título principal do livro */
    this.title = title;

    /** @type {string} Nome do autor ou autores */
    this.author = author;

    /** @type {string|null} ISBN-13 ou ISBN-10, se disponível */
    this.isbn = isbn;

    /** @type {number|null} Ano de publicação (ex: 2023) */
    this.year = year;

    /** @type {string|null} Gênero literário (ex: "Ficção", "Não-ficção") */
    this.genre = genre;

    /** @type {string} Timestamp ISO 8601 da criação do registro */
    this.createdAt = new Date().toISOString();

    /** @type {string|null} Timestamp ISO 8601 da última atualização, ou null se nunca atualizado */
    this.updatedAt = null;
  }

  /**
   * Atualiza os campos mutáveis do livro com novos valores.
   * Campos não fornecidos permanecem inalterados (partial update).
   *
   * @param {Object} updates - Objeto contendo os campos a atualizar
   */
  update(updates) {
    // Atualiza apenas os campos que existem no objeto de atualização
    if (updates.title !== undefined) this.title = updates.title;
    if (updates.author !== undefined) this.author = updates.author;
    if (updates.isbn !== undefined) this.isbn = updates.isbn;
    if (updates.year !== undefined) this.year = updates.year;
    if (updates.genre !== undefined) this.genre = updates.genre;

    // Sempre atualiza o timestamp de modificação
    this.updatedAt = new Date().toISOString();
  }

  /**
   * Retorna uma representação em JSON do livro.
   * Útil para serialização consistente nas respostas da API.
   *
   * @returns {Object} Objeto plano com todos os campos do livro
   */
  toJSON() {
    return {
      id: this.id,
      title: this.title,
      author: this.author,
      isbn: this.isbn,
      year: this.year,
      genre: this.genre,
      createdAt: this.createdAt,
      updatedAt: this.updatedAt,
    };
  }
}

/**
 * Valida os campos obrigatórios de um livro antes da criação.
 *
 * @param {Object} data - Dados brutos vindos do corpo da requisição
 * @returns {{valid: boolean, errors: string[]}} Resultado da validação
 */
function validateBook(data) {
  const errors = [];

  // Validação de título: obrigatório e não vazio após trim
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    errors.push('O campo "title" é obrigatório e deve ser uma string não vazia.');
  }

  // Validação de autor: obrigatório e não vazio após trim
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    errors.push('O campo "author" é obrigatório e deve ser uma string não vazia.');
  }

  // Validação opcional de ano: se fornecido, deve ser um número positivo
  if (data.year !== undefined && data.year !== null) {
    const year = Number(data.year);
    if (!Number.isInteger(year) || year < 1000 || year > new Date().getFullYear() + 1) {
      errors.push('O campo "year" deve ser um número inteiro entre 1000 e o ano atual + 1.');
    }
  }

  return { valid: errors.length === 0, errors };
}

/**
 * Retorna todos os livros armazenados em memória.
 *
 * @returns {Object[]} Array de objetos livro (formato JSON)
 */
function getAllBooks() {
  return books.map((book) => book.toJSON());
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - ID do livro a ser encontrado
 * @returns {Object|null} Livro encontrado ou null se não existir
 */
function getBookById(id) {
  const book = books.find((b) => b.id === id);
  return book ? book.toJSON() : null;
}

/**
 * Cria um novo livro e o adiciona ao array em memória.
 *
 * @param {Object} data - Dados do livro (title, author, isbn?, year?, genre?)
 * @returns {Object} O livro criado com todos os campos preenchidos
 */
function createBook(data) {
  const book = new Book(data.title, data.author, data.isbn, data.year, data.genre);
  books.push(book);
  return book.toJSON();
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a atualizar
 * @param {Object} updates - Campos a atualizar
 * @returns {Object|null} Livro atualizado ou null se não encontrado
 */
function updateBook(id, updates) {
  const book = books.find((b) => b.id === id);
  if (!book) return null;

  book.update(updates);
  return book.toJSON();
}

/**
 * Remove um livro do array pelo ID.
 *
 * @param {number} id - ID do livro a remover
 * @returns {boolean} True se removido, false se não encontrado
 */
function deleteBook(id) {
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o acervo de livros.
 *
 * Estatísticas incluídas:
 * - totalBooks: quantidade total de livros
 * - totalAuthors: quantidade de autores únicos (considerando trim)
 * - avgYear: ano médio de publicação (arredondado)
 * - booksByGenre: contagem de livros por gênero
 * - oldestBook: livro mais antigo publicado
 * - newestBook: livro mais recente publicado
 *
 * @returns {Object} Objeto com as estatísticas calculadas
 */
function getStats() {
  const totalBooks = books.length;

  // Set para contar autores únicos (normaliza com trim e lowercase)
  const uniqueAuthors = new Set(books.map((b) => b.author.trim().toLowerCase()));

  // Filtra livros com ano válido para cálculo da média
  const booksWithYear = books.filter((b) => b.year !== null && b.year !== undefined);
  const avgYear =
    booksWithYear.length > 0
      ? Math.round(booksWithYear.reduce((sum, b) => sum + b.year, 0) / booksWithYear.length)
      : null;

  // Agrupamento por gênero usando reduce — O(n) com um único loop
  const booksByGenre = books.reduce((acc, book) => {
    const genre = book.genre ? book.genre.trim() : 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Encontra livro mais antigo e mais recente por ano de publicação
  const oldestBook =
    booksWithYear.length > 0
      ? booksWithYear.reduce((min, b) => (b.year < min.year ? b : min)).toJSON()
      : null;

  const newestBook =
    booksWithYear.length > 0
      ? booksWithYear.reduce((max, b) => (b.year > max.year ? b : max)).toJSON()
      : null;

  return {
    totalBooks,
    totalAuthors: uniqueAuthors.size,
    avgYear,
    booksByGenre,
    oldestBook,
    newestBook,
  };
}

/**
 * Limpa todos os livros da memória (útil para testes).
 */
function clearAllBooks() {
  books.length = 0;
  nextId = 1;
}

module.exports = {
  Book,
  validateBook,
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  clearAllBooks,
};
