## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * @fileoverview Middleware centralizado de tratamento de erros.
 *
 * Por que um middleware dedicado para erros?
 * - O Express permite definir middlewares com 4 parâmetros (err, req, res, next)
 *   que capturam erros lançados em qualquer ponto da cadeia.
 * - Centralizar o tratamento evita repetição de blocos try/catch em cada rota.
 * - Permite padronizar o formato de respostas de erro para todos os clientes.
 *
 * Padrão de resposta de erro:
 * {
 *   success: false,
 *   error: {
 *     code: "NOT_FOUND",
 *     message: "Recurso não encontrado",
 *     details: [...]  // opcional, para validação
 *   },
 *   timestamp: "2024-01-15T10:30:00.000Z"
 * }
 */

/**
 * Classe base para erros personalizados da API.
 *
 * Herda de Error nativo do JavaScript, adicionando:
 * - statusCode: código HTTP correspondente (400, 404, etc.)
 * - errorCode: identificador único em UPPER_SNAKE_CASE para o cliente
 *
 * @example
 * throw new NotFoundError('Livro não encontrado', { bookId: 42 });
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem de erro legível pelo usuário
   * @param {number} statusCode - Código HTTP da resposta (padrão: 500)
   * @param {string} errorCode - Código de erro em UPPER_SNAKE_CASE
   * @param {Object} [details] - Detalhes adicionais para debugging
   */
  constructor(message, statusCode = 500, errorCode = 'INTERNAL_ERROR', details = null) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
    this.errorCode = errorCode;
    this.details = details;

    // Mantém o stack trace correto mesmo com custom constructor
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

/**
 * Erro para requisições malformadas (400 Bad Request).
 * Usado quando validação de entrada falha.
 */
class BadRequestError extends ApiError {
  constructor(message, details = null) {
    super(message, 400, 'BAD_REQUEST', details);
    this.name = 'BadRequestError';
  }
}

/**
 * Erro para recurso não encontrado (404 Not Found).
 * Usado quando um ID inválido é fornecido.
 */
class NotFoundError extends ApiError {
  constructor(message, details = null) {
    super(message, 404, 'NOT_FOUND', details);
    this.name = 'NotFoundError';
  }
}

/**
 * Erro para recurso já existente (409 Conflict).
 * Pode ser usado no futuro para duplicatas de ISBN.
 */
class ConflictError extends ApiError {
  constructor(message, details = null) {
    super(message, 409, 'CONFLICT', details);
    this.name = 'ConflictError';
  }
}

/**
 * Middleware que captura erros lançados em rotas ou middlewares anteriores.
 *
 * O Express identifica middlewares de erro pelo número de parâmetros (4).
 * Este middleware é adicionado APÓS todas as rotas para capturar erros não tratados.
 *
 * @param {Error} err - Objeto de erro lançado
 * @param {import('express').Request} req - Objeto de requisição Express
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {import('express').NextFunction} next - Função next (não usada aqui)
 */
function errorHandler(err, req, res, next) {
  // Se o erro já é uma instância de ApiError, usamos seus campos
  if (err instanceof ApiError) {
    return res.status(err.statusCode).json({
      success: false,
      error: {
        code: err.errorCode,
        message: err.message,
        ...(err.details && { details: err.details }),
      },
      timestamp: new Date().toISOString(),
      path: req.path,
      method: req.method,
    });
  }

  // Para erros não classificados (ex: erro de parsing JSON), tratamos como 500
  console.error('[Unhandled Error]', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  return res.status(500).json({
    success: false,
    error: {
      code: 'INTERNAL_ERROR',
      message: 'Ocorreu um erro interno no servidor. Tente novamente mais tarde.',
    },
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
  });
}

module.exports = {
  ApiError,
  BadRequestError,
  NotFoundError,
  ConflictError,
  errorHandler,
};
```

