/**
 * @fileoverview Controlador de livros — contém toda a lógica de negócio.
 *
 * Por que separar controladores das rotas?
 * - Rotas apenas mapeiam URL → função; controladores contêm a lógica real.
 * - Isso permite reutilizar a mesma lógica em diferentes contextos (ex: job queue).
 * - Facilita testes unitários isolando a lógica de negócio dos detalhes HTTP.
 *
 * Padrão async/await vs callbacks:
 * - Usamos async/await porque é mais legível e evita "callback hell".
 * - Como esta API usa memória (operações síncronas), as funções são simples,
 *   mas mantemos a assinatura async para facilitar migração futura para DB.
 */

const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  validateBook,
} = require('../models/book');
const { BadRequestError, NotFoundError } = require('../middleware/errorHandler');

/**
 * GET /books
 * Lista todos os livros com suporte a filtragem e paginação.
 *
 * Query params suportados:
 * - author: filtra por autor (case-insensitive, partial match)
 * - genre: filtra por gênero (exato)
 * - search: busca por título ou autor (partial match)
 * - page: número da página (padrão: 1)
 * - limit: itens por página (padrão: 10, máximo: 100)
 *
 * @example
 * // curl "http://localhost:3000/books?author=tolkien&page=1&limit=5"
 *
 * @param {import('express').Request} req - Requisição Express com query params
 * @param {import('express').Response} res - Resposta Express
 * @param {import('express').NextFunction} next - Função para propagação de erros
 */
async function getAllBooksController(req, res, next) {
  try {
    let result = getAllBooks();

    // Filtragem por autor (partial match, case-insensitive)
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter((book) => book.author.toLowerCase().includes(authorFilter));
    }

    // Filtragem exata por gênero
    if (req.query.genre) {
      result = result.filter(
        (book) => book.genre && book.genre.toLowerCase() === req.query.genre.toLowerCase()
      );
    }

    // Busca por título ou autor (partial match)
    if (req.query.search) {
      const search = req.query.search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(search) ||
          book.author.toLowerCase().includes(search)
      );
    }

    // Paginação
    const page = Math.max(1, parseInt(req.query.page) || 1);
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit) || 10));
    const totalItems = result.length;
    const totalPages = Math.ceil(totalItems / limit);
    const startIndex = (page - 1) * limit;
    const paginatedBooks = result.slice(startIndex, startIndex + limit);

    // Resposta estruturada com metadados de paginação
    res.json({
      success: true,
      data: paginatedBooks,
      pagination: {
        currentPage: page,
        totalPages,
        totalItems,
        itemsPerPage: limit,
        hasNextPage: page < totalPages,
        hasPrevPage: page > 1,
      },
      filters: {
        author: req.query.author || null,
        genre: req.query.genre || null,
        search: req.query.search || null,
      },
    });
  } catch (error) {
    next(error); // Propaga para o middleware de erro centralizado
  }
}

/**
 * GET /books/:id
 * Retorna um único livro pelo ID.
 *
 * @example
 * // curl "http://localhost:3000/books/1"
 *
 * @param {import('express').Request} req - Requisição com params.id
 * @param {import('express').Response} res - Resposta Express
 * @param {import('express').NextFunction} next - Função para propagação de erros
 */
async function getBookByIdController(req, res, next) {
  try {
    const id = parseInt(req.params.id, 10);

    // Validação do ID: deve ser um número inteiro positivo
    if (isNaN(id) || id < 1) {
      throw new BadRequestError('O parâmetro "id" deve ser um número inteiro positivo.', {
        providedValue: req.params.id,
      });
    }

    const book = getBookById(id);

    if (!book) {
      // NotFoundError é uma classe personalizada que o middleware de erro trata automaticamente
      throw new NotFoundError(`Livro com ID ${id} não encontrado.`, { bookId: id });
    }

    res.json({ success: true, data: book });
  } catch (error) {
    next(error);
  }
}

/**
 * POST /books
 * Cria um novo livro a partir dos dados enviados no corpo da requisição.
 *
 * Corpo esperado (JSON):
 * {
 *   "title": "O Senhor dos Anéis",
 *   "author": "J.R.R. Tolkien",
 *   "isbn": "978-0618640157",
 *   "year": 1954,
 *   "genre": "Ficção"
 * }
 *
 * @example
 * // curl -X POST http://localhost:3000/books \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"1984","author":"George Orwell","year":1949}'
 *
 * @param {import('express').Request} req - Requisição com body do livro
 * @param {import('express').Response} res - Resposta Express
 * @param {import('express').NextFunction} next - Função para propagação de erros
 */
async function createBookController(req, res, next) {
  try {
    // Validação dos campos obrigatórios antes de criar o livro
    const validation = validateBook(req.body);

    if (!validation.valid) {
      throw new BadRequestError('Validação falhou. Verifique os campos enviados.', validation.errors);
    }

    const book = createBook(req.body);

    // 201 Created é o código HTTP semântico para recursos criados com sucesso
    res.status(201).json({
      success: true,
      message: 'Livro criado com sucesso.',
      data: book,
    });
  } catch (error) {
    next(error);
  }
}

/**
 * PUT /books/:id
 * Atualiza completamente um livro existente.
 *
 * Nota: PUT é idempotente — múltiplas requisições com o mesmo corpo produzem
 * o mesmo resultado. Para atualizações parciais, usaríamos PATCH.
 *
 * @example
 * // curl -X PUT http://localhost:3000/books/1 \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","year":1932}'
 *
 * @param {import('express').Request} req - Requisição com params.id e body atualizado
 * @param {import('express').Response} res - Resposta Express
 * @param {import('express').NextFunction} next - Função para propagação de erros
 */
async function updateBookController(req, res, next) {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id < 1) {
      throw new BadRequestError('O parâmetro "id" deve ser um número inteiro positivo.', {
        providedValue: req.params.id,
      });
    }

    // Verifica se o livro existe antes de atualizar
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado.`, { bookId: id });
    }

    // Validação dos campos enviados (apenas os obrigatórios)
    const validation = validateBook(req.body);
    if (!validation.valid) {
      throw new BadRequestError('Validação falhou. Verifique os campos enviados.', validation.errors);
    }

    const updatedBook = updateBook(id, req.body);

    res.json({
      success: true,
      message: 'Livro atualizado com sucesso.',
      data: updatedBook,
    });
  } catch (error) {
    next(error);
  }
}

/**
 * DELETE /books/:id
 * Remove um livro do sistema pelo ID.
 *
 * @example
 * // curl -X DELETE http://localhost:3000/books/1
 *
 * @param {import('express').Request} req - Requisição com params.id
 * @param {import('express').Response} res - Resposta Express
 * @param {import('express').NextFunction} next - Função para propagação de erros
 */
async function deleteBookController(req, res, next) {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id < 1) {
      throw new BadRequestError('O parâmetro "id" deve ser um número inteiro positivo.', {
        providedValue: req.params.id,
      });
    }

    const deleted = deleteBook(id);

    if (!deleted) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado.`, { bookId: id });
    }

    // 204 No Content é o código semântico para deleção bem-sucedida sem corpo
    res.status(204).send();
  } catch (error) {
    next(error);
  }
}

/**
 * GET /stats
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * @example
 * // curl "http://localhost:3000/stats"
 *
 * @param {import('express').Request} req - Requisição Express
 * @param {import('express').Response} res - Resposta Express
 * @param {import('express').NextFunction} next - Função para propagação de erros
 */
async function getStatsController(req, res, next) {
  try {
    const stats = getStats();

    res.json({
      success: true,
      data: stats,
    });
  } catch (error) {
    next(error);
  }
}

module.exports = {
  getAllBooksController,
  getBookByIdController,
  createBookController,
  updateBookController,
  deleteBookController,
  getStatsController,
};
