```javascript
/**
 * @fileoverview Configuração da aplicação Express.
 *
 * Esta camada configura middlewares globais, registra rotas e conecta
 * o middleware de tratamento de erros. É o "orquestrador" que une
 * todas as camadas do projeto.
 *
 * Ordem dos middlewares (importante!):
 * 1. Middleware de parsing (body-parser) — deve vir ANTES das rotas
 * 2. CORS — permite requisições cross-origin
 * 3. Rotas — mapeia URLs para controladores
 * 4. Middleware de erro — deve ser o ÚLTIMO, após todas as rotas
 */

const express = require('express');
const cors = require('cors');
const { errorHandler } = require('./middleware/errorHandler');
const bookRoutes = require('./routes/books');

/**
 * Cria e configura a aplicação Express.
 *
 * @returns {import('express').Express} Instância configurada do Express
 */
function createApp() {
  const app = express();

  // Middleware para parsing de JSON no corpo das requisições.
  // limit: '10kb' previne ataques de body gigante; ajuste conforme necessidade.
  app.use(express.json({ limit: '10kb' }));

  // Middleware CORS com configuração restritiva (pode ser expandido para produção)
  app.use(
    cors({
      origin: process.env.CORS_ORIGIN || '*', // Em produção, defina origens específicas
      methods: ['GET', 'POST', 'PUT', 'DELETE'],
      allowedHeaders: ['Content-Type', 'Authorization'],
    })
  );

  // Middleware de logging simples para desenvolvimento
  app.use((req, res, next) => {
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
    next();
  });

  // Rota raiz para health check e documentação
  app.get('/', (req, res) => {
    res.json({
      success: true,
      message: 'API de Livros — Servidor rodando com sucesso!',
      endpoints: {
        docs: 'http://localhost:3000/',
        books: {
          list: 'GET /books',
          getById: 'GET /books/:id',
          create: 'POST /books',
          update: 'PUT /books/:id',
          delete: 'DELETE /books/:id',
        },
        stats: 'GET /stats',
      },
    });
  });

  // Registro das rotas de livros (prefixo /api/v1 para versionamento futuro)
  app.use('/api/v1', bookRoutes);

  // Rota 404 para URLs não mapeados — deve vir ANTES do middleware de erro
  app.use((req, res, next) => {
    const { NotFoundError } = require('./middleware/errorHandler');
    next(new NotFoundError(`Rota ${req.method} ${req.path} não encontrada.`));
  });

  // Middleware centralizado de tratamento de erros — SEMPRE o último
  app.use(errorHandler);

  return app;
}

module.exports = createApp;
```

