## File 2: `server.js`

```javascript
/**
 * server.js — Express Application Entry Point
 *
 * This file sets up the Express application, configures middleware,
 * defines error-handling middleware, and starts the HTTP server.
 *
 * Design choices explained:
 * - We use express.json() middleware to automatically parse incoming JSON bodies.
 *   Without this, req.body would be undefined for POST/PUT requests.
 * - Error-handling middleware in Express is identified by its 4-parameter signature
 *   (err, req, res, next). This must be defined AFTER all routes so Express knows
 *   to route errors here instead of treating it as a regular handler.
 * - We use async/await throughout because it makes asynchronous code more readable
 *   than .then() chains while still being non-blocking. For an in-memory API like
 *   this, async isn't strictly necessary, but it prepares you for real-world APIs
 *   that interact with databases or external services.
 */

const express = require('express');
const bookRoutes = require('./routes/index');

// Create the Express application instance.
// This is the core object through which we configure middleware, routes, and behavior.
const app = express();

// ─────────────────────────────────────────────
// Middleware Configuration
// ─────────────────────────────────────────────

/**
 * express.json() — Built-in middleware that parses incoming requests with JSON payloads.
 *
 * Why we need it: When a client sends a POST or PUT request with a JSON body,
 * Express does NOT automatically parse it into req.body. This middleware reads the
 * raw request stream, parses the JSON, and attaches the resulting object to req.body.
 *
 * The { limit: '10kb' } option prevents abuse by rejecting excessively large payloads.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Custom logging middleware — runs before every request for debugging purposes.
 *
 * Why we include it: In production, you'd use a proper logging library (like winston).
 * For this educational example, simple console.log statements help you trace the
 * request lifecycle and understand how middleware executes in order.
 */
app.use((req, res, next) => {
  // Log the HTTP method, URL, and timestamp for every incoming request.
  // This helps developers debug issues by seeing exactly what requests hit the server.
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  // Call next() to pass control to the next middleware or route handler.
  // Forgetting next() is a common mistake that causes requests to hang indefinitely.
  next();
});

// ─────────────────────────────────────────────
// Route Registration
// ─────────────────────────────────────────────

/**
 * Register all book-related routes under the /books prefix.
 *
 * Why we use a separate route file: As your API grows, keeping all routes in one file
 * becomes unmaintainable. Express's Router abstraction lets you organize routes by
 * resource (books, users, orders) while still mounting them at a single path prefix.
 */
app.use('/books', bookRoutes);

/**
 * Register the stats route under the /stats prefix.
 *
 * Why separate from books: Statistics are aggregate data about the collection, not
 * individual resources. Keeping it on its own route makes the API more intuitive and
 * follows the REST principle that each endpoint should represent a single concept.
 */
app.use('/stats', require('./routes/stats'));

// ─────────────────────────────────────────────
// 404 Handler — Catch-All for Undefined Routes
// ─────────────────────────────────────────────

/**
 * This middleware runs when no route matches the requested URL.
 *
 * Why we need it: Without this, Express would return a generic "Cannot GET /foo" HTML page.
 * For a JSON API, we want consistent error responses regardless of whether the issue is
 * a missing route or a malformed request. This handler ensures all 404s return JSON.
 */
app.use((req, res, next) => {
  // Create an instance of our custom NotFoundError class (defined in routes/index.js).
  // Using a custom error class lets us attach additional properties like statusCode.
  const error = new Error(`Route not found: ${req.method} ${req.url}`);
  // Cast to any because TypeScript isn't being used, but we know the shape.
  const typedError = error;
  typedError.statusCode = 404;
  next(typedError);
});

// ─────────────────────────────────────────────
// Global Error-Handling Middleware
// ─────────────────────────────────────────────

/**
 * Express error-handling middleware — catches all errors and returns consistent JSON responses.
 *
 * Why 4 parameters (err, req, res, next): This is Express's convention for identifying
 * error-handling middleware. If a handler has fewer than 4 parameters, Express treats it
 * as a regular middleware. The extra `err` parameter receives any error passed via next(err).
 *
 * Why we check statusCode: Custom errors (like NotFoundError) carry their own status codes.
 * For unexpected errors, we default to 500 Internal Server Error per HTTP standards.
 */
app.use((err, req, res, next) => {
  // Determine the HTTP status code from the error object, defaulting to 500.
  const statusCode = err.statusCode || 500;

  // Log the full error stack for debugging. In production, you'd use a structured logger.
  console.error(`[ERROR] ${statusCode} - ${err.message}`);
  if (process.env.NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  // Return a consistent JSON error response format.
  // This consistency helps API consumers handle errors predictably.
  res.status(statusCode).json({
    success: false,
    error: {
      message: err.message,
      // Include stack trace only in development for debugging.
      // Never expose stack traces in production as they leak implementation details.
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    },
  });
});

// ─────────────────────────────────────────────
// Server Startup
// ─────────────────────────────────────────────

/**
 * Start the HTTP server and listen on the configured port.
 *
 * Why we use process.env.PORT || 3000: This allows the port to be overridden via
 * environment variables (common in cloud deployments like Heroku or Docker), while
 * defaulting to 3000 for local development.
 */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Try: GET http://localhost:${PORT}/books`);
});
```

