## File 3: `routes/index.js`

```javascript
/**
 * routes/index.js — All Book Management Route Handlers
 *
 * This file contains every endpoint for the /books resource, plus shared utilities
 * like validation helpers and custom error classes.
 *
 * REST Conventions followed:
 * - GET    /books       → List all books (with optional filtering)
 * - GET    /books/:id   → Get a single book by ID
 * - POST   /books       → Create a new book
 * - PUT    /books/:id   → Fully update an existing book
 * - DELETE /books/:id   → Delete a book
 *
 * Why we use REST conventions: REST (Representational State Transfer) is the most
 * widely understood API architecture. Clients know exactly what HTTP method and URL
 * to use without reading documentation. GET retrieves, POST creates, PUT replaces,
 * DELETE removes. This predictability reduces bugs and onboarding time.
 */

const express = require('express');
const router = express.Router();

// ─────────────────────────────────────────────
// In-Memory Data Store
// ─────────────────────────────────────────────

/**
 * In-memory array storage for books.
 *
 * Why an array: Arrays provide O(1) access by index (via splice for deletion) and
 * support iteration for listing/filtering. For a small educational dataset, this is
 * simpler than a Map or object store. In production, you'd use a database (PostgreSQL,
 * MongoDB, etc.) because arrays don't persist across restarts and don't scale.
 *
 * Why we seed with sample data: Having initial data lets you test the API immediately
 * without making POST requests first. It also demonstrates what a typical book object
 * looks like in the response.
 */
const books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5,
  },
  {
    id: 2,
    title: 'Clean Code',
    author: 'Robert C. Martin',
    genre: 'Technology',
    publishedYear: 2008,
    rating: 4.7,
  },
  {
    id: 3,
    title: 'Dune',
    author: 'Frank Herbert',
    genre: 'Science Fiction',
    publishedYear: 1965,
    rating: 4.8,
  },
];

// Track the next ID to assign for new books.
// Why not use array length + 1? If you delete a book, the max ID might be higher
// than the current length. Using a separate counter guarantees unique IDs.
let nextId = 4;

// ─────────────────────────────────────────────
// Custom Error Classes
// ─────────────────────────────────────────────

/**
 * NotFoundError — thrown when a requested resource doesn't exist.
 *
 * Why custom error classes: Built-in JavaScript errors (like Error) don't carry
 * HTTP status codes. By extending Error and adding a statusCode property, we can
 * distinguish between "client error" (404) and "server error" (500) in our global
 * error handler, enabling consistent JSON responses.
 */
class NotFoundError extends Error {
  /**
   * @param {string} message - Human-readable description of the not-found condition.
   */
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
    // Set the HTTP status code to 404 (Not Found).
    // The global error handler reads this property to set res.status().
    this.statusCode = 404;
  }
}

/**
 * ValidationError — thrown when client input fails validation.
 *
 * Why a separate class: Validation errors are client mistakes (400 Bad Request),
 * not server failures (500). Distinguishing them helps API consumers understand
 * whether they need to fix their request or report a bug.
 */
class ValidationError extends Error {
  /**
   * @param {string} message - Description of what validation failed.
   * @param {Object} details - Optional object mapping field names to specific errors.
   */
  constructor(message, details = {}) {
    super(message);
    this.name = 'ValidationError';
    // Set the HTTP status code to 400 (Bad Request).
    this.statusCode = 400;
    // Attach field-level details so clients know exactly which inputs are invalid.
    this.details = details;
  }
}

// ─────────────────────────────────────────────
// Validation Helpers
// ─────────────────────────────────────────────

/**
 * Validate that a book ID is a valid positive integer.
 *
 * Why we validate IDs: Express route parameters are always strings, even if the URL
 * looks numeric (e.g., /books/1). We must explicitly convert and verify to prevent
 * invalid operations like searching for book "abc".
 *
 * @param {string} idStr - The ID parameter from the URL.
 * @returns {number} The parsed integer ID.
 * @throws {ValidationError} If the ID is not a valid positive integer.
 */
function parseBookId(idStr) {
  const id = Number(idStr);
  // Check if parsing succeeded AND the result is a positive integer.
  // isNaN checks for NaN (not-a-number), and id < 1 rejects zero and negatives.
  if (isNaN(id) || id < 1) {
    throw new ValidationError(`Invalid book ID: "${idStr}". Must be a positive integer.`);
  }
  return id;
}

/**
 * Validate required fields for creating or updating a book.
 *
 * Why we validate on both create and update: POST requires all fields because the
 * client is providing the complete resource. PUT also requires all fields because,
 * by REST convention, PUT replaces the entire resource (unlike PATCH which updates
 * only specified fields). This distinction is important for API clarity.
 *
 * @param {Object} body - The request body containing book data.
 * @throws {ValidationError} If any required field is missing or invalid.
 */
function validateBookBody(body) {
  const errors = {};

  // Check that title exists and is a non-empty string.
  // Why trim(): Prevents clients from submitting whitespace-only titles like "   ".
  if (!body.title || !body.title.trim()) {
    errors.title = 'Title is required and cannot be empty.';
  } else if (typeof body.title !== 'string') {
    errors.title = 'Title must be a string.';
  }

  // Check that author exists and is a non-empty string.
  if (!body.author || !body.author.trim()) {
    errors.author = 'Author is required and cannot be empty.';
  } else if (typeof body.author !== 'string') {
    errors.author = 'Author must be a string.';
  }

  // Check that genre exists and is a non-empty string.
  if (!body.genre || !body.genre.trim()) {
    errors.genre = 'Genre is required and cannot be empty.';
  } else if (typeof body.genre !== 'string') {
    errors.genre = 'Genre must be a string.';
  }

  // Check that publishedYear exists and is a valid year.
  // Why check range? Years before 0 or after 2100 are almost certainly mistakes.
  if (body.publishedYear === undefined || body.publishedYear === null) {
    errors.publishedYear = 'Published year is required.';
  } else if (!Number.isInteger(body.publishedYear)) {
    errors.publishedYear = 'Published year must be an integer.';
  } else if (body.publishedYear < 0 || body.publishedYear > 2100) {
    errors.publishedYear = 'Published year must be between 0 and 2100.';
  }

  // Check that rating exists and is a number between 0 and 5.
  if (body.rating === undefined || body.rating === null) {
    errors.rating = 'Rating is required.';
  } else if (typeof body.rating !== 'number') {
    errors.rating = 'Rating must be a number.';
  } else if (body.rating < 0 || body.rating > 5) {
    errors.rating = 'Rating must be between 0 and 5.';
  }

  // If any validations failed, throw a ValidationError with all field details.
  // Throwing here instead of returning lets the global error handler format the response.
  if (Object.keys(errors).length > 0) {
    throw new ValidationError('Validation failed: one or more fields are invalid.', errors);
  }
}

/**
 * Find a book by its ID in the in-memory array.
 *
 * Why we use Array.find(): It returns the first element that satisfies the test
 * function, or undefined if none match. This is more efficient than looping manually
 * and is the idiomatic JavaScript approach.
 *
 * @param {number} id - The numeric ID to search for.
 * @returns {Object|null} The matching book object, or null if not found.
 */
function findBookById(id) {
  return books.find((book) => book.id === id) || null;
}

// ─────────────────────────────────────────────
// GET /books — List All Books (with Filtering)
// ─────────────────────────────────────────────

/**
 * GET /books
 *
 * Returns a list of all books, with optional filtering by query parameters.
 *
 * Query parameter filters:
 * - genre: Filter by exact genre match (e.g., ?genre=Fiction)
 * - author: Filter by author name substring (case-insensitive, e.g., ?author=fitzgerald)
 * - minRating: Filter books with rating >= this value (e.g., ?minRating=4.0)
 *
 * Why we support filtering: Real-world APIs almost always need filtering. Returning
 * all 10,000 books when the client only wants fiction novels would be wasteful.
 * Query parameters are the REST-standard way to modify a list response without
 * creating new endpoints.
 *
 * @example
 * // curl http://localhost:3000/books
 * // Returns all books
 *
 * @example
 * // curl "http://localhost:3000/books?genre=Science+Fiction&minRating=4.5"
 * // Returns only sci-fi books with rating >= 4.5
 */
router.get('/', (req, res) => {
  /**
   * Start with all books as the base result set.
   * We'll apply filters sequentially, narrowing the results at each step.
   */
  let result = [...books];

  // Apply genre filter if provided.
  // Why check req.query.genre !== undefined? This allows empty strings to be
  // distinguished from missing parameters. An empty string would match nothing,
  // which is probably what the user wants if they explicitly typed ?genre=.
  if (req.query.genre !== undefined) {
    result = result.filter((book) => book.genre === req.query.genre);
  }

  // Apply author filter (case-insensitive substring match).
  // Why toLowerCase() on both sides? This makes the search user-friendly—
  // "Fitzgerald", "fitzgerald", and "FITZGERALD" all work.
  if (req.query.author !== undefined) {
    const authorQuery = req.query.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorQuery));
  }

  // Apply minimum rating filter if provided.
  // Why parseFloat()? Query parameters are always strings, so we must convert.
  if (req.query.minRating !== undefined) {
    const minRating = parseFloat(req.query.minRating);
    // Validate that the conversion produced a valid number.
    if (!isNaN(minRating)) {
      result = result.filter((book) => book.rating >= minRating);
    }
  }

  /**
   * Return the filtered results as JSON.
   * Why wrap in { data: [...] }? This provides a consistent response shape that
   * can later be extended with pagination metadata (total, page, limit) without
   * breaking existing clients.
   */
  res.json({
    success: true,
    count: result.length,
    data: result,
  });
});

// ─────────────────────────────────────────────
// GET /books/:id — Get Single Book by ID
// ─────────────────────────────────────────────

/**
 * GET /books/:id
 *
 * Returns a single book identified by its numeric ID.
 *
 * Why we throw NotFoundError instead of returning null: Throwing an error lets the
 * global error handler format a consistent JSON response with the correct HTTP status
 * code (404). If we returned null and checked in the route, we'd need to duplicate
 * this logic in every route that looks up by ID.
 *
 * @param {number} id - The numeric book ID from the URL path.
 *
 * @example
 * // curl http://localhost:3000/books/1
 * // Returns: { "success": true, "data": { "id": 1, ... } }
 */
router.get('/:id', (req, res) => {
  // Parse and validate the ID parameter.
  // This throws ValidationError if the ID is invalid, which the global handler catches.
  const id = parseBookId(req.params.id);

  // Look up the book in our in-memory store.
  const book = findBookById(id);

  // If not found, throw a NotFoundError with a descriptive message.
  if (!book) {
    throw new NotFoundError(`Book with ID ${id} not found.`);
  }

  // Return the book wrapped in our standard response envelope.
  res.json({
    success: true,
    data: book,
  });
});

// ─────────────────────────────────────────────
// POST /books — Create a New Book
// ─────────────────────────────────────────────

/**
 * POST /books
 *
 * Creates a new book and returns it with HTTP status 201 (Created).
 *
 * Why 201 instead of 200: The HTTP specification defines 201 as the standard status
 * for successful resource creation. It signals to clients that a new resource now
 * exists, which may trigger different behavior (e.g., redirecting to the new resource).
 *
 * Why we assign a new ID: Since this is in-memory storage with no database auto-
 * increment, we manually track the next available ID using the `nextId` counter.
 * In production, databases handle this automatically via sequences or ObjectId generation.
 *
 * @example
 * // curl -X POST http://localhost:3000/books \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","publishedYear":1949,"rating":4.6}'
 */
router.post('/', (req, res) => {
  /**
   * Validate the request body before attempting to create anything.
   * Why validate first? Failing fast prevents partial writes and ensures we don't
   * create incomplete records. The ValidationError will include all field errors at once,
   * so the client can fix everything in a single request rather than one field at a time.
   */
  validateBookBody(req.body);

  // Create the new book object with an auto-incremented ID.
  const newBook = {
    id: nextId++,
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    genre: req.body.genre.trim(),
    publishedYear: req.body.publishedYear,
    rating: req.body.rating,
  };

  // Add the new book to our in-memory array.
  // Why push()? Arrays are ordered collections, and push() appends to the end—
  // the most natural operation for a list that grows over time.
  books.push(newBook);

  /**
   * Respond with 201 Created and the newly created book.
   * Including the full resource in the response body is a REST best practice because
   * it lets clients confirm exactly what was stored (e.g., the assigned ID).
   */
  res.status(201).json({
    success: true,
    data: newBook,
  });
});

// ─────────────────────────────────────────────
// PUT /books/:id — Fully Update an Existing Book
// ─────────────────────────────────────────────

/**
 * PUT /books/:id
 *
 * Replaces an existing book entirely with the provided data.
 *
 * Why PUT instead of PATCH? PUT is a full replacement—every required field must be
 * present in the request body. PATCH would only update specified fields. We chose PUT
 * here to keep validation simple and to demonstrate the difference between the two.
 * In practice, you might implement both for more flexible updates.
 *
 * Why we return 200 OK (not 204): Returning the updated resource lets clients confirm
 * the changes were applied correctly, especially since some fields may have been
 * normalized (e.g., trimmed strings).
 *
 * @example
 * // curl -X PUT http://localhost:3000/books/1 \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"The Great Gatsby","author":"F. Scott Fitzgerald","genre":"Fiction","publishedYear":1925,"rating":4.7}'
 */
router.put('/:id', (req, res) => {
  // Parse and validate the ID parameter.
  const id = parseBookId(req.params.id);

  // Find the book before attempting any modifications.
  const bookIndex = books.findIndex((book) => book.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError(`Book with ID ${id} not found.`);
  }

  // Validate the incoming request body.
  validateBookBody(req.body);

  // Replace the entire book object with updated data.
  // Why create a new object instead of mutating? This is safer because it avoids
  // accidental side effects and makes the code easier to reason about.
  books[bookIndex] = {
    id, // Preserve the original ID—IDs should never change.
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    genre: req.body.genre.trim(),
    publishedYear: req.body.publishedYear,
    rating: req.body.rating,
  };

  res.json({
    success: true,
    data: books[bookIndex],
  });
});

// ─────────────────────────────────────────────
// DELETE /books/:id — Delete a Book
// ─────────────────────────────────────────────

/**
 * DELETE /books/:id
 *
 * Removes a book from the collection by its ID.
 *
 * Why 204 No Content? The HTTP specification defines 204 as the standard response
 * for successful deletions with no body. It tells clients "the operation succeeded,
 * and there's nothing to return." Some APIs return 200 with a confirmation message,
 * but 204 is more semantically correct.
 *
 * @example
 * // curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', (req, res) => {
  // Parse and validate the ID parameter.
  const id = parseBookId(req.params.id);

  // Find the index of the book to delete.
  const bookIndex = books.findIndex((book) => book.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError(`Book with ID ${id} not found.`);
  }

  // Remove the book from the array using splice.
  // Why splice(index, 1)? It removes exactly 1 element at the given index and
  // shifts all subsequent elements down, maintaining array continuity.
  books.splice(bookIndex, 1);

  /**
   * Respond with 204 No Content.
   * We explicitly set status(204) and send no body. This is the REST-standard
   * response for successful deletion.
   */
  res.status(204).send();
});

// ─────────────────────────────────────────────
// Export the Router
// ─────────────────────────────────────────────

/**
 * Export the router so server.js can mount it at /books.
 *
 * Why export the router instead of exporting individual handlers? Express routers
 * are self-contained modules that bundle routes, middleware, and error handling for
 * a specific resource. This makes them reusable and testable in isolation.
 */
module.exports = router;
```

