## File 4: `routes/stats.js`

```javascript
/**
 * routes/stats.js — Statistics Endpoint
 *
 * Provides aggregate information about the book collection.
 *
 * Why a separate route file? Even though this is small, separating stats from books
 * demonstrates how to organize an API into logical modules. As your project grows,
 * you'd have routes/users.js, routes/orders.js, etc., each in its own file.
 */

const express = require('express');
const router = express.Router();

// Import the shared data store and helpers from the books route module.
// Why re-export? We could duplicate the books array here, but that would create
// two separate copies of the data. Instead, we import the same in-memory array
// so stats always reflects the current state.
const { books } = require('./index');

/**
 * GET /stats
 *
 * Returns aggregate statistics about the book collection.
 *
 * Statistics provided:
 * - totalBooks: Total number of books in the collection
 * - averageRating: Mean rating across all books (rounded to 2 decimal places)
 * - genreDistribution: Count of books per genre
 * - oldestBook: The book with the earliest published year
 * - newestBook: The book with the latest published year
 *
 * Why we compute these on every request: For a small in-memory dataset, real-time
 * computation is fast and simple. In production with millions of records, you'd use
 * database aggregations or cached statistics that update incrementally.
 *
 * @example
 * // curl http://localhost:3000/stats
 */
router.get('/', (req, res) => {
  // Handle the empty collection case to avoid division by zero.
  if (books.length === 0) {
    return res.json({
      success: true,
      data: {
        totalBooks: 0,
        averageRating: null,
        genreDistribution: {},
        oldestBook: null,
        newestBook: null,
      },
    });
  }

  // Calculate the average rating using reduce.
  // Why reduce()? It's the functional programming idiom for computing a single value
  // from an array. We sum all ratings and divide by the count.
  const totalRating = books.reduce((sum, book) => sum + book.rating, 0);
  const averageRating = parseFloat((totalRating / books.length).toFixed(2));

  // Build the genre distribution object.
  // Why a plain object? It provides O(1) lookup by genre name and serializes nicely
  // to JSON. We iterate through all books and increment the count for each genre.
  const genreDistribution = {};
  for (const book of books) {
    if (!genreDistribution[book.genre]) {
      genreDistribution[book.genre] = 0;
    }
    genreDistribution[book.genre]++;
  }

  // Find the oldest and newest books by published year.
  // Why sort with a custom comparator? We need to compare years numerically, not
  // lexicographically (which would put "1925" after "2008").
  const sortedByYear = [...books].sort((a, b) => a.publishedYear - b.publishedYear);
  const oldestBook = sortedByYear[0];
  const newestBook = sortedByYear[sortedByYear.length - 1];

  res.json({
    success: true,
    data: {
      totalBooks: books.length,
      averageRating,
      genreDistribution,
      oldestBook,
      newestBook,
    },
  });
});

module.exports = router;
```

> **Note:** The stats route imports `books` from `./index`. Since we only export the `router` in `routes/index.js`, we need to also export the `books` array. Update the export at the bottom of `routes/index.js`:

```javascript
// Replace the existing module.exports with:
module.exports = router;
module.exports.books = books; // Also export the data store for stats route
module.exports.NotFoundError = NotFoundError;
module.exports.ValidationError = ValidationError;
```

