## Arquivo 2: `src/errors/customErrors.js`

```javascript
/**
 * customErrors.js
 *
 * Classes de erro personalizadas para a API.
 *
 * POR QUE criar classes de erro personalizadas?
 * -----------------------------------------------
 * Em vez de lançar erros genéricos (new Error('mensagem')), criamos subclasses
 * que carregam informações estruturadas: código HTTP, tipo do erro e mensagem.
 * Isso permite que o middleware de tratamento de erros responda com payloads
 * consistentes e códigos HTTP adequados, seguindo a convenção REST.
 *
 * Padrão adotado: Cada classe estende Error e define uma propriedade 'statusCode'
 * para mapeamento direto para o código HTTP da resposta.
 */

/**
 * Classe base para erros de negócio da API.
 *
 * Herda de Error (classe nativa do Node.js) para manter compatibilidade com
 * o stack trace, mas adiciona campos customizados para uso pelo middleware.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {number} statusCode - Código HTTP correspondente (ex: 400, 404)
   */
  constructor(message, statusCode) {
    super(message); // Chama o construtor da classe Error com a mensagem

    // Define o código HTTP como propriedade da instância.
    // Usamos Object.defineProperty para que a propriedade não seja enumerável
    // (não apareça em JSON.stringify ou Object.keys), mantendo a resposta limpa.
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'error' : 'fail';
    this.isOperational = true; // Indica que é um erro esperado, não um bug

    // Captura o stack trace no ponto de criação do erro (melhor que Error.captureStackTrace)
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro para requisições malformadas (400 Bad Request).
 * Usado quando o cliente envia dados inválidos ou ausentes.
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400); // 400 = Bad Request
  }
}

/**
 * Erro para recurso não encontrado (404 Not Found).
 * Usado quando um ID informado não corresponde a nenhum livro.
 */
class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} não encontrado`, 404); // 404 = Not Found
  }
}

/**
 * Erro para recursos duplicados (409 Conflict).
 * Usado quando uma operação criaria um registro com chave duplicada.
 */
class ConflictError extends AppError {
  constructor(message) {
    super(message, 409); // 409 = Conflict
  }
}

/**
 * Erro para método não permitido (405 Method Not Allowed).
 * Usado quando o cliente usa um verbo HTTP incorreto.
 */
class MethodNotAllowedError extends AppError {
  constructor() {
    super('Método HTTP não permitido para este endpoint', 405);
  }
}

/**
 * Erro interno do servidor (500 Internal Server Error).
 * Usado apenas para erros inesperados que não deveriam ocorrer.
 */
class InternalError extends AppError {
  constructor(message = 'Erro interno do servidor') {
    super(message, 500); // 500 = Internal Server Error
  }
}

// Exporta todas as classes como um único objeto para facilitar a importação
module.exports = {
  AppError,
  ValidationError,
  NotFoundError,
  ConflictError,
  MethodNotAllowedError,
  InternalError,
};
```

**Explicação:** As classes de erro personalizadas seguem o padrão **"Operational Errors"** (erros operacionais) vs. **"Programming Errors"** (bugs). A propriedade `isOperational = true` permite que o middleware de erros distinga entre erros esperados (como "livro não encontrado") e bugs inesperados (como variável indefinida), tratando-os de forma diferente — os primeiros são logados silenciosamente, os segundos recebem alertas.

