## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * errorHandler.js
 *
 * Middleware centralizado de tratamento de erros.
 *
 * POR QUE um middleware de erro dedicado?
 * ----------------------------------------
 * Em Express, middlewares de erro têm 4 parâmetros (err, req, res, next).
 * Centralizar o tratamento evita repetição de lógica de resposta em cada rota
 * e garante que TODOS os erros sejam capturados, inclusive os assíncronos.
 *
 * Padrão adotado: Resposta JSON consistente com { error: { message, statusCode } }.
 */

const { AppError } = require('../errors/customErrors');

/**
 * Middleware de tratamento de erros.
 *
 * @param {Error} err - O erro capturado
 * @param {import('express').Request} req - Objeto de requisição Express
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {import('express').NextFunction} next - Função next do Express
 */
function errorHandler(err, req, res, next) {
  // Se o erro for nossa classe AppError personalizada, usamos seus campos.
  // Caso contrário, tratamos como erro interno inesperado (500).
  const statusCode = err.statusCode || 500;
  const message = err.isOperational ? err.message : 'Ocorreu um erro interno. Tente novamente mais tarde.';

  // Em produção, NÃO expomos o stack trace para o cliente (vazamento de informação)
  // Em desenvolvimento, incluímos o stack para facilitar debugging.
  const response = {
    error: {
      message,
      statusCode,
    },
  };

  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.error.stack = err.stack;
  }

  // Define o Content-Type explicitamente para garantir que o cliente interprete corretamente
  res.status(statusCode).json(response);
}

/**
 * Middleware para capturar erros de rotas assíncronas.
 *
 * POR QUE este wrapper?
 * ---------------------
 * Express NÃO captura automaticamente rejeições de Promises em handlers async.
 * Se um handler async lança um erro, o Express não o encaminha ao middleware
 * de erro a menos que explicitamente passemos o erro para next().
 * Este wrapper resolve esse problema de forma transparente.
 *
 * @param {Function} fn - Função assíncrona do handler
 * @returns {Function} Middleware Express
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    // Executa a função e captura tanto rejeições de Promise quanto erros síncronos
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = { errorHandler, asyncHandler };
```

**Explicação:** O `asyncHandler` é um padrão essencial em APIs Express modernas. Sem ele, qualquer erro lançado dentro de um handler `async` causaria um **UnhandledPromiseRejection**, que pode derrubar o processo Node.js. O wrapper converte silenciosamente a rejeição em uma chamada a `next(err)`, permitindo que o middleware de erro centralizado trate tudo uniformemente.

