## Arquivo 4: `src/data/books.js`

```javascript
/**
 * books.js
 *
 * Camada de dados da API — armazenamento em memória com array.
 *
 * POR QUE usar um array em memória?
 * ------------------------------------
 * Para este exemplo educacional, um array em memória é suficiente porque:
 * 1. Não requer configuração de banco de dados (mais simples para rodar)
 * 2. Permite focar nos conceitos de REST, rotas e middleware
 * 3. Operações são O(1) a O(n) dependendo da operação, aceitável para poucos registros
 *
 * POR QUE NÃO usar um objeto como mapa?
 * ---------------------------------------
 * Um array foi escolhido porque:
 * - A ordem de inserção é preservada (útil para listagem)
 * - É mais fácil de serializar para JSON
 * - Simula melhor um "banco de dados" real onde registros têm ordem
 *
 * Estrutura de cada livro:
 * {
 *   id: number       — Identificador único auto-incrementado
 *   title: string    — Título do livro (obrigatório)
 *   author: string   — Autor do livro (obrigatório)
 *   year: number     — Ano de publicação (obrigatório, inteiro positivo)
 *   genre: string    — Gênero literário (opcional)
 *   createdAt: string — Timestamp ISO da criação
 *   updatedAt: string — Timestamp ISO da última atualização
 * }
 */

// Array que armazena todos os livros em memória.
// Inicializamos com alguns dados de exemplo para facilitar testes.
let books = [
  {
    id: 1,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    year: 1899,
    genre: 'Romance',
    createdAt: '2024-01-15T10:00:00.000Z',
    updatedAt: '2024-01-15T10:00:00.000Z',
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    year: 1949,
    genre: 'Distopia',
    createdAt: '2024-01-15T10:00:00.000Z',
    updatedAt: '2024-01-15T10:00:00.000Z',
  },
  {
    id: 3,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    year: 1954,
    genre: 'Fantasia',
    createdAt: '2024-01-15T10:00:00.000Z',
    updatedAt: '2024-01-15T10:00:00.000Z',
  },
];

// Contador para gerar IDs únicos auto-incrementados.
// Usamos uma variável separada em vez de Math.max() porque é O(1) vs O(n).
let nextId = 4;

/**
 * Retorna todos os livros armazenados.
 * @returns {Array} Lista de objetos livro
 */
function findAll() {
  return books;
}

/**
 * Busca um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser buscado
 * @returns {Object|null} Livro encontrado ou null se não existir
 */
function findById(id) {
  // find() retorna o primeiro elemento que satisfaz a condição, ou undefined
  return books.find((book) => book.id === id) || null;
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * @param {Object} data - Dados do livro (sem id, createdAt, updatedAt)
 * @returns {Object} Livro criado com id e timestamps
 */
function create(data) {
  const newBook = {
    id: nextId++, // Incrementa e atribui o ID atual
    ...data, // Espalha os dados fornecidos pelo cliente
    createdAt: new Date().toISOString(), // Timestamp ISO 8601 para consistência
    updatedAt: new Date().toISOString(),
  };

  books.push(newBook); // Adiciona ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} updates - Campos a serem atualizados (partial update)
 * @returns {Object|null} Livro atualizado ou null se não encontrado
 */
function update(id, updates) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return null; // Livro não encontrado
  }

  // Atualiza apenas os campos fornecidos (partial update / PATCH semantics)
  // e sempre atualiza o timestamp de modificação.
  books[index] = {
    ...books[index], // Mantém todos os campos existentes
    ...updates,      // Sobrescreve com os novos valores
    updatedAt: new Date().toISOString(),
  };

  return books[index];
}

/**
 * Remove um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser removido
 * @returns {boolean} True se removido, False se não encontrado
 */
function remove(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return false;
  }

  // splice() remove o elemento do array e retorna um array com o elemento removido
  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas sobre os livros armazenados.
 *
 * @returns {Object} Estatísticas: total, porGenero, mediaAno, autorMaisProdutivo
 */
function getStats() {
  const total = books.length;

  // Agrupa livros por gênero e conta quantos existem em cada um
  const byGenre = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero'; // Livros sem gênero vão para "Sem gênero"
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Calcula a média dos anos de publicação
  const averageYear =
    total > 0
      ? books.reduce((sum, book) => sum + book.year, 0) / total
      : 0;

  // Encontra o autor com mais livros (mais produtivo)
  const byAuthor = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});

  let mostProductiveAuthor = null;
  let maxBooks = 0;
  for (const [author, count] of Object.entries(byAuthor)) {
    if (count > maxBooks) {
      maxBooks = count;
      mostProductiveAuthor = author;
    }
  }

  return {
    total,
    byGenre,
    averageYear: Math.round(averageYear * 100) / 100, // Arredonda para 2 casas decimais
    mostProductiveAuthor: mostProductiveAuthor
      ? { author: mostProductiveAuthor, booksCount: maxBooks }
      : null,
  };
}

// Exporta todas as funções como um único objeto.
// Isso facilita a importação em outros módulos e permite adicionar
// métodos de teste/mock mais facilmente no futuro.
module.exports = {
  findAll,
  findById,
  create,
  update,
  remove,
  getStats,
};
```

**Explicação:** O uso de `let` para `books` e `nextId` permite que as funções modifiquem o estado. O padrão de exportar um objeto (em vez de exports individuais) é uma convenção que facilita a manutenção — se precisarmos adicionar mais funções, basta adicioná-las ao objeto sem mudar os imports.

