## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * routes/books.js
 *
 * Rotas da API para recursos de livros.
 *
 * POR QUE rotas separadas?
 * -------------------------
 * Manter rotas em arquivos separados por recurso segue o princípio de
 * responsabilidade única. Isso facilita:
 * - Encontrar e modificar rotas específicas
 * - Testar cada conjunto de rotas isoladamente
 * - Escalar a aplicação adicionando novos recursos (autores, editoras, etc.)
 *
 * Convenções REST adotadas:
 * - GET    /books       → Listar todos (com filtragem opcional)
 * - GET    /books/:id   → Obter um específico
 * - POST   /books       → Criar novo
 * - PUT    /books/:id   → Atualizar completo (substituição)
 * - DELETE /books/:id   → Remover
 *
 * Cada handler é envolto por asyncHandler para captura de erros assíncronos.
 */

const express = require('express');
const { asyncHandler } = require('../middleware/errorHandler');
const { ValidationError, NotFoundError } = require('../errors/customErrors');
const booksData = require('../data/books');

// Cria um roteador Express dedicado para livros.
// Isso permite aplicar middlewares específicos apenas a estas rotas.
const router = express.Router();

/**
 * GET /books
 * Lista todos os livros com filtragem opcional por gênero e/ou autor.
 *
 * Parâmetros de query (opcionais):
 * - genre: Filtra por gênero literário (ex: ?genre=Ficção)
 * - author: Filtra por autor (ex: ?author=Orwell)
 * - year: Filtra por ano exato de publicação (ex: ?year=1949)
 *
 * Exemplos de uso:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Ficção"
 *   curl "http://localhost:3000/books?author=Machado"
 *   curl "http://localhost:3000/books?genre=Fantasia&year=1954"
 */
router.get(
  '/',
  asyncHandler(async (req, res) => {
    // req.query contém todos os parâmetros da query string como strings.
    // Usamos destructuring para extrair apenas os que nos interessam.
    const { genre, author, year } = req.query;

    let result = booksData.findAll();

    // Aplica filtros de forma encadeada — cada filtro reduz o array.
    // Isso segue o padrão "query builder" e permite combinar múltiplos filtros.
    if (genre) {
      // toLowerCase() para comparação case-insensitive
      result = result.filter((book) => book.genre?.toLowerCase() === genre.toLowerCase());
    }

    if (author) {
      // Busca parcial no nome do autor (contém o termo, não exige correspondência exata)
      const authorLower = author.toLowerCase();
      result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
    }

    if (year) {
      // Converte para número para comparação numérica correta
      const yearNum = parseInt(year, 10);
      if (!isNaN(yearNum)) {
        result = result.filter((book) => book.year === yearNum);
      }
    }

    // Retorna os livros com código 200 (OK).
    // O array vazio [] é a resposta padrão quando não há resultados —
    // isso evita retornar null/undefined que confundiria o cliente.
    res.json({ data: result, count: result.length });
  })
);

/**
 * GET /books/:id
 * Retorna um livro específico pelo seu ID numérico.
 *
 * Parâmetros de rota:
 * - id: Identificador numérico do livro (ex: /books/1)
 *
 * Exemplos de uso:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → retorna 404
 */
router.get(
  '/:id',
  asyncHandler(async (req, res) => {
    // req.params contém parâmetros da URL. Express os converte para string.
    const id = parseInt(req.params.id, 10);

    // Validação: verifica se o ID é um número válido
    if (isNaN(id)) {
      throw new ValidationError('ID deve ser um número inteiro válido');
    }

    const book = booksData.findById(id);

    // Se não encontrado, lançamos NotFoundError que será capturado pelo middleware
    if (!book) {
      throw new NotFoundError('Livro');
    }

    res.json({ data: book });
  })
);

/**
 * POST /books
 * Cria um novo livro a partir dos dados enviados no corpo da requisição.
 *
 * Corpo esperado (JSON):
 * {
 *   "title": "O Nome do Vento",
 *   "author": "Patrick Rothfuss",
 *   "year": 2007,
 *   "genre": "Fantasia"  // opcional
 * }
 *
 * Exemplos de uso:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Nome do Vento","author":"Patrick Rothfuss","year":2007,"genre":"Fantasia"}'
 */
router.post(
  '/',
  asyncHandler(async (req, res) => {
    const { title, author, year, genre } = req.body;

    // Validação de campos obrigatórios
    if (!title || !author || !year) {
      throw new ValidationError('Campos obrigatórios: title, author, year');
    }

    // Validação do tipo e valor do ano
    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      throw new ValidationError('Year deve ser um número inteiro entre 0 e o ano atual + 1');
    }

    // Cria o livro usando a camada de dados
    const newBook = booksData.create({
      title: title.trim(),     // Remove espaços em branco extras
      author: author.trim(),
      year: yearNum,
      genre: genre ? genre.trim() : undefined, // Gênero é opcional
    });

    // 201 Created + Location header indica o URI do recurso criado.
    // Isso segue a convenção REST e permite ao cliente localizar o novo recurso.
    res.status(201).json({
      data: newBook,
      message: 'Livro criado com sucesso',
    });
  })
);

/**
 * PUT /books/:id
 * Atualiza completamente um livro existente pelo seu ID.
 *
 * Corpo esperado (JSON):
 * {
 *   "title": "Título atualizado",
 *   "author": "Autor atualizado",
 *   "year": 2024,
 *   "genre": "Gênero atualizado"
 * }
 *
 * Nota: PUT implica substituição completa. Todos os campos obrigatórios
 * devem ser enviados, mesmo que não tenham mudado.
 *
 * Exemplos de uso:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dom Casmurro (Ed. Atualizada)","author":"Machado de Assis","year":1899,"genre":"Romance Realista"}'
 */
router.put(
  '/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('ID deve ser um número inteiro válido');
    }

    const { title, author, year, genre } = req.body;

    // Validação dos campos obrigatórios
    if (!title || !author || !year) {
      throw new ValidationError('Campos obrigatórios: title, author, year');
    }

    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      throw new ValidationError('Year deve ser um número inteiro entre 0 e o ano atual + 1');
    }

    // Verifica se o livro existe antes de tentar atualizar
    const existingBook = booksData.findById(id);
    if (!existingBook) {
      throw new NotFoundError('Livro');
    }

    const updatedBook = booksData.update(id, {
      title: title.trim(),
      author: author.trim(),
      year: yearNum,
      genre: genre ? genre.trim() : undefined,
    });

    // 200 OK com o recurso atualizado de volta
    res.json({ data: updatedBook, message: 'Livro atualizado com sucesso' });
  })
);

/**
 * DELETE /books/:id
 * Remove um livro pelo seu ID.
 *
 * Exemplos de uso:
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete(
  '/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('ID deve ser um número inteiro válido');
    }

    // Verifica se o livro existe antes de tentar remover
    const existingBook = booksData.findById(id);
    if (!existingBook) {
      throw new NotFoundError('Livro');
    }

    const removed = booksData.remove(id);

    // 204 No Content é o padrão REST para DELETE bem-sucedido.
    // Não retornamos corpo porque não há recurso para devolver.
    if (removed) {
      res.status(204).send();
    } else {
      // Este caso nunca deve ser atingido (já verificamos a existência),
      // mas mantemos como defesa em profundidade.
      throw new NotFoundError('Livro');
    }
  })
);

module.exports = router;
```

**Explicação:** Cada rota segue o padrão **asyncHandler → validação → operação → resposta**. A validação ocorre ANTES da chamada à camada de dados, seguindo o princípio de "fail fast" — rejeitamos requisições malformadas o mais cedo possível. O uso de `res.status(201)` para criação e `res.status(204)` para deleção segue estritamente as convenções HTTP/REST.

