## File 2: `models/books.js` — In-Memory Data Store

```javascript
/**
 * @fileoverview Books data model using in-memory storage.
 *
 * WHY IN-MEMORY? For an educational example, an in-memory array keeps the code
 * focused on REST API concepts (routing, middleware, error handling) without
 * requiring a database setup. In production, you would replace this with a
 * database layer (MongoDB, PostgreSQL, etc.) while keeping the same interface.
 *
 * WHY AN ARRAY? Arrays provide O(1) access by index and are simple to iterate
 * over for filtering/sorting. For larger datasets, a Map or object keyed by ID
 * would give O(1) lookups by ID instead of O(n).
 */

// ---------------------------------------------------------------------------
// Data Structure: Array of Book Objects
// ---------------------------------------------------------------------------
// Each book has the following shape:
// {
//   id: number          — Unique identifier (auto-incremented)
//   title: string       — Book title
//   author: string      — Author name
//   genre: string       — Genre/category (e.g., "Fiction", "Science")
//   publishedYear: number — Year of publication
//   rating: number      — Average rating from 1.0 to 5.0
// }
// ---------------------------------------------------------------------------

/** @type {Array<Object>} In-memory storage for all books */
const books = [];

/** @type {number} Auto-incrementing ID counter, starts at 1 */
let nextId = 1;

// Seed some initial data so the API isn't empty on startup
books.push(
  { id: 1, title: "To Kill a Mockingbird", author: "Harper Lee", genre: "Fiction", publishedYear: 1960, rating: 4.8 },
  { id: 2, title: "A Brief History of Time", author: "Stephen Hawking", genre: "Science", publishedYear: 1988, rating: 4.7 },
  { id: 3, title: "The Great Gatsby", author: "F. Scott Fitzgerald", genre: "Fiction", publishedYear: 1925, rating: 4.5 }
);
nextId = 4; // Next ID will be 4

// ---------------------------------------------------------------------------
// Exported Functions — Each function is documented with JSDoc
// ---------------------------------------------------------------------------

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * @param {Object} filters - Optional filter criteria
 * @param {string} [filters.author] - Filter by author name (case-insensitive partial match)
 * @param {string} [filters.genre] - Filter by genre (exact match)
 * @param {number} [filters.minRating] - Minimum rating threshold (1.0–5.0)
 * @param {number} [filters.publishedYear] - Exact publication year filter
 * @returns {Array<Object>} Array of matching book objects
 */
function getAllBooks(filters = {}) {
  let result = [...books]; // Create a shallow copy to avoid mutating the original array

  // Apply filters only if they are provided and have truthy values
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter(book => book.author.toLowerCase().includes(authorLower));
  }

  if (filters.genre) {
    result = result.filter(book => book.genre.toLowerCase() === filters.genre.toLowerCase());
  }

  if (filters.minRating != null) {
    result = result.filter(book => book.rating >= Number(filters.minRating));
  }

  if (filters.publishedYear != null) {
    result = result.filter(book => book.publishedYear === Number(filters.publishedYear));
  }

  return result;
}

/**
 * Retrieves a single book by its numeric ID.
 *
 * @param {number} id - The unique identifier of the book
 * @returns {Object|null} The book object if found, null otherwise
 */
function getBookById(id) {
  return books.find(book => book.id === Number(id)) || null;
}

/**
 * Creates a new book and adds it to the in-memory store.
 *
 * @param {Object} bookData - The book data to create
 * @param {string} bookData.title - Book title (required)
 * @param {string} bookData.author - Author name (required)
 * @param {string} [bookData.genre] - Genre (defaults to "Unknown")
 * @param {number} [bookData.publishedYear] - Publication year
 * @param {number} [bookData.rating=0] - Rating from 1.0 to 5.0
 * @returns {Object} The newly created book object with assigned ID
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,
    title: bookData.title,
    author: bookData.author,
    genre: bookData.genre || "Unknown",
    publishedYear: bookData.publishedYear || null,
    rating: bookData.rating != null ? Number(bookData.rating) : 0
  };

  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by its ID. Performs a partial update — only the
 * fields provided in updateData are modified; all other fields remain unchanged.
 *
 * @param {number} id - The unique identifier of the book to update
 * @param {Object} updateData - Fields to update (partial object)
 * @returns {Object|null} The updated book object, or null if not found
 */
function updateBook(id, updateData) {
  const index = books.findIndex(book => book.id === Number(id));
  if (index === -1) return null;

  // Merge: keep existing values, override with provided ones
  books[index] = { ...books[index], ...updateData, id: Number(id) };
  return books[index];
}

/**
 * Deletes a book by its ID.
 *
 * @param {number} id - The unique identifier of the book to delete
 * @returns {boolean} True if the book was found and deleted, false otherwise
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === Number(id));
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Computes aggregate statistics across all books.
 *
 * @returns {Object} Statistics object containing:
 *   - totalBooks: number of books in the store
 *   - averageRating: mean rating rounded to 2 decimal places
 *   - genres: record mapping each genre to its book count
 *   - authors: record mapping each author to their book count
 *   - oldestYear: earliest publication year (null if no books)
 *   - newestYear: latest publication year (null if no books)
 */
function getStats() {
  const totalBooks = books.length;

  // Guard against empty dataset
  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      averageRating: 0,
      genres: {},
      authors: {},
      oldestYear: null,
      newestYear: null
    };
  }

  const averageRating = parseFloat(
    (books.reduce((sum, book) => sum + book.rating, 0) / totalBooks).toFixed(2)
  );

  // Build genre and author counts using reduce for O(n) single-pass aggregation
  const genres = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  const authors = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});

  const years = books.map(book => book.publishedYear).filter(y => y != null);
  const oldestYear = years.length ? Math.min(...years) : null;
  const newestYear = years.length ? Math.max(...years) : null;

  return { totalBooks, averageRating, genres, authors, oldestYear, newestYear };
}

// ---------------------------------------------------------------------------
// Module Exports — Using named exports for clarity and tree-shaking compatibility
// ---------------------------------------------------------------------------
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  books // Export the raw array for testing purposes only
};
```

> **Key Design Decisions:**
> - **Shallow copy on `getAllBooks`**: We return `[...books]` instead of the original array so callers can't accidentally mutate our internal state.
> - **Partial updates in `updateBook`**: Using `{ ...existing, ...updateData }` means clients only need to send the fields they want to change — a RESTful best practice.
> - **Auto-incrementing IDs**: Simple and collision-free for an in-memory store. In production, UUIDs or database auto-increment would be used.

