## File 3: `middleware/errors.js` — Custom Error Classes & Error Handler

```javascript
/**
 * @fileoverview Custom error classes and centralized error-handling middleware.
 *
 * WHY CUSTOM ERROR CLASSES? They allow us to distinguish between different
 * failure modes (not found, validation error, internal server error) so that
 * the error handler can return appropriate HTTP status codes and messages.
 *
 * WHY CENTRALIZED ERROR MIDDLEWARE? Express supports a special 4-argument
 * middleware function (err, req, res, next) that catches all errors — whether
 * thrown synchronously or passed via next(err). This avoids repeating try/catch
 * blocks in every route handler.
 */

// ---------------------------------------------------------------------------
// Custom Error Classes
// ---------------------------------------------------------------------------

/**
 * Base error class for all API errors. Extends the built-in Error class and
 * adds an HTTP status code so the response middleware can set the correct code.
 *
 * @extends {Error}
 */
class ApiError extends Error {
  /**
   * @param {number} statusCode - HTTP status code (e.g., 400, 404)
   * @param {string} message - Human-readable error description
   */
  constructor(statusCode, message) {
    super(message);
    this.statusCode = statusCode;

    // Capture the stack trace for debugging
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Represents a resource that was not found (HTTP 404).
 */
class NotFoundError extends ApiError {
  /**
   * @param {string} resourceName - Name of the resource (e.g., "Book")
   * @param {*} id - The ID that was requested
   */
  constructor(resourceName = "Resource", id) {
    super(404, `${resourceName} with id ${id} not found`);
    this.statusCode = 404;
  }
}

/**
 * Represents invalid input data (HTTP 400).
 */
class ValidationError extends ApiError {
  /**
   * @param {string|string[]} message - Error message or array of messages
   */
  constructor(message) {
    super(400, Array.isArray(message) ? message.join("; ") : message);
    this.statusCode = 400;
  }
}

/**
 * Represents an internal server error (HTTP 500).
 * In production, you would log the actual error details privately.
 */
class InternalError extends ApiError {
  constructor(message = "Internal server error") {
    super(500, message);
    this.statusCode = 500;
  }
}

// ---------------------------------------------------------------------------
// Error-Handling Middleware
// ---------------------------------------------------------------------------

/**
 * Centralized error-handling middleware. Must be registered AFTER all routes.
 * Express identifies it by its 4-parameter signature (err, req, res, next).
 *
 * @param {Error} err - The error object (any of our custom classes or a standard Error)
 * @param {import('express').Request} req - Express request object
 * @param {import('express').Response} res - Express response object
 * @param {import('express').NextFunction} next - Express next middleware function
 */
function errorHandler(err, req, res, next) {
  // Log the full error for server-side debugging (not sent to client)
  console.error(`[ERROR] ${new Date().toISOString()} — ${err.statusCode || 500}: ${err.message}`);
  if (process.env.NODE_ENV === "development" && err.stack) {
    console.error(err.stack);
  }

  // Build a consistent JSON error response shape
  const errorResponse = {
    success: false,
    error: {
      statusCode: err.statusCode || 500,
      message: err.message,
      // In development, include the stack trace for debugging
      ...(process.env.NODE_ENV === "development" && { stack: err.stack })
    }
  };

  // Set the appropriate HTTP status and send the JSON response
  res.status(errorResponse.error.statusCode).json(errorResponse);
}

// ---------------------------------------------------------------------------
// Module Exports
// ---------------------------------------------------------------------------
module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  InternalError,
  errorHandler
};
```

> **Key Design Decisions:**
> - **`ApiError` as base class**: All custom errors inherit from it, making it easy to check `err instanceof ApiError` if needed.
> - **Consistent error response shape**: Every error returns `{ success: false, error: { statusCode, message } }`, so clients can parse errors uniformly.
> - **Stack traces only in development**: We never leak internal details in production — a critical security practice.

