## File 4: `middleware/validate.js` — Request Validation Middleware

```javascript
/**
 * @fileoverview Request validation middleware for POST and PUT endpoints.
 *
 * WHY SEPARATE VALIDATION? Keeping validation logic separate from route handlers
 * makes the code more testable and reusable. It also keeps routes focused on
 * orchestration rather than data sanitization.
 */

const { ValidationError } = require("./errors");

// ---------------------------------------------------------------------------
// Validation Rules — Each rule is a function that returns an error message or null
// ---------------------------------------------------------------------------

/**
 * Validates that a string field is present and non-empty.
 *
 * @param {*} value - The value to validate
 * @param {string} fieldName - Name of the field (for error messages)
 * @returns {null|string} null if valid, error message string otherwise
 */
function requiredString(value, fieldName) {
  if (value == null || String(value).trim() === "") {
    return `${fieldName} is required`;
  }
  return null;
}

/**
 * Validates that a number is within the given range.
 *
 * @param {*} value - The value to validate
 * @param {string} fieldName - Name of the field (for error messages)
 * @param {number} min - Minimum allowed value
 * @param {number} max - Maximum allowed value
 * @returns {null|string} null if valid, error message string otherwise
 */
function rangeNumber(value, fieldName, min, max) {
  const num = Number(value);
  if (value != null && (isNaN(num) || num < min || num > max)) {
    return `${fieldName} must be a number between ${min} and ${max}`;
  }
  return null;
}

/**
 * Validates that a year is a reasonable publication year.
 *
 * @param {*} value - The value to validate
 * @returns {null|string} null if valid, error message string otherwise
 */
function validYear(value) {
  const num = Number(value);
  if (value != null && (isNaN(num) || num < 1000 || num > new Date().getFullYear() + 1)) {
    return "publishedYear must be a year between 1000 and current year";
  }
  return null;
}

// ---------------------------------------------------------------------------
// Route-Specific Validation Functions
// ---------------------------------------------------------------------------

/**
 * Validates the body of a POST /books request.
 * All required fields must be present and correctly typed.
 *
 * @param {import('express').Request} req - Express request object
 * @param {import('express').Response} res - Express response object
 * @param {import('express').NextFunction} next - Express next middleware function
 */
function validateCreateBook(req, res, next) {
  const errors = [];

  // Check required fields
  errors.push(requiredString(req.body.title, "Title"));
  errors.push(requiredString(req.body.author, "Author"));

  // Check optional numeric fields
  errors.push(rangeNumber(req.body.rating, "Rating", 1.0, 5.0));
  errors.push(validYear(req.body.publishedYear));

  // If any errors exist, throw a ValidationError with all messages
  const filteredErrors = errors.filter(Boolean);
  if (filteredErrors.length > 0) {
    return next(new ValidationError(filteredErrors));
  }

  // All validations passed — proceed to the route handler
  next();
}

/**
 * Validates the body of a PUT /books/:id request.
 * At least one updatable field must be provided.
 *
 * @param {import('express').Request} req - Express request object
 * @param {import('express').Response} res - Express response object
 * @param {import('express').NextFunction} next - Express next middleware function
 */
function validateUpdateBook(req, res, next) {
  const errors = [];
  const body = req.body;

  // At least one field must be provided for a meaningful update
  const hasAnyField = Object.keys(body).length > 0;
  if (!hasAnyField) {
    return next(new ValidationError("At least one field must be provided for update"));
  }

  // Validate each optional field only if it's present
  errors.push(requiredString(body.title, "Title"));
  errors.push(requiredString(body.author, "Author"));
  errors.push(rangeNumber(body.rating, "Rating", 1.0, 5.0));
  errors.push(validYear(body.publishedYear));

  const filteredErrors = errors.filter(Boolean);
  if (filteredErrors.length > 0) {
    return next(new ValidationError(filteredErrors));
  }

  next();
}

// ---------------------------------------------------------------------------
// Module Exports
// ---------------------------------------------------------------------------
module.exports = {
  validateCreateBook,
  validateUpdateBook
};
```

> **Key Design Decisions:**
> - **Validation returns error messages, not throws**: This lets us collect ALL validation errors at once and return them in a single response, rather than failing on the first error.
> - **`null` means valid**: Using `null` as the "no error" sentinel keeps the code clean — we filter out falsy values to get only actual errors.
> - **Partial update allowance**: PUT allows any subset of fields; we only validate fields that are actually present in the request body.

