## File 5: `routes/books.js` — Book Routes

```javascript
/**
 * @fileoverview REST API routes for book resources.
 *
 * WHY SEPARATE ROUTE FILE? Keeping routes in their own module makes the codebase
 * modular and easier to maintain. As the API grows, you'd have one route file
 * per resource (authors.js, genres.js, etc.).
 *
 * REST CONVENTIONS USED:
 *   GET    /books          — List all books (with optional query filters)
 *   GET    /books/:id      — Get a single book by ID
 *   POST   /books          — Create a new book
 *   PUT    /books/:id      — Fully update an existing book
 *   DELETE /books/:id      — Delete a book by ID
 *
 * HTTP STATUS CODES:
 *   200 OK        — Successful GET/PUT
 *   201 Created   — Successful POST (resource created)
 *   204 No Content— Successful DELETE (no body to return)
 *   400 Bad Request — Validation error
 *   404 Not Found — Resource doesn't exist
 *   500 Internal Error — Server-side failure
 */

const express = require("express");
const router = express.Router(); // Creates a standalone route handler

// Import our data model and middleware
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
} = require("../models/books");

const { NotFoundError } = require("../middleware/errors");
const { validateCreateBook, validateUpdateBook } = require("../middleware/validate");

// ---------------------------------------------------------------------------
// GET /books — List all books with optional filtering
// ---------------------------------------------------------------------------
/**
 * @name GET /books
 * @description Returns a list of all books. Supports query parameter filtering.
 *
 * @query {string} [author] - Filter by author name (partial, case-insensitive)
 * @query {string} [genre]  - Filter by genre (exact match)
 * @query {number} [minRating] - Minimum rating threshold (1.0–5.0)
 * @query {number} [publishedYear] - Exact publication year filter
 *
 * @response 200 — Array of book objects
 * @response 400 — Bad request (invalid query parameters)
 *
 * @example curl "http://localhost:3000/books?genre=Fiction&minRating=4.5"
 */
router.get("/books", (req, res) => {
  // Extract filter parameters from the query string; default to empty object
  const filters = {
    author: req.query.author,
    genre: req.query.genre,
    minRating: req.query.minRating,
    publishedYear: req.query.publishedYear
  };

  // Filter out undefined values so the model only applies provided filters
  const cleanFilters = Object.fromEntries(
    Object.entries(filters).filter(([, v]) => v !== undefined && v !== "")
  );

  const result = getAllBooks(cleanFilters);

  res.json({
    success: true,
    count: result.length,
    data: result
  });
});

// ---------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
// ---------------------------------------------------------------------------
/**
 * @name GET /books/:id
 * @description Returns a single book object by its numeric ID.
 *
 * @param {number} id - The book's unique identifier (URL parameter)
 *
 * @response 200 — Book object
 * @response 404 — Book not found
 *
 * @example curl "http://localhost:3000/books/1"
 */
router.get("/books/:id", (req, res) => {
  const book = getBookById(req.params.id);

  if (!book) {
    // Throw NotFoundError — caught by the centralized error handler
    throw new NotFoundError("Book", req.params.id);
  }

  res.json({ success: true, data: book });
});

// ---------------------------------------------------------------------------
// POST /books — Create a new book
// ---------------------------------------------------------------------------
/**
 * @name POST /books
 * @description Creates a new book and returns it with a 201 status.
 *
 * @body {string} title       - Book title (required)
 * @body {string} author      - Author name (required)
 * @body {string} [genre]     - Genre (defaults to "Unknown")
 * @body {number} [publishedYear] - Publication year
 * @body {number} [rating=0]  - Rating from 1.0 to 5.0
 *
 * @response 201 — Created book object
 * @response 400 — Validation error
 *
 * @example curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","publishedYear":1949,"rating":4.7}'
 */
router.post("/books", validateCreateBook, (req, res) => {
  const newBook = createBook(req.body);

  // 201 Created is the standard status for resource creation
  res.status(201).json({ success: true, data: newBook });
});

// ---------------------------------------------------------------------------
// PUT /books/:id — Update an existing book
// ---------------------------------------------------------------------------
/**
 * @name PUT /books/:id
 * @description Partially updates a book by ID. Only provided fields are changed.
 *
 * @param {number} id - The book's unique identifier (URL parameter)
 * @body {string} [title]       - New title
 * @body {string} [author]      - New author
 * @body {string} [genre]       - New genre
 * @body {number} [publishedYear] - New publication year
 * @body {number} [rating]      - New rating (1.0–5.0)
 *
 * @response 200 — Updated book object
 * @response 400 — Validation error
 * @response 404 — Book not found
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"rating":4.9}'
 */
router.put("/books/:id", validateUpdateBook, (req, res) => {
  const updatedBook = updateBook(req.params.id, req.body);

  if (!updatedBook) {
    throw new NotFoundError("Book", req.params.id);
  }

  res.json({ success: true, data: updatedBook });
});

// ---------------------------------------------------------------------------
// DELETE /books/:id — Delete a book
// ---------------------------------------------------------------------------
/**
 * @name DELETE /books/:id
 * @description Deletes a book by its ID. Returns 204 No Content on success.
 *
 * @param {number} id - The book's unique identifier (URL parameter)
 *
 * @response 204 — Successfully deleted (no body)
 * @response 404 — Book not found
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete("/books/:id", (req, res) => {
  const deleted = deleteBook(req.params.id);

  if (!deleted) {
    throw new NotFoundError("Book", req.params.id);
  }

  // 204 No Content is the standard status for successful deletion
  res.status(204).end();
});

// ---------------------------------------------------------------------------
// GET /stats — Return aggregate statistics
// ---------------------------------------------------------------------------
/**
 * @name GET /stats
 * @description Returns aggregate statistics about all books in the store.
 *
 * @response 200 — Statistics object containing totalBooks, averageRating,
 *                 genres, authors, oldestYear, and newestYear
 *
 * @example curl "http://localhost:3000/stats"
 */
router.get("/stats", (req, res) => {
  const stats = getStats();
  res.json({ success: true, data: stats });
});

// ---------------------------------------------------------------------------
// Module Export — Attach the router to the Express app
// ---------------------------------------------------------------------------
module.exports = router;
```

> **Key Design Decisions:**
> - **`express.Router()`**: Creates a modular route handler that can be mounted anywhere in the app. This is the standard Express pattern for organizing routes.
> - **Middleware before handlers**: `validateCreateBook` and `validateUpdateBook` run before the route logic, ensuring invalid requests never reach the model layer.
> - **Consistent response shape**: Every successful response wraps data in `{ success: true, data: ... }`, making client-side parsing predictable.
> - **`throw` instead of manual error handling**: In Express, throwing inside a route handler (or passing `err` to `next()`) is caught by the error-handling middleware — this keeps route code clean.

