## File 6: `server.js` — Application Entry Point

```javascript
/**
 * @fileoverview Main application entry point.
 *
 * This file wires together Express, middleware, routes, and error handling.
 * It is intentionally minimal — all business logic lives in separate modules.
 */

const express = require("express");

// Import our modular components
const bookRoutes = require("./routes/books");
const { errorHandler } = require("./middleware/errors");

// ---------------------------------------------------------------------------
// Application Setup
// ---------------------------------------------------------------------------

/** @type {import('express').Express} Express application instance */
const app = express();

/** Port number — defaults to 3000, can be overridden via environment variable */
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// Middleware Registration
// ---------------------------------------------------------------------------

/**
 * Built-in middleware: parses JSON request bodies.
 * Enables req.body to contain parsed JSON data from POST/PUT requests.
 */
app.use(express.json());

/**
 * Built-in middleware: logs every incoming request to the console.
 * Useful for debugging and monitoring in development.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler
});

// ---------------------------------------------------------------------------
// Route Registration
// ---------------------------------------------------------------------------

/**
 * Mount the book routes at the /api/v1 prefix.
 * Using a versioned API path (/api/v1/) is a best practice that allows
 * future backward-compatible changes (e.g., /api/v2/).
 */
app.use("/api/v1", bookRoutes);

// ---------------------------------------------------------------------------
// Root Endpoint — Health check
// ---------------------------------------------------------------------------
/**
 * @name GET /
 * @description Simple health-check endpoint to verify the server is running.
 *
 * @response 200 — JSON with server status and uptime information
 */
app.get("/", (req, res) => {
  res.json({
    success: true,
    message: "Book REST API is running",
    version: "1.0.0",
    endpoints: {
      books: "GET /api/v1/books, GET /api/v1/books/:id, POST /api/v1/books, PUT /api/v1/books/:id, DELETE /api/v1/books/:id",
      stats: "GET /api/v1/stats"
    }
  });
});

// ---------------------------------------------------------------------------
// 404 Handler — Catch-all for undefined routes
// ---------------------------------------------------------------------------
/**
 * Any request that doesn't match a registered route falls through to here.
 * We throw a NotFoundError so the centralized error handler formats the response.
 */
app.use((req, res, next) => {
  const { NotFoundError } = require("./middleware/errors");
  next(new NotFoundError("Endpoint", `${req.method} ${req.url}`));
});

// ---------------------------------------------------------------------------
// Centralized Error Handler — MUST be last middleware
// ---------------------------------------------------------------------------
/**
 * Express identifies error-handling middleware by its 4-parameter signature.
 * This catches errors from anywhere in the app (routes, middleware, etc.).
 */
app.use(errorHandler);

// ---------------------------------------------------------------------------
// Start the Server
// ---------------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`\n========================================`);
  console.log(`  Book REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || "development"}`);
  console.log(`  Base URL: http://localhost:${PORT}`);
  console.log(`========================================\n`);
});

module.exports = app; // Export for testing
```

> **Key Design Decisions:**
> - **Versioned API path (`/api/v1`)**: Allows future API versions without breaking existing clients.
> - **404 catch-all**: Any unmatched route returns a proper 404 JSON response instead of Express's default HTML page.
> - **Error handler last**: In Express, middleware order matters. The error handler must be registered after all routes so it can catch errors from anywhere.
> - **Export `app`**: Exporting the app instance allows unit testing with tools like Supertest without starting an actual HTTP server.

