## Arquivo 2: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE UM ARQUIVO SEPARADO?
 * -----------------------------
 * O middleware de erros é uma camada transversal que precisa ser acessível
 * de qualquer parte da aplicação. Isolá-lo em um arquivo próprio permite:
 *   1. Reutilização em múltiplos pontos (app-level e route-level)
 *   2. Centralização da lógica de formatação de respostas de erro
 *   3. Facilidade para adicionar logging, métricas ou notificações no futuro
 *
 * PADRÃO DO MIDDLEWARE DE ERROS NO EXPRESS:
 * ------------------------------------------
 * Express identifica middlewares de erro pela assinatura de 4 parâmetros:
 *   (error, req, res, next) => {}
 * Se um middleware tiver apenas 3 parâmetros, o Express o trata como normal.
 * Os 4 parâmetros são obrigatórios para que o framework saiba que é um
 * handler de erro — isso é parte da convenção interna do Express.
 *
 * CLASSES DE ERRO PERSONALIZADAS:
 * --------------------------------
 * Criamos subclasses de Error para categorizar falhas semanticamente. Isso
 * permite que o middleware de erros tome decisões diferentes com base no
 * tipo de erro (ex: 404 para NotFoundError, 400 para ValidationError).
 * Sem classes personalizadas, teríamos que inspecionar strings de mensagem,
 * o que é frágil e propenso a bugs.
 */

// ----------------------------------------------------------------------------
// CLASSE BASE: ApiError
// ----------------------------------------------------------------------------
//
// POR QUE EXTENDER Error?
// ------------------------
// A classe nativa Error do JavaScript já possui propriedades úteis como
// 'message' e 'stack'. Ao estendê-la, herdamos automaticamente o comportamento
// de empilhamento de stack trace, que é essencial para debugging.
//
// O campo 'statusCode' é adicionado manualmente porque a classe Error nativa
// não o possui — ele carrega o código HTTP que deve ser retornado ao cliente.
//
// O campo 'isOperational' distingue erros previsíveis (ex: usuário envia ID
// inválido) de erros imprevisíveis do sistema (bugs, falhas de banco). Erros
// operacionais não devem ser logados em produção para não expor informações
// sensíveis.

class ApiError extends Error {
  /**
   * @param {string} message - Descrição legível do erro para o cliente
   * @param {number} statusCode - Código HTTP correspondente (ex: 400, 404)
   * @param {boolean} [isOperational=true] - Se true, é um erro esperado; se false, bug do sistema
   */
  constructor(message, statusCode, isOperational = true) {
    super(message); // Chama o construtor da classe pai (Error)

    this.statusCode = statusCode;
    this.isOperational = isOperational;

    // Captura o stack trace no momento da criação do erro.
    // Error.captureStackTrace remove a própria linha do construtor do stack,
    // deixando o trace mais limpo e direto ao ponto.
    Error.captureStackTrace(this, this.constructor);
  }
}

// ----------------------------------------------------------------------------
// SUBCLASSES DE ERRO ESPECÍFICAS
// ----------------------------------------------------------------------------
//
// Cada subclasse encapsula um tipo específico de falha. Isso torna o código
// mais legível e permite que middlewares tratem cada caso de forma granular.
// Note que todas herdam de ApiError, mantendo a consistência na estrutura.

/** Erro quando um recurso solicitado não é encontrado */
class NotFoundError extends ApiError {
  constructor(resource) {
    // 'resource' é o nome do recurso (ex: "Livro") para mensagens dinâmicas
    super(`${resource} não encontrado`, 404);
  }
}

/** Erro quando os dados enviados pelo cliente são inválidos */
class ValidationError extends ApiError {
  constructor(message) {
    super(message, 400);
  }
}

/** Erro para operações não implementadas ainda */
class NotImplentedError extends ApiError {
  constructor() {
    super('Recurso ainda não implementado', 501);
  }
}

// ----------------------------------------------------------------------------
// MIDDLEWARE PRINCIPAL DE TRATAMENTO DE ERROS
// ----------------------------------------------------------------------------
//
 * POR QUE COLOCAR ESTE MIDDLEWARE POR ÚLTIMO?
 * --------------------------------------------
 * No Express, middlewares são executados em ordem FIFO (First In, First Out).
 * O middleware de erros DEVE ser o último registrado porque ele captura
 * erros que passaram por todos os outros middlewares e rotas sem serem
 * tratados. Se colocado no início, ele interceptaria tudo e nenhum outro
 * middleware funcionaria.
 *
 * A assinatura (error, req, res, next) com 4 parâmetros é o que identifica
 * este middleware como handler de erros para o Express.
 *
 * O try/catch dentro da função de rota é uma prática recomendada porque
 * middlewares de erro do Express NÃO capturam rejeições de Promises
 * automaticamente. Sem o try/catch, um async/await com erro não seria
 * interceptado pelo middleware de erros — a aplicação simplesmente
 * retornaria um erro 500 genérico ou travaria.

/**
 * Middleware central de tratamento de erros.
 *
 * Este middleware é chamado sempre que:
 *   1. Uma rota lança um erro síncrono
 *   2. Uma Promise é rejeitada e o erro é passado para next(err)
 *   3. Um middleware anterior chama next(err) explicitamente
 *
 * @param {Error} error - A instância de erro lançada
 * @param {import('express').Request} req - Objeto de requisição do Express
 * @param {import('express').Response} res - Objeto de resposta do Express
 * @param {import('express').NextFunction} next - Função para encadear middlewares
 */
const errorHandler = (error, req, res, next) => {
  // Determina o status code: usa o da instância ApiError ou padrão 500
  const statusCode = error.statusCode || 500;

  // Em desenvolvimento, retornamos o stack trace completo para facilitar debugging.
  // Em produção, ocultamos o stack para não expor detalhes internos da aplicação.
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Monta a resposta de erro padronizada
  const errorResponse = {
    success: false,
    statusCode,
    message: error.message,
    // Stack trace apenas em desenvolvimento (segurança)
    ...(isDevelopment && { stack: error.stack }),
    // Timestamp para rastreamento em logs
    timestamp: new Date().toISOString(),
  };

  // Log do erro no servidor (sempre, independente do ambiente)
  // Em produção, envie isso para um serviço como Sentry ou ELK Stack
  if (error.isOperational) {
    // Erros operacionais são esperados — log apenas o essencial
    console.warn(`[Operacional] ${statusCode} - ${error.message}`);
  } else {
    // Erros não-operacionais são bugs reais — log completo com stack
    console.error(`[BUG] ${statusCode} - ${error.message}`, error.stack);
  }

  // Envia a resposta JSON padronizada
  res.status(statusCode).json(errorResponse);
};

// ----------------------------------------------------------------------------
// EXPORTAÇÕES
// ----------------------------------------------------------------------------
module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  NotImplentedError,
  errorHandler,
};
```

