## Arquivo 3: `src/store/books.js`

```javascript
/**
 * ============================================================================
 * ARMAZENAMENTO EM MEMÓRIA (IN-MEMORY STORE)
 * ============================================================================
 *
 * POR QUE USAR UM ARRAY?
 * -----------------------
 * Arrays são a estrutura de dados mais natural para uma lista ordenada de
 * itens com IDs sequenciais. Eles oferecem:
 *   - Acesso por índice em O(1)
 *   - Métodos nativos poderosos (filter, map, findIndex, splice)
 *   - Serialização trivial para JSON
 *
 * POR QUE NÃO USAR UM OBJETO PLANO?
 * ----------------------------------
 * Objetos JavaScript têm chaves que são strings, o que exigiria conversão
 * constante de IDs numéricos. Arrays mantêm a tipagem forte dos IDs e
 * preservam a ordem de inserção — importante para listagens.
 *
 * POR QUE NÃO USAR MAP()?
 * ------------------------
 * Map() seria eficiente para buscas por ID (O(1)), mas perderíamos a
 * ordenação natural e teríamos que sincronizar duas estruturas (array + map).
 * Para uma API educacional com poucos registros, array é mais simples e
 * legível. Em produção com milhares de registros, um Map ou banco de dados
 * seria preferível.
 *
 * POR QUE NÃO USAR BANCO DE DADOS?
 * ---------------------------------
 * Este é um exemplo educacional. Bancos de dados introduzem complexidade
 * (conexões, migrations, queries) que desviam o foco dos conceitos de API
 * REST. Um array em memória permite testar todos os endpoints CRUD
 * imediatamente sem infraestrutura adicional.
 *
 * LIMITAÇÕES DESTA ABORDAGEM:
 * ----------------------------
 *   - Dados são perdidos ao reiniciar o servidor (não há persistência)
 *   - Não escala para múltiplas instâncias (cada processo tem seu próprio array)
 *   - Buscas por campo não-ID exigem varredura O(n)
 *
 * Para superar essas limitações, substitua este store por MongoDB, PostgreSQL
 * ou Redis em uma implementação de produção.
 */

// ----------------------------------------------------------------------------
// DADOS INICIAIS (SEED DATA)
// ----------------------------------------------------------------------------
//
 * Populamos o array com alguns livros para que a API já venha com dados
 * para testar imediatamente, sem precisar criar registros manualmente.
 * Isso é especialmente útil para testar GET /books e GET /stats.

/**
 * Lista inicial de livros para popular o store.
 * Cada livro possui: id (numérico), title, author, year (número), genre.
 *
 * Exemplo de uso com curl:
 *   curl http://localhost:3000/books
 */
const books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    year: 1954,
    genre: 'Fantasia',
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    year: 1949,
    genre: 'Distopia',
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    year: 1899,
    genre: 'Romance',
  },
  {
    id: 4,
    title: 'O Pequeno Príncipe',
    author: 'Antoine de Saint-Exupéry',
    year: 1943,
    genre: 'Fábula',
  },
];

// ----------------------------------------------------------------------------
// FUNÇÕES DO STORE
// ----------------------------------------------------------------------------
//
 * Cada função opera diretamente sobre o array `books`. Em uma aplicação
 * real, estas funções fariam chamadas assíncronas a um banco de dados.
 * Aqui, mantemos síncronas para simplicidade — arrays permitem operações
 * síncronas sem complicar o código com Promises desnecessárias.

/**
 * Retorna todos os livros armazenados.
 * @returns {Array<Object>} Lista completa de livros
 */
const getAllBooks = () => books;

/**
 * Busca um livro pelo ID numérico.
 * Usa findIndex para encontrar o índice do livro com o ID correspondente.
 * Se não encontrado, retorna -1 (comportamento padrão do findIndex).
 *
 * @param {number} id - ID numérico do livro
 * @returns {Object|null} Livro encontrado ou null se não existir
 */
const getBookById = (id) => {
  const index = books.findIndex((book) => book.id === id);
  return index !== -1 ? books[index] : null;
};

/**
 * Adiciona um novo livro ao array.
 * O ID é gerado automaticamente como o maior ID existente + 1, garantindo
 * unicidade sem necessidade de UUIDs ou sequenciadores externos.
 *
 * @param {Object} bookData - Dados do novo livro (sem id)
 * @returns {Object} O livro criado com ID atribuído
 */
const createBook = (bookData) => {
  // Gera o próximo ID: máximo atual + 1, ou 1 se o array estiver vazio
  const nextId = books.length > 0 ? Math.max(...books.map((b) => b.id)) + 1 : 1;

  const newBook = { id: nextId, ...bookData };
  books.push(newBook); // push adiciona ao final do array e retorna o novo comprimento
  return newBook;
};

/**
 * Atualiza um livro existente pelo ID.
 * Se o livro não existir, retorna null.
 * Usa spread operator (...) para mesclar os dados antigos com os novos,
 * preservando campos que não foram enviados na atualização (partial update).
 *
 * @param {number} id - ID do livro a atualizar
 * @param {Object} updates - Campos a atualizar
 * @returns {Object|null} Livro atualizado ou null se não encontrado
 */
const updateBook = (id, updates) => {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Mescla dados existentes com atualizações (atualização parcial)
  books[index] = { ...books[index], ...updates };
  return books[index];
};

/**
 * Remove um livro pelo ID.
 * Usa splice para remover o elemento no índice encontrado, mantendo a
 * integridade do array. Retorna true se removido, false caso contrário.
 *
 * @param {number} id - ID do livro a remover
 * @returns {boolean} True se removido com sucesso, false caso contrário
 */
const deleteBook = (id) => {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove 1 elemento na posição index
  return true;
};

// ----------------------------------------------------------------------------
// EXPORTAÇÕES
// ----------------------------------------------------------------------------
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
};
