/**
 * ============================================================================
 * ROTAS DE LIVROS (CRUD COMPLETO)
 * ============================================================================
 *
 * POR QUE UM ARQUIVO DE ROTAS SEPARADO?
 * --------------------------------------
 * Separar rotas em arquivos distintos segue o princípio de responsabilidade
 * única: cada módulo é responsável por um domínio específico. Isso permite:
 *   - Escalar adicionando novos módulos de rota sem modificar o app principal
 *   - Testar rotas isoladamente (unit tests)
 *   - Manter o código legível e navegável
 *
 * PADRÃO REST PARA ESTAS ROTAS:
 * ------------------------------
 *   GET    /books          → Listar todos (com filtragem opcional)
 *   GET    /books/:id      → Obter um específico
 *   POST   /books          → Criar novo recurso
 *   PUT    /books/:id      → Atualizar completamente (substituir)
 *   DELETE /books/:id      → Remover recurso
 *
 * Por que PUT e não PATCH? PUT substitui o recurso inteiro. Se o cliente
 * enviar apenas { "title": "Novo Título" }, os outros campos são perdidos.
 * Para atualizações parciais, usaríamos PATCH — mas para este exemplo
 * educacional, PUT é mais simples de demonstrar.
 *
 * CONVENÇÕES DE NOMENCLATURA:
 * ----------------------------
 *   - Métodos HTTP em MAIÚSCULAS (GET, POST, etc.) — padrão RFC 7231
 *   - URLs em kebab-case (/books) — padrão da web
 *   - Parâmetros de rota com :prefixo (:id) — convenção do Express
 */

const express = require('express');
const router = express.Router(); // Cria um roteador independente

// Importa o store e as classes de erro
const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require('../store/books');
const { ApiError, NotFoundError, ValidationError } = require('../middleware/errorHandler');

// ----------------------------------------------------------------------------
// VALIDAÇÃO DE ENTRADA (INPUT VALIDATION)
// ----------------------------------------------------------------------------
//
 * POR QUE VALIDAR INPUTS?
 * ------------------------
 * Validação de entrada é a primeira linha de defesa contra:
 *   - Dados malformados que quebrariam o sistema
 *   - Injeções (embora menos comum em JSON, ainda é relevante)
 *   - Lógica de negócio incorreta por dados ausentes ou inválidos
 *
 * Em uma aplicação real, usaríamos bibliotecas como Joi, Zod ou Yup para
 * schemas declarativos. Aqui, validamos manualmente para demonstrar o
 * conceito sem dependências extras.
 *
 * A função validateBookData é chamada antes de criar ou atualizar livros,
 * garantindo que todos os campos obrigatórios estejam presentes e com
 * tipos corretos.

/**
 * Valida os dados de um livro antes de criá-lo ou atualizá-lo.
 *
 * Regras de validação:
 *   - title: string não vazia (mínimo 1 caractere)
 *   - author: string não vazia
 *   - year: número inteiro entre 0 e o ano atual + 1
 *   - genre: string não vazia
 *
 * @param {Object} data - Dados a validar
 * @throws {ValidationError} Se alguma validação falhar
 */
const validateBookData = (data) => {
  const errors = [];

  // Valida título: deve ser string e não vazio
  if (!data.title || typeof data.title !== 'string' || data.title.trim().length === 0) {
    errors.push('O campo "title" é obrigatório e deve ser uma string não vazia');
  }

  // Valida autor: deve ser string e não vazio
  if (!data.author || typeof data.author !== 'string' || data.author.trim().length === 0) {
    errors.push('O campo "author" é obrigatório e deve ser uma string não vazia');
  }

  // Valida ano: deve ser número inteiro dentro de um intervalo razoável
  if (data.year === undefined || data.year === null) {
    errors.push('O campo "year" é obrigatório');
  } else if (!Number.isInteger(data.year)) {
    errors.push('O campo "year" deve ser um número inteiro');
  } else if (data.year < 0 || data.year > new Date().getFullYear() + 1) {
    errors.push(`O campo "year" deve estar entre 0 e ${new Date().getFullYear() + 1}`);
  }

  // Valida gênero: deve ser string e não vazio
  if (!data.genre || typeof data.genre !== 'string' || data.genre.trim().length === 0) {
    errors.push('O campo "genre" é obrigatório e deve ser uma string não vazia');
  }

  // Se houver erros, lança ValidationError com a lista de problemas
  if (errors.length > 0) {
    throw new ValidationError(errors.join('; '));
