// ----------------------------------------------------------------------------
// GET /books — LISTAR TODOS OS LIVROS COM FILTRAGEM
// ----------------------------------------------------------------------------
//
 * A filtragem é implementada via query parameters (parâmetros de consulta):
 *   - ?author=nome     → filtra por autor (case-insensitive)
 *   - ?genre=gênero    → filtra por gênero (case-insensitive)
 *   - ?year=2024       → filtra por ano exato
 *   - ?title=parte     → busca parcial no título
 *
 * POR QUE QUERY PARAMETERS E NÃO PARÂMETROS DE ROTA?
 * ---------------------------------------------------
 * Query parameters são ideais para filtragem porque:
 *   1. São opcionais — a URL base permanece válida sem eles
 *   2. Podem ser combinados livremente (author=X&genre=Y)
 *   3. Seguem o padrão REST de recursos identificáveis por URL e filtráveis
 *      por query strings
 *
 * A conversão para lowercase (.toLowerCase()) permite buscas case-insensitive,
 * melhorando a experiência do usuário que pode digitar "fantasia" ou "FANTASIA".

/**
 * Lista todos os livros com suporte a filtragem opcional.
 *
 * Query parameters suportados:
 *   - author  → filtra por autor (parcial, case-insensitive)
 *   - genre   → filtra por gênero (exato, case-insensitive)
 *   - year    → filtra por ano exato
 *   - title   → busca parcial no título (case-insensitive)
 *
 * @example
 * // curl http://localhost:3000/books
 * // curl "http://localhost:3000/books?genre=fantasia"
 * // curl "http://localhost:3000/books?author=tolkien&year=1954"
 *
 * @param {import('express').Request} req - Requisição com query parameters
 * @param {import('express').Response} res - Resposta JSON
 * @param {import('express').NextFunction} next - Encadeamento de middleware
 */
router.get('/books', (req, res, next) => {
  try {
    // Obtém todos os livros do store
    let result = getAllBooks();

    // Aplica filtros apenas se os query parameters forem fornecidos
    const { author, genre, year, title } = req.query;

    if (author) {
      // Filtra por autor: converte ambos para lowercase para comparação case-insensitive
      result = result.filter((book) =>
        book.author.toLowerCase().includes(author.toLowerCase())
      );
    }

    if (genre) {
      // Filtra por gênero exato (case-insensitive)
      result = result.filter((book) => book.genre.toLowerCase() === genre.toLowerCase());
    }

    if (year) {
      // Converte para número e filtra por ano exato
      const yearNum = parseInt(year, 10);
      if (!isNaN(yearNum)) {
        result = result.filter((book) => book.year === yearNum);
      }
    }

    if (title) {
      // Busca parcial no título (case-insensitive)
      result = result.filter((book) =>
        book.title.toLowerCase().includes(title.toLowerCase())
      );
    }

    // Retorna a lista filtrada com metadados de paginação (futuro)
    res.json({
      success: true,
      count: result.length,
      total: getAllBooks().length,
      data: result,
    });
  } catch (error) {
    next(error); // Passa o erro para o middleware de tratamento de erros
  }
});

// ----------------------------------------------------------------------------
// GET /books/:id — OBTER LIVRO POR ID
// ----------------------------------------------------------------------------
//
 * O parâmetro :id é extraído automaticamente pelo Express e disponibilizado
 * em req.params.id. Como vem como string, convertemos para número com
 * parseInt antes de buscar no store.
 *
 * Se o livro não for encontrado, lançamos NotFoundError em vez de retornar
 * null silenciosamente — isso garante que o middleware de erros formate
 * uma resposta padronizada e logue o evento adequadamente.

/**
 * Busca um livro específico pelo ID.
 *
 * @example
 * // curl http://localhost:3000/books/1
 * // curl http://localhost:3000/books/999  → retorna 404
 *
 * @param {import('express').Request} req - Requisição com params.id
 * @param {import('express').Response} res - Resposta JSON
 * @param {import('express').NextFunction} next - Encadeamento de middleware
 */
router.get('/books/:id', (req, res, next) => {
  try {
    // Converte ID de string para número
    const id = parseInt(req.params.id, 10);

    // Valida se o ID é um número válido
    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número válido');
    }

    const book = getBookById(id);

    // Se não encontrado, lança NotFoundError para tratamento padronizado
    if (!book) {
      throw new NotFoundError('Livro');
    }

    res.json({ success: true, data: book });
  } catch (error) {
    next(error);
  }
});

// ----------------------------------------------------------------------------
// POST /books — CRIAR NOVO LIVRO
// ----------------------------------------------------------------------------
//
 * POST é o método HTTP semântico para criar recursos. Diferente de GET (que
 * não deve ter efeito colateral), POST cria um novo recurso no servidor.
 *
 * O corpo da requisição (req.body) contém os dados enviados pelo cliente em
 * JSON. Precisamos garantir que o body-parser do Express esteja configurado
 * (feito em app.js).
 *
 * A validação é feita ANTES de persistir os dados, seguindo o princípio de
 * "fail fast" — falhar o mais cedo possível para evitar processamento
 * desnecessário.

/**
 * Cria um novo livro a partir dos dados enviados no corpo da requisição.
 *
 * Corpo esperado (JSON):
