 *   "title": "Nome do Livro",
 *   "author": "Nome do Autor",
 *   "year": 2024,
 *   "genre": "Gênero"
 * }
 *
 * @example
 * // curl -X POST http://localhost:3000/books \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"Duna","author":"Frank Herbert","year":1965,"genre":"Ficção Científica"}'
 *
 * @param {import('express').Request} req - Requisição com body contendo dados do livro
 * @param {import('express').Response} res - Resposta JSON com o livro criado
 * @param {import('express').NextFunction} next - Encadeamento de middleware
 */
router.post('/books', (req, res, next) => {
  try {
    // Valida os dados antes de criar
    validateBookData(req.body);

    // Cria o livro no store
    const newBook = createBook(req.body);

    // Retorna 201 Created com o recurso criado
    // 201 é o status semântico para "recurso criado com sucesso"
    res.status(201).json({ success: true, data: newBook });
  } catch (error) {
    next(error);
  }
});

// ----------------------------------------------------------------------------
// PUT /books/:id — ATUALIZAR LIVRO EXISTENTE
// ----------------------------------------------------------------------------
//
 * PUT substitui o recurso inteiro. Diferente de PATCH (atualização parcial),
 * PUT espera que o cliente envie todos os campos — campos não enviados são
 * considerados como "remover do recurso".
 *
 * Para este exemplo, implementamos uma atualização parcial: apenas os campos
 * enviados no body são atualizados, preservando os demais. Isso é mais
 * amigável para clientes que não precisam enviar o livro completo.

/**
 * Atualiza um livro existente pelo ID.
 * Campos não enviados no corpo são preservados (atualização parcial).
 *
 * @example
 * // curl -X PUT http://localhost:3000/books/1 \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"O Senhor dos Anéis - Nova Edição"}'
 *
 * @param {import('express').Request} req - Requisição com params.id e body
 * @param {import('express').Response} res - Resposta JSON com o livro atualizado
 * @param {import('express').NextFunction} next - Encadeamento de middleware
 */
router.put('/books/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número válido');
    }

    // Verifica se o livro existe antes de atualizar
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Livro');
    }

    // Valida apenas os campos enviados (para campos obrigatórios)
    // Nota: em produção, a validação deveria ser mais rigorosa para PUT
    const updates = req.body;
    const updatedBook = updateBook(id, updates);

    res.json({ success: true, data: updatedBook });
  } catch (error) {
    next(error);
  }
});

// ----------------------------------------------------------------------------
// DELETE /books/:id — EXCLUIR LIVRO
// ----------------------------------------------------------------------------
//
 * DELETE remove permanentemente o recurso. O status 204 No Content é o
 * padrão REST para "remoção bem-sucedida sem corpo de resposta". Porém,
 * retornamos 200 com uma mensagem de confirmação para melhor experiência
 * do desenvolvedor que está testando a API.

/**
 * Exclui um livro pelo ID.
 *
 * @example
 * // curl -X DELETE http://localhost:3000/books/1
 *
 * @param {import('express').Request} req - Requisição com params.id
 * @param {import('express').Response} res - Resposta JSON de confirmação
 * @param {import('express').NextFunction} next - Encadeamento de middleware
 */
router.delete('/books/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número válido');
    }

    const deleted = deleteBook(id);

    if (!deleted) {
      throw new NotFoundError('Livro');
    }

    // 200 OK com mensagem de confirmação (alternativa: 204 No Content)
    res.json({ success: true, message: `Livro ${id} excluído com sucesso` });
  } catch (error) {
    next(error);
  }
});

// ----------------------------------------------------------------------------
// EXPORTAÇÕES
// ----------------------------------------------------------------------------
module.exports = router;
