```javascript
/**
 * ============================================================================
 * ROTAS DE ESTATÍSTICAS
 * ============================================================================
 *
 * A rota GET /stats demonstra como criar endpoints que não são puramente
 * CRUD — eles calculam e agregam dados. Isso é comum em APIs reais para
 * dashboards, métricas de negócio e monitoramento.
 *
 * As estatísticas retornadas incluem:
 *   - totalBooks: quantidade total de livros
 *   - totalAuthors: quantidade de autores únicos
 *   - genres: distribuição por gênero (quantidade por gênero)
 *   - oldestBook / newestBook: extremos temporais
 *   - averageYear: ano médio de publicação
 */

const express = require('express');
const router = express.Router();
const { getAllBooks } = require('../store/books');

/**
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * @example
 * // curl http://localhost:3000/stats
 * // Resposta:
 * // {
 * //   "success": true,
 * //   "data": {
 * //     "totalBooks": 4,
 * //     "totalAuthors": 4,
 * //     "genres": { "Fantasia": 1, "Distopia": 1, ... },
 * //     "oldestBook": { "title": "...", "year": 1899 },
 * //     "newestBook": { "title": "...", "year": 1965 },
 * //     "averageYear": 1930
 * //   }
 * // }
 *
 * @param {import('express').Request} req - Requisição
 * @param {import('express').Response} res - Resposta JSON
 */
router.get('/stats', (req, res) => {
  const books = getAllBooks();

  if (books.length === 0) {
    return res.json({ success: true, data: { totalBooks: 0 } });
  }

  // Calcula autores únicos usando Set (estrutura que elimina duplicatas)
  const uniqueAuthors = new Set(books.map((book) => book.author)).size;

  // Conta ocorrências por gênero
  const genres = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Encontra livro mais antigo e mais recente
  const oldest = books.reduce((min, book) => (book.year < min.year ? book : min), books[0]);
  const newest = books.reduce((max, book) => (book.year > max.year ? book : max), books[0]);

  // Calcula ano médio (arredondado)
  const averageYear = Math.round(books.reduce((sum, book) => sum + book.year, 0) / books.length);

  res.json({
    success: true,
    data: {
      totalBooks: books.length,
      totalAuthors: uniqueAuthors,
      genres,
      oldestBook: { title: oldest.title, author: oldest.author, year: oldest.year },
      newestBook: { title: newest.title, author: newest.author, year: newest.year },
      averageYear,
    },
  });
});

module.exports = router;
```

