```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO PRINCIPAL DA APLICAÇÃO
 * ============================================================================
 *
 * POR QUE CONFIGURAR MIDDLEWARE ANTES DAS ROTAS?
 * -----------------------------------------------
 * O Express executa middlewares na ordem em que são registrados. Por isso:
 *   1. body-parser deve vir antes das rotas (para que req.body esteja disponível)
 *   2. middleware de CORS deve vir antes (para permitir requisições cross-origin)
 *   3. middleware de erros DEVE vir por último (para capturar todos os erros)
 *
 * PADRÃO async/await vs CALLBACKS:
 * ---------------------------------
 * Usamos funções assíncronas com try/catch em vez de callbacks porque:
 *   - Código mais legível e linear (sem "callback hell")
 *   - Tratamento de erros centralizado com try/catch
 *   - Padrão moderno do ecossistema Node.js (recomendado desde ES2017)
 *
 * Em teoria, Express 5 captura rejeições de Promises automaticamente, mas
 * a versão 4 (usada aqui) NÃO faz isso — por isso o try/catch é necessário.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

// ----------------------------------------------------------------------------
// CRIAÇÃO DO APP EXPRESS
// ----------------------------------------------------------------------------
const app = express();

// ----------------------------------------------------------------------------
// MIDDLEWARE GLOBAL
// ----------------------------------------------------------------------------

/**
 * body-parser: converte o corpo da requisição JSON em objeto JavaScript.
 * Sem este middleware, req.body seria undefined.
 * limit: '10kb' previne requisições excessivamente grandes (segurança).
 */
app.use(express.json({ limit: '10kb' }));

/**
 * CORS: permite que frontends de diferentes origens acessem esta API.
 * Em produção, substitua '*' pelo domínio específico do frontend.
 *
 * Nota: Para desenvolvimento local com React/Vue, o CORS é essencial
 * pois o browser bloqueia requisições cross-origin por padrão (Same-Origin Policy).
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept, Authorization');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');

  // Responde imediatamente a requisições OPTIONS (preflight do CORS)
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Logger simples de requisições para debugging.
 * Mostra o método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ----------------------------------------------------------------------------
// ROTAS
// ----------------------------------------------------------------------------
//
 * As rotas são registradas APÓS os middlewares globais mas ANTES do
 * middleware de erros. Isso garante que:
 *   - req.body esteja disponível (body-parser já executou)
 *   - Erros nas rotas sejam capturados pelo errorHandler

app.use('/', booksRouter); // Todas as rotas de livros
app.use('/', statsRouter); // Rotas de estatísticas

// ----------------------------------------------------------------------------
// ROTA PARA RAIZ (DOCUMENTAÇÃO)
// ----------------------------------------------------------------------------
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros REST — Exemplo Educacional',
    endpoints: {
      books: {
        list: 'GET /books?author=&genre=&year=&title=',
        get: 'GET /books/:id',
        create: 'POST /books',
        update: 'PUT /books/:id',
        delete: 'DELETE /books/:id',
      },
      stats: 'GET /stats',
    },
  });
});

// ----------------------------------------------------------------------------
// ROTA 404 PARA URLS NÃO ENCONTRADAS
// ----------------------------------------------------------------------------
//
 * Esta rota captura todas as URLs que não correspondem a nenhum endpoint
 * registrado. Lançamos NotFoundError para que o middleware de erros formate
 * uma resposta padronizada em vez de retornar HTML genérico do Express.

app.use((req, res, next) => {
  const { ApiError } = require('./middleware/errorHandler');
  next(new ApiError(`Rota não encontrada: ${req.method} ${req.url}`, 404));
});

// ----------------------------------------------------------------------------
// MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE POR ÚLTIMO)
// ----------------------------------------------------------------------------
app.use(errorHandler);

// ----------------------------------------------------------------------------
// INICIALIZAÇÃO DO SERVIDOR
// ----------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`✅ Servidor rodando em http://localhost:${PORT}`);
  console.log(`📚 Endpoints disponíveis:`);
  console.log(`   GET    http://localhost:${PORT}/`);
  console.log(`   GET    http://localhost:${PORT}/books`);
  console.log(`   GET    http://localhost:${PORT}/books/:id`);
  console.log(`   POST   http://localhost:${PORT}/books`);
  console.log(`   PUT    http://localhost:${PORT}/books/:id`);
  console.log(`   DELETE http://localhost:${PORT}/books/:id`);
  console.log(`   GET    http://localhost:${PORT}/stats`);
});

module.exports = app;
```

