## File 2: `server.js` — Application Entry Point

```javascript
/**
 * server.js — Main application entry point
 *
 * This file bootstraps the Express application, configures middleware,
 * mounts route handlers, and starts the HTTP server on port 3000.
 *
 * Why this structure?
 * - Separation of concerns: routing logic lives in ./routes/, not here.
 * - Middleware is configured before routes so it applies globally.
 * - The error-handling middleware is registered LAST (required by Express).
 */

const express = require('express');
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');

// Initialize the Express application instance
const app = express();

// ─────────────────────────────────────────────
// Middleware Configuration
// ─────────────────────────────────────────────

/**
 * Body-parser middleware (built into Express 4.16+)
 * Parses incoming JSON request bodies and makes them available at req.body.
 * Without this, POST/PUT requests with JSON payloads would have undefined body.
 */
app.use(express.json());

/**
 * Request logging middleware
 * Prints a timestamped log for every incoming request.
 * Useful for debugging and understanding request flow during development.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler
});

// ─────────────────────────────────────────────
// Route Mounting
// ─────────────────────────────────────────────

/**
 * Mount the books router at /books.
 * All routes defined in ./routes/books.js will be prefixed with /books.
 * This keeps the main app file clean and modular.
 */
app.use('/books', booksRouter);

/**
 * Mount the stats router at /stats.
 * Statistics are a separate resource, so they get their own route prefix.
 */
app.use('/stats', statsRouter);

// ─────────────────────────────────────────────
// Health Check Endpoint
// ─────────────────────────────────────────────

/**
 * GET /health — Simple health check endpoint
 * Returns 200 with a JSON message to confirm the server is running.
 * Useful for load balancers, Kubernetes probes, or quick manual checks.
 */
app.get('/health', (req, res) => {
  res.status(200).json({
    success: true,
    data: { status: 'ok', timestamp: new Date().toISOString() }
  });
});

// ─────────────────────────────────────────────
// Error-Handling Middleware (MUST be last)
// ─────────────────────────────────────────────

/**
 * Express error-handling middleware
 *
 * Why must this be LAST?
 * Express executes middleware in the order it's registered.
 * If this were placed before routes, it would intercept errors
 * from route handlers instead of letting them propagate here.
 *
 * Signature: (err, req, res, next) — Express identifies this as error
 * middleware by the 4-parameter signature. Regular middleware has 3.
 */
app.use((err, req, res, next) => {
  // If for some reason err doesn't have a statusCode, default to 500
  const statusCode = err.statusCode || 500;

  // Build a consistent error response regardless of error type
  res.status(statusCode).json({
    success: false,
    error: {
      statusCode,
      errorType: err.errorType || 'InternalServerError',
      message: err.message
    }
  });
});

// ─────────────────────────────────────────────
// Server Startup
// ─────────────────────────────────────────────

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`📚 Book Management API running on http://localhost:${PORT}`);
  console.log(`   Health check:    GET http://localhost:${PORT}/health`);
  console.log(`   Books endpoint:  GET http://localhost:${PORT}/books`);
  console.log(`   Stats endpoint:  GET http://localhost:${PORT}/stats`);
});
```

