## File 3: `routes/books.js` — Book CRUD Routes

```javascript
/**
 * routes/books.js — All book-related route handlers
 *
 * This module exports an Express Router containing five endpoints:
 *   GET    /          → List all books (with optional filtering)
 *   GET    /:id       → Get a single book by ID
 *   POST   /          → Create a new book
 *   PUT    /:id       → Update an existing book
 *   DELETE /:id       → Delete a book
 *
 * Data structure choice (in-memory array):
 * - An array of plain JavaScript objects is used instead of a Map or object.
 * - Arrays preserve insertion order and support index-based operations.
 * - Each book has a unique numeric ID for O(1) lookups via findIndex.
 * - In production, this would be replaced by a database (MongoDB, PostgreSQL, etc.).
 */

const express = require('express');
const router = express.Router();

// ─────────────────────────────────────────────
// In-Memory Data Store
// ─────────────────────────────────────────────

/**
 * booksData — Array holding all book records in memory.
 *
 * Why an array and not a plain object?
 * - Arrays maintain order (important for list endpoints).
 * - They support built-in methods like .find(), .filter(), .map().
 * - A plain object would require Object.values() to iterate, which is less intuitive.
 *
 * Seed data provides realistic examples so the API works immediately on startup.
 */
let booksData = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5
  },
  {
    id: 2,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    rating: 4.8
  },
  {
    id: 3,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    rating: 4.7
  },
  {
    id: 4,
    title: 'The Art of War',
    author: 'Sun Tzu',
    genre: 'Philosophy',
    publishedYear: -500,
    rating: 4.2
  }
];

/**
 * nextId — Tracks the next available ID for new books.
 * Initialized to 5 because we already have IDs 1–4 in seed data.
 * In a real app, databases handle ID generation automatically (auto-increment, UUIDs).
 */
let nextId = 5;

// ─────────────────────────────────────────────
// Validation Helpers
// ─────────────────────────────────────────────

/**
 * validateBookPayload — Validates data for POST and PUT requests.
 *
 * Why separate validation from route handlers?
 * - Keeps route handlers focused on business logic, not input checking.
 * - Makes validation reusable across multiple endpoints.
 * - Returns a descriptive error message so clients know exactly what went wrong.
 *
 * @param {Object} data — The request body to validate
 * @returns {string|null} Error message if invalid, null if valid
 */
function validateBookPayload(data) {
  // Check that required fields exist and are non-empty strings
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    return 'title is required and must be a non-empty string';
  }
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    return 'author is required and must be a non-empty string';
  }

  // Validate genre is a string (optional but must be correct type if provided)
  if (data.genre !== undefined && typeof data.genre !== 'string') {
    return 'genre must be a string';
  }

  // publishedYear: optional, but if provided must be a number
  if (data.publishedYear !== undefined && typeof data.publishedYear !== 'number') {
    return 'publishedYear must be a number';
  }

  // rating: optional, but if provided must be between 0 and 5
  if (data.rating !== undefined) {
    if (typeof data.rating !== 'number' || data.rating < 0 || data.rating > 5) {
      return 'rating must be a number between 0 and 5';
    }
  }

  return null; // No errors — payload is valid
}

// ─────────────────────────────────────────────
// GET /books — List All Books (with Filtering)
// ─────────────────────────────────────────────

/**
 * GET /books
 *
 * Returns a paginated list of all books. Supports optional query parameters:
 *   ?genre=Fiction       → Filter by genre (case-insensitive partial match)
 *   ?search=gatsby       → Search title and author (case-insensitive)
 *   ?minRating=4.0       → Only books with rating >= this value
 *   ?page=1              → Page number (default: 1)
 *   ?limit=10            → Items per page (default: 10, max: 100)
 *
 * Example curl commands:
 *   # Get all books
 *   curl http://localhost:3000/books
 *
 *   # Filter by genre
 *   curl "http://localhost:3000/books?genre=fiction"
 *
 *   # Search with minimum rating
 *   curl "http://localhost:3000/books?search=hawking&minRating=4.5"
 *
 *   # Paginated results
 *   curl "http://localhost:3000/books?page=1&limit=2"
 */
router.get('/', async (req, res) => {
  try {
    // Destructure query parameters with defaults for pagination
    const { genre, search, minRating, page = 1, limit = 10 } = req.query;

    // Start with a copy of the full dataset to avoid mutating the original
    let filteredBooks = [...booksData];

    // Apply genre filter if provided (case-insensitive partial match)
    if (genre) {
      const genreLower = genre.toLowerCase();
      filteredBooks = filteredBooks.filter(book =>
        book.genre.toLowerCase().includes(genreLower)
      );
    }

    // Apply search filter across title and author (case-insensitive)
    if (search) {
      const searchLower = search.toLowerCase();
      filteredBooks = filteredBooks.filter(book =>
        book.title.toLowerCase().includes(searchLower) ||
        book.author.toLowerCase().includes(searchLower)
      );
    }

    // Apply minimum rating filter if provided
    if (minRating !== undefined) {
      const minR = parseFloat(minRating);
      if (!isNaN(minR)) {
        filteredBooks = filteredBooks.filter(book => book.rating >= minR);
      }
    }

    // Calculate pagination values
    const totalBooks = filteredBooks.length;
    const totalPages = Math.ceil(totalBooks / limit);
    const currentPage = Math.max(1, parseInt(page));
    const startIndex = (currentPage - 1) * limit;
    const endIndex = startIndex + limit;

    // Slice the array to get only the current page of results
    const paginatedBooks = filteredBooks.slice(startIndex, endIndex);

    // Return a consistent response structure with metadata for pagination
    res.status(200).json({
      success: true,
      data: {
        books: paginatedBooks,
        pagination: {
          currentPage,
          totalPages,
          totalBooks,
          limit: parseInt(limit),
          hasNextPage: currentPage < totalPages,
          hasPrevPage: currentPage > 1
        }
      }
    });
  } catch (error) {
    // This should rarely happen with in-memory operations, but we handle it gracefully
    error.statusCode = 500;
    error.errorType = 'InternalServerError';
    throw error;
  }
});

// ─────────────────────────────────────────────
// GET /books/:id — Get Single Book by ID
// ─────────────────────────────────────────────

/**
 * GET /books/:id
 *
 * Returns a single book object matching the provided numeric ID.
 * Returns 404 if no book with that ID exists.
 *
 * Example curl commands:
 *   # Get book with ID 1
 *   curl http://localhost:3000/books/1
 *
 *   # Request a non-existent ID (returns 404)
 *   curl http://localhost:3000/books/999
 */
router.get('/:id', async (req, res) => {
  try {
    // Parse the ID from the URL parameter and ensure it's a valid number
    const id = parseInt(req.params.id);

    if (isNaN(id)) {
      // Return a validation error if the ID is not a number
      const err = new Error('Invalid book ID: must be a numeric value');
      err.statusCode = 400;
      err.errorType = 'ValidationError';
      throw err;
    }

    // Use Array.find() to locate the book with matching ID (O(n) search)
    const book = booksData.find(book => book.id === id);

    if (!book) {
      // Book not found — create a custom NotFoundError for consistent handling
      const err = new Error(`Book with ID ${id} not found`);
      err.statusCode = 404;
      err.errorType = 'NotFoundError';
      throw err;
    }

    // Return the book in our standard response format
    res.status(200).json({
      success: true,
      data: { book }
    });
  } catch (error) {
    // Re-throw so the global error middleware can handle it
    throw error;
  }
});

// ─────────────────────────────────────────────
// POST /books — Create a New Book
// ─────────────────────────────────────────────

/**
 * POST /books
 *
 * Creates a new book from the JSON payload in the request body.
 * Required fields: title, author
 * Optional fields: genre, publishedYear, rating (0–5)
 * Returns 201 Created with the newly created book object.
 *
 * Example curl command:
 *   curl -X POST http://localhost:3000/books \
 *     -H "Content-Type: application/json" \
 *     -d '{
 *       "title": "1984",
 *       "author": "George Orwell",
 *       "genre": "Dystopian",
 *       "publishedYear": 1949,
 *       "rating": 4.6
 *     }'
 */
router.post('/', async (req, res) => {
  try {
    const requestBody = req.body;

    // Validate the incoming payload before creating the book
    const validationError = validateBookPayload(requestBody);
    if (validationError) {
      const err = new Error(validationError);
      err.statusCode = 400;
      err.errorType = 'ValidationError';
      throw err;
    }

    // Generate a unique ID using an incrementing counter
    const newId = nextId++;

    // Build the new book object with defaults for optional fields
    const newBook = {
      id: newId,
      title: requestBody.title.trim(),
      author: requestBody.author.trim(),
      genre: requestBody.genre || 'Unknown',
      publishedYear: requestBody.publishedYear || null,
      rating: requestBody.rating !== undefined ? requestBody.rating : 0.0
    };

    // Add the new book to our in-memory array (O(1) append operation)
    booksData.push(newBook);

    // Return 201 Created to indicate successful resource creation
    res.status(201).json({
      success: true,
      data: { book: newBook },
      message: 'Book created successfully'
    });
  } catch (error) {
    throw error;
  }
});

// ─────────────────────────────────────────────
// PUT /books/:id — Update an Existing Book
// ─────────────────────────────────────────────

/**
 * PUT /books/:id
 *
 * Replaces all fields of the book with the given ID using the provided JSON payload.
 * This is a full update (not partial). Fields not included in the body will be reset
 * to their defaults unless explicitly provided.
 *
 * Returns 404 if the book doesn't exist, 400 if validation fails.
 * Returns 200 with the updated book object on success.
 *
 * Example curl command:
 *   curl -X PUT http://localhost:3000/books/1 \
 *     -H "Content-Type: application/json" \
 *     -d '{
 *       "title": "The Great Gatsby (Updated)",
 *       "author": "F. Scott Fitzgerald",
 *       "genre": "Classic Fiction",
 *       "publishedYear": 1925,
 *       "rating": 4.7
 *     }'
 */
router.put('/:id', async (req, res) => {
  try {
    const id = parseInt(req.params.id);

    if (isNaN(id)) {
      const err = new Error('Invalid book ID: must be a numeric value');
      err.statusCode = 400;
      err.errorType = 'ValidationError';
      throw err;
    }

    // Find the index of the book to update (we need the index for splice later)
    const bookIndex = booksData.findIndex(book => book.id === id);

    if (bookIndex === -1) {
      const err = new Error(`Book with ID ${id} not found`);
      err.statusCode = 404;
      err.errorType = 'NotFoundError';
      throw err;
    }

    // Validate the incoming payload
    const validationError = validateBookPayload(req.body);
    if (validationError) {
      const err = new Error(validationError);
      err.statusCode = 400;
      err.errorType = 'ValidationError';
      throw err;
    }

    // Replace the entire book object with updated values
    // Note: ID is preserved since it's a primary key and shouldn't change
    const updatedBook = {
      id,
      title: req.body.title.trim(),
      author: req.body.author.trim(),
      genre: req.body.genre || 'Unknown',
      publishedYear: req.body.publishedYear !== undefined ? req.body.publishedYear : null,
      rating: req.body.rating !== undefined ? req.body.rating : 0.0
    };

    // Update the book in-place using array index assignment (O(1))
    booksData[bookIndex] = updatedBook;

    res.status(200).json({
      success: true,
      data: { book: updatedBook },
      message: 'Book updated successfully'
    });
  } catch (error) {
    throw error;
  }
});

// ─────────────────────────────────────────────
// DELETE /books/:id — Delete a Book
// ─────────────────────────────────────────────

/**
 * DELETE /books/:id
 *
 * Removes the book with the given ID from the in-memory store.
 * Returns 404 if no book with that ID exists.
 * Returns 200 with a confirmation message on successful deletion.
 *
 * Example curl command:
 *   # Delete book with ID 3
 *   curl -X DELETE http://localhost:3000/books/3
 *
 *   # Delete non-existent book (returns 404)
 *   curl -X DELETE http://localhost:3000/books/999
 */
router.delete('/:id', async (req, res) => {
  try {
    const id = parseInt(req.params.id);

    if (isNaN(id)) {
      const err = new Error('Invalid book ID: must be a numeric value');
      err.statusCode = 400;
      err.errorType = 'ValidationError';
      throw err;
    }

    // Find the index of the book to delete
    const bookIndex = booksData.findIndex(book => book.id === id);

    if (bookIndex === -1) {
      const err = new Error(`Book with ID ${id} not found`);
      err.statusCode = 404;
      err.errorType = 'NotFoundError';
      throw err;
    }

    // Remove the book from the array using splice (O(n) due to array shifting)
    booksData.splice(bookIndex, 1);

    res.status(200).json({
      success: true,
      message: `Book with ID ${id} has been deleted successfully`
    });
  } catch (error) {
    throw error;
  }
});

// Export the router so it can be mounted in server.js
module.exports = router;
```

