## File 4: `routes/stats.js` — Statistics Endpoint

```javascript
/**
 * routes/stats.js — Book collection statistics endpoint
 *
 * This module exports a single GET /stats route that returns aggregate
 * analytics about the book collection. Statistics are computed on each
 * request from the current in-memory data (no caching).
 *
 * Why compute stats on demand?
 * - The dataset is small (in-memory), so computation is fast.
 * - Stats always reflect the current state without stale cache issues.
 * - In production with large datasets, you might precompute and cache these.
 */

const express = require('express');
const router = express.Router();

// Import the shared books data from the books route module
// This ensures both routers operate on the same in-memory dataset
const { getBooksData } = require('./books');

/**
 * GET /stats
 *
 * Returns comprehensive statistics about the book collection including:
 *   - totalBooks: Total number of books in the collection
 *   - averageRating: Mean rating across all books (rounded to 2 decimals)
 *   - genreDistribution: Count of books per genre
 *   - oldestBook: Book with the earliest publishedYear
 *   - newestBook: Book with the latest publishedYear
 *   - highestRated: Book with the highest rating
 *   - lowestRated: Book with the lowest rating
 *
 * Example curl command:
 *   curl http://localhost:3000/stats
 */
router.get('/', async (req, res) => {
  try {
    // Get a snapshot of the current books data
    const books = getBooksData();

    // Handle empty collection gracefully
    if (books.length === 0) {
      return res.status(200).json({
        success: true,
        data: {
          totalBooks: 0,
          averageRating: 0,
          genreDistribution: {},
          oldestBook: null,
          newestBook: null,
          highestRated: null,
          lowestRated: null
        }
      });
    }

    // Calculate total number of books
    const totalBooks = books.length;

    // Calculate average rating using reduce (O(n) single pass)
    const sumRatings = books.reduce((sum, book) => sum + book.rating, 0);
    const averageRating = parseFloat((sumRatings / totalBooks).toFixed(2));

    // Build genre distribution object using reduce (O(n))
    // Groups books by genre and counts occurrences
    const genreDistribution = books.reduce((acc, book) => {
      const genre = book.genre || 'Unknown';
      acc[genre] = (acc[genre] || 0) + 1;
      return acc;
    }, {});

    // Find the oldest book (earliest publishedYear)
    // We use a custom comparator to handle null/undefined years gracefully
    const oldestBook = books.reduce((oldest, current) => {
      const oldYear = oldest.publishedYear || Infinity;
      const currYear = current.publishedYear || Infinity;
      return currYear < oldYear ? current : oldest;
    }, books[0]);

    // Find the newest book (latest publishedYear)
    const newestBook = books.reduce((newest, current) => {
      const newYear = newest.publishedYear || -Infinity;
      const currYear = current.publishedYear || -Infinity;
      return currYear > newYear ? current : newest;
    }, books[0]);

    // Find the highest-rated book
    const highestRated = books.reduce((highest, current) =>
      current.rating > highest.rating ? current : highest
    , books[0]);

    // Find the lowest-rated book
    const lowestRated = books.reduce((lowest, current) =>
      current.rating < lowest.rating ? current : lowest
    , books[0]);

    // Return all statistics in a single response
    res.status(200).json({
      success: true,
      data: {
        totalBooks,
        averageRating,
        genreDistribution,
        oldestBook,
        newestBook,
        highestRated,
        lowestRated
      }
    });
  } catch (error) {
    error.statusCode = 500;
    error.errorType = 'InternalServerError';
    throw error;
  }
});

module.exports = router;
```

