## Arquivo 2: `src/utils/app-error.util.js`

```javascript
/**
 * ============================================================================
 * CLASSE PERSONALIZADA DE ERRO DA APLICAÇÃO
 * ============================================================================
 *
 * POR QUE CRIAR UMA CLASSE DE ERRO CUSTOMIZADA?
 * -----------------------------------------------
 * O JavaScript nativo oferece a classe Error, mas ela não carrega informações
 * contextuais suficientes para APIs REST. Uma classe AppError permite:
 *   1. Incluir um código de status HTTP diretamente no erro (400, 404, etc.)
 *   2. Diferenciar erros de validação de erros de "não encontrado"
 *   3. Manter uma propriedade 'isOperational' para distinguir erros previsíveis
 *      (que o usuário pode ter causado) de erros inesperados do servidor.
 *
 * PADRÃO ADOTADO: Error Subclassing
 * ----------------------------------
 * Estendemos a classe nativa 'Error' para herdar seu comportamento padrão
 * (stack trace, message) e adicionar campos customizados. Isso segue o padrão
 * "Operational Error" amplamente adotado em APIs profissionais.
 */

class AppError extends Error {
  /**
   * Construtor da classe AppError.
   *
   * @param {string} message - Mensagem descritiva do erro para o cliente.
   * @param {number} statusCode - Código HTTP correspondente (ex: 404, 500).
   * @param {boolean} [isOperational=true] - Indica se é um erro esperado/do usuário.
   */
  constructor(message, statusCode, isOperational = true) {
    // super() chama o construtor da classe pai (Error), passando a mensagem.
    // Isso garante que error.message e error.stack funcionem normalmente.
    super(message);

    // Atributos customizados da nossa classe:
    this.statusCode = statusCode;       // Código HTTP retornado ao cliente
    this.isOperational = isOperational; // Erro "operacional" vs erro de bug

    // Captura o nome da classe para logs mais claros.
    // captureStackTrace remove esta função da pilha de erros (limpa o stack).
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * ============================================================================
 * CLASSES DE ERRO ESPECÍFICAS POR DOMÍNIO
 * ============================================================================
 *
 * POR QUE SUBCLASSES?
 * --------------------
 * Criar subclasses como NotFoundError e ValidationError permite:
 *   - Tratamento diferenciado no middleware de erros
 *   - Mensagens padrão consistentes em toda a aplicação
 *   - Código mais legível ao lançar erros (new NotFoundError(...) é autoexplicativo)
 *
 * Isso segue o princípio de "fail fast" com mensagens claras.
 */

/**
 * Erro lançado quando um recurso solicitado não é encontrado.
 * Ex: Livro com ID inexistente.
 * Status HTTP padrão: 404 Not Found
 */
class NotFoundError extends AppError {
  constructor(resource = 'recurso', id = null) {
    // Template string para mensagem dinâmica e clara.
    const message = id
      ? `${resource} com ID ${id} não encontrado`
      : `${resource} não encontrado`;
    super(message, 404);
  }
}

/**
 * Erro lançado quando a entrada do cliente viola regras de validação.
 * Ex: Campo obrigatório ausente, tipo incorreto, etc.
 * Status HTTP padrão: 400 Bad Request
 */
class ValidationError extends AppError {
  constructor(message = 'Dados de entrada inválidos', details = null) {
    super(message, 400);
    this.details = details; // Array opcional com detalhes específicos
  }
}

/**
 * Erro lançado quando o cliente tenta uma operação não permitida.
 * Ex: PUT em recurso inexistente (atualizar livro que não existe).
 * Status HTTP padrão: 405 Method Not Allowed ou 409 Conflict
 */
class ConflictError extends AppError {
  constructor(message = 'Conflito com recurso existente') {
    super(message, 409);
  }
}

// Exportação nomeada para importação seletiva nos módulos.
module.exports = { AppError, NotFoundError, ValidationError, ConflictError };
```

