## Arquivo 3: `src/models/book.model.js`

```javascript
/**
 * ============================================================================
 * MODELO DE DADOS — LIVRO (EM MEMÓRIA)
 * ============================================================================
 *
 * POR QUE ARMAZENAMENTO EM ARRAY EM MEMÓRIA?
 * --------------------------------------------
 * Para este exemplo educacional, usamos um array em memória porque:
 *   1. Elimina a complexidade de configurar um banco de dados
 *   2. Permite focar nos conceitos REST e na estrutura da API
 *   3. Operações são O(1) para push/pop e O(n) para busca — aceitável para
 *      volumes pequenos de dados (centenas de registros)
 *
 * POR QUE NÃO USAR UM OBJETO ({id: livro})?
 * -------------------------------------------
 * Um objeto mapeando ID → Livro seria mais eficiente para buscas por ID
 * (O(1) vs O(n)). No entanto, um array é mais adequado aqui porque:
 *   - Facilita a iteração para filtragem e estatísticas
 *   - Mantém a ordem de inserção (útil para ordenação temporal)
 *   - É mais intuitivo para fins educacionais
 *
 * Em produção, substituiríamos este array por um banco de dados real
 * (MongoDB, PostgreSQL, etc.) mantendo a mesma interface.
 */

/**
 * Lista em memória de todos os livros cadastrados.
 * Cada livro é um objeto com propriedades bem definidas.
 *
 * INICIALIZAÇÃO COM DADOS DE EXEMPLO:
 * ------------------------------------
 * Populamos com alguns livros para que a API já venha funcional ao iniciar,
 * permitindo testes imediatos sem precisar criar dados primeiro.
 */
const books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    year: 1954,
    genre: 'Fantasia',
    createdAt: new Date('2024-01-15T10:00:00Z'),
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    year: 1949,
    genre: 'Ficção Científica',
    createdAt: new Date('2024-02-20T14:30:00Z'),
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    year: 1899,
    genre: 'Romance',
    createdAt: new Date('2024-03-10T09:15:00Z'),
  },
];

/**
 * Contador para geração automática de IDs únicos.
 *
 * POR QUE USAR UM CONTADOR EM VEZ DE uuid?
 * ------------------------------------------
 * Para este exemplo, IDs numéricos sequenciais são suficientes e mais legíveis.
 * Em produção, usaríamos UUIDs (v4) ou Snowflake IDs para evitar colisões em
 * sistemas distribuídos. O contador é simples, previsível e fácil de depurar.
 */
let nextId = 4; // Próximo ID a ser atribuído (começa após o último existente)

/**
 * ============================================================================
 * FUNÇÕES DO MODELO — OPERAÇÕES CRUD SOBRE O ARRAY EM MEMÓRIA
 * ============================================================================
 */

/**
 * Retorna todos os livros cadastrados.
 *
 * @returns {Array<Object>} Lista completa de livros.
 */
function findAll() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - ID do livro a ser buscado.
 * @returns {Object|null} Livro encontrado ou null se não existir.
 *
 * POR QUE USAR find() EM VEZ DE filter()?
 * -----------------------------------------
 * find() retorna o PRIMEIRO elemento que satisfaz a condição, parando a iteração
 * assim que encontra. Como IDs são únicos, não precisamos de todos os resultados —
 * find() é mais eficiente (O(n) no pior caso, mas para com o primeiro match).
 */
function findById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * @param {Object} bookData - Dados do novo livro (sem ID).
 * @returns {Object} O livro criado com ID e timestamp atribuídos.
 */
function create(bookData) {
  const newBook = {
    id: nextId++, // Atribui ID sequencial e incrementa o contador
    ...bookData,  // Espalha os dados fornecidos pelo cliente
    createdAt: new Date(), // Registra timestamp de criação automático
  };

  books.push(newBook); // O(1) — adiciona ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} updates - Campos a serem atualizados (partial update).
 * @returns {Object|null} Livro atualizado ou null se não encontrado.
 *
 * POR QUE USAR {...book, ...updates}?
 * ------------------------------------
 * O operador spread cria uma NOVA cópia do objeto com os campos atualizados,
 * em vez de mutar o objeto original diretamente. Isso segue o princípio de
 * imutabilidade de dados, evitando efeitos colaterais indesejados.
 */
function update(id, updates) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return null; // Livro não encontrado
  }

  // Cria cópia atualizada sem mutar o original diretamente
  const updatedBook = { ...books[index], ...updates };
  books[index] = updatedBook; // Substitui no array

  return updatedBook;
}

/**
 * Remove um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} true se removido, false se não encontrado.
 *
 * POR QUE USAR splice() EM VEZ DE filter()?
 * -------------------------------------------
 * splice() modifica o array original in-place e é mais eficiente para remoções
 * únicas (O(n) para encontrar + O(n) para realocar). filter() criaria um novo
 * array inteiro, desperdiçando memória para uma única remoção.
 */
function remove(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return false;
  }

  books.splice(index, 1); // Remove 1 elemento na posição encontrada
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o acervo de livros.
 *
 * @returns {Object} Estatísticas: total, por gênero, média de anos, mais antigo e mais recente.
 *
 * POR QUE CALCULAR NO MODELO E NÃO NO CONTROLADOR?
 * --------------------------------------------------
 * Separação de responsabilidades (SoC): o modelo conhece seus dados e sabe como
 * agregá-los. O controlador apenas orquestra a chamada e formata a resposta HTTP.
 */
function getStats() {
  const total = books.length;

  // Agrupamento por gênero usando reduce — padrão funcional para aggregação
  const byGenre = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Cálculo da média de anos de publicação
  const avgYear =
    total > 0
      ? books.reduce((sum, book) => sum + book.year, 0) / total
      : 0;

  // Livros mais antigo e mais recente (comparação por timestamp)
  const oldest =
    total > 0
      ? books.reduce((min, book) =>
          book.createdAt < min.createdAt ? book : min
        )
      : null;

  const newest =
    total > 0
      ? books.reduce((max, book) =>
          book.createdAt > max.createdAt ? book : max
        )
      : null;

  return {
    total,
    byGenre,
    avgYear: Math.round(avgYear * 100) / 100, // Arredonda para 2 casas decimais
    oldest,
    newest,
  };
}

// Exportação de todas as funções do modelo.
module.exports = {
  findAll,
  findById,
  create,
  update,
  remove,
  getStats,
};
```

