## Arquivo 4: `src/middleware/validation.middleware.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE VALIDAÇÃO DE ENTRADA
 * ============================================================================
 *
 * POR QUE VALIDAR NO MIDDLEWARE E NÃO NO CONTROLADOR?
 * ----------------------------------------------------
 * Validação antecipada (fail-fast) evita que dados inválidos cheguem à lógica
 * de negócio. O middleware atua como um "portão" que rejeita requisições mal
 * formadas antes de qualquer processamento, economizando recursos e mantendo
 * o controlador limpo focado apenas na regra de negócio.
 *
 * PADRÃO ADOTADO: Função validadora como middleware Express
 * ----------------------------------------------------------
 * Cada função validadora é uma função que recebe (req, res, next), onde 'next'
 * é chamado ao passar pela validação. Se falhar, enviamos a resposta de erro
 * diretamente sem chamar next(). Isso segue o padrão de middlewares Express.
 */

const { ValidationError } = require('../utils/app-error.util');

/**
 * Middleware que valida os dados de criação de um livro (POST /books).
 *
 * REGRAS DE VALIDAÇÃO:
 *   - title: obrigatório, string não vazia
 *   - author: obrigatório, string não vazia
 *   - year: obrigatório, número inteiro entre 1000 e o ano atual
 *   - genre: opcional, mas se fornecido deve ser string não vazia
 *
 * @param {Object} req - Objeto de requisição Express.
 * @param {Object} res - Objeto de resposta Express.
 * @param {Function} next - Função para passar ao próximo middleware.
 */
function validateCreateBook(req, res, next) {
  const errors = []; // Acumulador de erros de validação

  const { title, author, year, genre } = req.body;

  // Validação do título: campo obrigatório e não vazio
  if (!title || typeof title !== 'string' || title.trim() === '') {
    errors.push({ field: 'title', message: 'Título é obrigatório e deve ser uma string não vazia' });
  }

  // Validação do autor: campo obrigatório e não vazio
  if (!author || typeof author !== 'string' || author.trim() === '') {
    errors.push({ field: 'author', message: 'Autor é obrigatório e deve ser uma string não vazia' });
  }

  // Validação do ano: número inteiro em rango razoável
  const currentYear = new Date().getFullYear();
  if (year === undefined || year === null) {
    errors.push({ field: 'year', message: 'Ano de publicação é obrigatório' });
  } else if (!Number.isInteger(year)) {
    errors.push({ field: 'year', message: 'Ano deve ser um número inteiro' });
  } else if (year < 1000 || year > currentYear + 1) {
    errors.push({ field: 'year', message: `Ano deve estar entre 1000 e ${currentYear + 1}` });
  }

  // Validação do gênero: opcional, mas se fornecido deve ser string
  if (genre !== undefined && genre !== null) {
    if (typeof genre !== 'string' || genre.trim() === '') {
      errors.push({ field: 'genre', message: 'Gênero deve ser uma string não vazia' });
    }
  }

  // Se houver erros, lançamos ValidationError com todos os detalhes.
  // Isso permite que o cliente corrija todos os campos de uma vez.
  if (errors.length > 0) {
    return next(new ValidationError('Validação falhou', errors));
  }

  // Todos os testes passaram — passa para o próximo middleware/controlador.
  next();
}

/**
 * Middleware que valida o ID na URL (GET/PUT/DELETE /books/:id).
 *
 * REGRAS DE VALIDAÇÃO:
 *   - id deve ser um número inteiro positivo
 *
 * @param {Object} req - Objeto de requisição Express.
 * @param {Object} res - Objeto de resposta Express.
 * @param {Function} next - Função para passar ao próximo middleware.
 */
function validateBookId(req, res, next) {
  const id = parseInt(req.params.id, 10); // Converte string da URL para número

  if (isNaN(id) || id <= 0 || !Number.isInteger(id)) {
    return next(new ValidationError('ID do livro deve ser um número inteiro positivo'));
  }

  // Armazena o ID convertido no req para uso posterior pelo controlador.
  // Isso evita que o controlador precise fazer a conversão novamente.
  req.validatedId = id;
  next();
}

module.exports = { validateCreateBook, validateBookId };
```

