/**
 * ============================================================================
 * MIDDLEWARE CENTRAL DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE UM MIDDLEWARE DE ERROS SEPARADO?
 * ------------------------------------------
 * Express possui um mecanismo especial de middlewares de erro: funções com
 * QUATRO parâmetros (err, req, res, next). Quando qualquer middleware ou
 * controlador chama next(err), o Express pula diretamente para este middleware.
 *
 * VANTAGENS:
 *   1. Centralização do formato de resposta de erro (consistência)
 *   2. Separação entre lógica de negócio e lógica de apresentação de erros
 *   3. Capacidade de logar erros no servidor sem expor detalhes ao cliente
 *   4. Diferenciação entre erros operacionais (4xx) e erros do servidor (5xx)
 *
 * PADRÃO: "Operational" vs "Exceptional" Errors
 * ----------------------------------------------
 * Erros com isOperational = true são previsíveis (input inválido, recurso não
 * encontrado) e devem ser tratados silenciosamente. Erros com isOperational =
 * false indicam bugs no código e devem ser logados com stack trace completo.
 */

const { AppError } = require('../utils/app-error.util');

/**
 * Middleware de tratamento de erros para a aplicação Express.
 *
 * @param {Error} err - O erro lançado (pode ser AppError ou Error nativo).
 * @param {Object} req - Objeto de requisição Express.
 * @param {Object} res - Objeto de resposta Express.
 * @param {Function} next - Não utilizado, mas necessário para assinatura de 4 params.
 */
function errorHandler(err, req, res, next) {
  // Determina se é um AppError conhecido ou um erro inesperado do sistema.
  const isAppError = err instanceof AppError;

  let statusCode = isAppError ? err.statusCode : 500;
  let responseBody = {};

  if (isAppError) {
    // Erro operacional: responde com mensagem clara e código apropriado.
    responseBody = {
      success: false,
      error: {
        type: err.constructor.name, // Nome da classe do erro (NotFoundError, etc.)
        message: err.message,
        ...(err.details && { details: err.details }), // Inclui detalhes se existirem
      },
    };

    // Log apenas em desenvolvimento para não poluir logs de produção.
    if (process.env.NODE_ENV !== 'production') {
      console.error(`[AppError] ${err.constructor.name}: ${err.message}`);
    }
  } else {
    // Erro inesperado do servidor: protege o cliente de ver stack traces.
    responseBody = {
      success: false,
      error: {
        type: 'InternalError',
        message: 'Ocorreu um erro interno no servidor. Tente novamente mais tarde.',
      },
    };

    // Log completo com stack trace para depuração.
    console.error('[InternalError]', err);
    if (err.stack) {
      console.error(err.stack);
    }
  }

  // Envia a resposta de erro no formato JSON padronizado.
  res.status(statusCode).json(responseBody);
}

/**
 * Middleware para capturar erros assíncronos que escapam dos blocos try/catch.
 *
 * PROBLEMA RESOLVIDO:
 * --------------------
 * Express não captura automaticamente rejeições de Promises em controladores
 * async/await. Se um controlador async lança um erro sem try/catch, a requisição
 * fica "pendente" indefinidamente (hang). Este middleware converte erros
 * assíncronos não tratados em chamadas normais a next(err).
 *
 * PADRÃO: Higher-Order Function (Wrapper)
 * -----------------------------------------
 * Envolvemos cada controlador async com esta função que captura rejeições e
 * as encaminha para o middleware de erros via next(err). Isso é um padrão
 * amplamente usado em APIs Express profissionais.
 *
 * @param {Function} fn - Função assíncrona do controlador.
 * @returns {Function} Middleware Express com tratamento de erros assíncronos.
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    // Executa a função e captura tanto rejeições quanto erros síncronos.
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = { errorHandler, asyncHandler };
```

