## Arquivo 6: `src/controllers/books.controller.js`

```javascript
/**
 * ============================================================================
 * CONTROLADOR DE LIVROS — ORQUESTRAÇÃO DAS OPERAÇÕES CRUD
 * ============================================================================
 *
 * POR QUE UM CONTROLADOR SEPARADO?
 * ----------------------------------
 * O controlador é a camada que orquestra a lógica de negócio: recebe a requisição,
 * chama o modelo, e formata a resposta HTTP. Ele NÃO deve conter lógica de banco
 * de dados (isso vai no modelo) nem lógica de validação de input (isso vai no
 * middleware). Esta separação segue o padrão MVC (Model-View-Controller).
 *
 * PADRÃO async/await:
 * --------------------
 * Usamos funções assíncronas com await porque:
 *   1. Código mais legível que encadeamento de .then()
 *   2. Tratamento de erros natural com try/catch
 *   3. Express suporta nativamente funções async a partir da versão 4.x
 *
 * FORMATO DE RESPOSTA PADRONIZADO:
 * ----------------------------------
 * Todas as respostas seguem o esquema:
 *   { success: boolean, data?: Object | Array, error?: Object }
 * Isso proporciona consistência para consumidores da API.
 */

const bookModel = require('../models/book.model');
const { NotFoundError } = require('../utils/app-error.util');
const { asyncHandler } = require('../middleware/error.middleware');

/**
 * GET /books
 * Lista todos os livros com filtragem opcional por gênero e/ou autor.
 *
 * PARÂMETROS DE QUERY (opcionais):
 *   - genre: filtra por gênero (ex: ?genre=Fantasia)
 *   - author: filtra por autor (busca parcial, case-insensitive)
 *   - sort: ordena por campo (title, year, createdAt)
 *   - order: direção da ordenação (asc, desc) — padrão: asc
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Fantasia"
 *   curl "http://localhost:3000/books?author=tolkien&sort=year&order=desc"
 */
const getAllBooks = asyncHandler(async (req, res) => {
  // Começa com todos os livros e aplica filtros sequencialmente.
  let result = bookModel.findAll();

  // Filtro por gênero: comparação exata, case-insensitive.
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase() === genreFilter);
  }

  // Filtro por autor: busca parcial (substrings), case-insensitive.
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) =>
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Ordenação opcional por campo especificado.
  if (req.query.sort) {
    const sortField = req.query.sort;
    const order = req.query.order === 'desc' ? -1 : 1; // Padrão: asc

    result = [...result].sort((a, b) => {
      // Compara valores do campo especificado.
      const valA = a[sortField];
      const valB = b[sortField];

      if (typeof valA === 'string') {
        return order * valA.localeCompare(valB);
      }
      return order * (valA - valB);
    });
  }

  // Resposta padronizada com dados e metadados de paginação.
  res.json({
    success: true,
    data: result,
    meta: {
      total: result.length,
      filters: {
        genre: req.query.genre || null,
        author: req.query.author || null,
        sort: req.query.sort || null,
        order: req.query.order || 'asc',
      },
    },
  });
});

/**
 * GET /books/:id
 * Retorna um único livro pelo seu ID.
 *
 * PARÂMETROS DE URL:
 *   - id: ID numérico do livro (ex: /books/1)
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → 404 Not Found
 */
const getBookById = asyncHandler(async (req, res) => {
  // Usa o ID já validado pelo middleware validateBookId.
  const book = bookModel.findById(req.validatedId);

  if (!book) {
    // Lança NotFoundError que será capturado pelo middleware de erros.
    throw new NotFoundError('Livro', req.validatedId);
  }

  res.json({
    success: true,
    data: book,
  });
});

/**
 * POST /books
 * Cria um novo livro com os dados fornecidos no corpo da requisição.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 *   {
 *     "title": "Nome do Livro",
 *     "author": "Nome do Autor",
 *     "year": 2024,
 *     "genre": "Gênero"  // opcional
 *   }
 *
 * EXEMPLOS DE USO:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","year":1932,"genre":"Ficção Científica"}'
 */
const createBook = asyncHandler(async (req, res) => {
  // Extrai apenas os campos válidos do corpo da requisição.
  const { title, author, year, genre } = req.body;

  const newBook = bookModel.create({ title, author, year, genre });

  // Status 201 Created indica que um novo recurso foi criado com sucesso.
  // Location header aponta para o URI do recurso criado (convenção REST).
  res.status(201).json({
    success: true,
    data: newBook,
    message: 'Livro criado com sucesso',
  });
});

/**
 * PUT /books/:id
 * Atualiza completamente um livro existente pelo seu ID.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 *   {
 *     "title": "Novo Título",
 *     "author": "Novo Autor",
 *     "year": 2023,
 *     "genre": "Novo Gênero"
 *   }
 *
 * NOTA: PUT é substituição completa. Todos os campos obrigatórios devem ser
 * fornecidos. Para atualizações parciais, use PATCH (não implementado aqui).
 *
 * EXEMPLOS DE USO:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Senhor dos Anéis (Ed. Celebrant)","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 */
const updateBook = asyncHandler(async (req, res) => {
  const updatedBook = bookModel.update(req.validatedId, req.body);

  if (!updatedBook) {
    throw new NotFoundError('Livro', req.validatedId);
  }

  res.json({
    success: true,
    data: updatedBook,
    message: 'Livro atualizado com sucesso',
  });
});

/**
 * DELETE /books/:id
 * Remove um livro pelo seu ID.
 *
 * EXEMPLOS DE USO:
 *   curl -X DELETE http://localhost:3000/books/1
 *   curl -X DELETE http://localhost:3000/books/999  → 404 Not Found
 */
const deleteBook = asyncHandler(async (req, res) => {
  const removed = bookModel.remove(req.validatedId);

  if (!removed) {
    throw new NotFoundError('Livro', req.validatedId);
  }

  // Status 204 No Content indica sucesso sem corpo de resposta.
  // Isso é apropriado para DELETE conforme convenções REST.
  res.status(204).end();
});

/**
 * GET /stats
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/stats
 */
const getStats = asyncHandler(async (req, res) => {
  const stats = bookModel.getStats();

  res.json({
    success: true,
    data: stats,
  });
});

// Exportação de todas as handlers do controlador.
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

