## Arquivo 7: `src/routes/books.routes.js`

```javascript
/**
 * ============================================================================
 * ROTAS DA API — DEFINIÇÃO DOS ENDPOINTS REST
 * ============================================================================
 *
 * POR QUE ARQUIVO DE ROTAS SEPARADO?
 * ------------------------------------
 * Separar rotas do controlador permite:
 *   1. Manter o arquivo de rotas como "mapa" da API (fácil de visualizar)
 *   2. Aplicar middlewares específicos por rota sem poluir o controlador
 *   3. Reutilizar middlewares em múltiplas rotas (ex: validateBookId)
 *   4. Facilitar testes unitários de cada camada isoladamente
 *
 * PADRÃO RESTFUL DE NOMENCLATURA:
 * ---------------------------------
 * Seguimos as convenções REST estabelecidas por Roy Fielding:
 *   - GET    /books       → Coleção (listar/filtrar)
 *   - GET    /books/:id   → Recurso individual
 *   - POST   /books       → Criar novo recurso
 *   - PUT    /books/:id   → Substituir recurso existente
 *   - DELETE /books/:id   → Remover recurso
 *   - GET    /stats       → Recurso derivado (estatísticas)
 *
 * Cada método HTTP tem um significado semântico específico:
 *   - GET: segurança (não modifica dados) + idempotência
 *   - POST: não idempotente (cria recurso único)
 *   - PUT: idempotente (mesma requisição = mesmo resultado)
 *   - DELETE: idempotente (remover já removido é estado final)
 */

const express = require('express');
const router = express.Router(); // Cria um roteador modular

const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
} = require('../controllers/books.controller');
const { validateCreateBook, validateBookId } = require('../middleware/validation.middleware');

/**
 * ============================================================================
 * ROTA: GET /books
 * Listar todos os livros com filtragem opcional.
 * ============================================================================
 */
router.get('/books', getAllBooks);

/**
 * ============================================================================
 * ROTA: GET /books/:id
 * Obter um livro específico pelo ID.
 *
 * PIPELINE DE MIDDLEWARE:
 *   validateBookId → getBookById
 *
 * O middleware validateBookId é executado PRIMEIRO para:
 *   1. Validar que o ID é um número inteiro positivo
 *   2. Converter a string da URL para número
 *   3. Armazenar o ID validado em req.validatedId para uso pelo controlador
 */
router.get('/books/:id', validateBookId, getBookById);

/**
 * ============================================================================
 * ROTA: POST /books
 * Criar um novo livro.
 *
 * PIPELINE DE MIDDLEWARE:
 *   express.json() → validateCreateBook → createBook
 *
 * express.json(): Middleware nativo do Express que faz parse do corpo JSON.
 * Deve ser aplicado ANTES da validação para que req.body esteja populado.
 */
router.post('/books', express.json(), validateCreateBook, createBook);

/**
 * ============================================================================
 * ROTA: PUT /books/:id
 * Atualizar um livro existente.
 *
 * PIPELINE DE MIDDLEWARE:
 *   express.json() → validateBookId → updateBook
 */
router.put('/books/:id', express.json(), validateBookId, updateBook);

/**
 * ============================================================================
 * ROTA: DELETE /books/:id
 * Remover um livro.
 *
 * PIPELINE DE MIDDLEWARE:
 *   validateBookId → deleteBook
 */
router.delete('/books/:id', validateBookId, deleteBook);

/**
 * ============================================================================
 * ROTA: GET /stats
 * Retornar estatísticas do acervo.
 * ============================================================================
 */
router.get('/stats', getStats);

// Exportação do roteador para ser usado em app.js.
module.exports = router;
```

