## Arquivo 8: `src/app.js`

```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO DA APLICAÇÃO EXPRESS
 * ============================================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * --------------------------------------
 * app.js configura a aplicação (middlewares, rotas, error handling).
 * server.js apenas inicia o servidor HTTP ouvindo uma porta.
 * Esta separação permite:
 *   - Testar a aplicação sem precisar iniciar um servidor
 *   - Reutilizar a configuração em diferentes ambientes
 *   - Manter o código de rede isolado da lógica da aplicação
 *
 * ORDEM DOS MIDDLEWARES (CRÍTICO):
 * ----------------------------------
 * A ordem importa porque Express executa middlewares sequencialmente:
 *   1. cors → permite requisições cross-origin (desenvolvimento)
 *   2. express.json() → parse de JSON no corpo das requisições
 *   3. rotas → processamento das requisições
 *   4. errorHandler → captura erros não tratados
 */

const express = require('express');
const booksRoutes = require('./routes/books.routes');
const { errorHandler } = require('./middleware/error.middleware');

const app = express();

/**
 * Middleware CORS (Cross-Origin Resource Sharing).
 * Permite que frontends de diferentes origens acessem esta API.
 * Em produção, restrinja o origin a domínios específicos.
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');

  // Responde imediatamente a requisições OPTIONS (preflight CORS).
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Middleware de logging simples para desenvolvimento.
 * Registra método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

/**
 * Middleware para parse de JSON no corpo das requisições.
 * Necessário para que req.body esteja disponível nos controladores.
 */
app.use(express.json());

/**
 * Registro das rotas da API sob o caminho base /api.
 * Todas as rotas definidas em books.routes.js serão prefixadas com /api.
 */
app.use('/api', booksRoutes);

/**
 * Rota de health check — útil para monitoramento e load balancers.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Middleware de tratamento de erros — DEVE ser o ÚLTIMO middleware registrado.
 * Express identifica middlewares de erro pela assinatura de 4 parâmetros.
 */
app.use(errorHandler);

// Exportação da instância app para uso em server.js e testes.
module.exports = app;
```

