## Arquivo 9: `src/server.js`

```javascript
/**
 * ============================================================================
 * PONTO DE ENTRADA DA APLICAÇÃO
 * ============================================================================
 *
 * Este arquivo apenas inicia o servidor HTTP ouvindo na porta configurada.
 * A configuração da aplicação está em app.js (separação de responsabilidades).
 */

const app = require('./app');

// Porta padrão: 3000, mas permite sobrescrita via variável de ambiente.
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  API de Livros rodando na porta ${PORT}`);
  console.log(`  Ambiente: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Base URL: http://localhost:${PORT}/api`);
  console.log(`========================================`);
});

// Tratamento de erros não capturados no processo.
process.on('uncaughtException', (err) => {
  console.error('[Uncaught Exception]', err);
  server.close(() => process.exit(1));
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('[Unhandled Rejection]', reason);
});

module.exports = server;
```

