## File: `server.js`

```js
/**
 * server.js — Entry point for the Book REST API.
 *
 * This module sets up Express, registers middleware, mounts route handlers,
 * and starts listening on a configurable port (default 3000).
 *
 * @module server
 */

const express = require('express');
const { bookRoutes } = require('./routes');
const { errorHandler } = require('./errorHandler');

// Create an Express application instance.
const app = express();

// ──────────────────────────────────────────────
// Middleware configuration
// ──────────────────────────────────────────────

/**
 * Parse incoming JSON request bodies.
 * Without this, req.body would be undefined for POST/PUT requests.
 */
app.use(express.json());

/**
 * Simple CORS middleware that allows cross‑origin requests from any origin.
 * In production you would restrict the allowed origin(s).
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  if (req.method === 'OPTIONS') return res.sendStatus(200);
  next();
});

// ──────────────────────────────────────────────
// Route registration
// ──────────────────────────────────────────────

/**
 * Mount the book routes under /books.
 * The route file exports an Express Router instance.
 */
app.use('/books', bookRoutes);

/**
 * Mount the stats route at the root level (/stats).
 */
app.get('/stats', (req, res) => {
  const { getStats } = require('./data');
  const stats = getStats();
  res.json({ success: true, data: stats });
});

// ──────────────────────────────────────────────
// Global error‑handling middleware
// ──────────────────────────────────────────────

/**
 * Express error‑handling middleware (must have 4 parameters).
 * Catches both synchronous errors thrown in route handlers and
 * rejected promises from async handlers.
 *
 * @param {Error} err - The error object (usually an AppError instance)
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
app.use(errorHandler);

// ──────────────────────────────────────────────
// Start the server
// ──────────────────────────────────────────────

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
});

module.exports = app;
```

**Key decisions explained:**

1. **`express.json()` middleware** — Required to parse JSON payloads in POST/PUT bodies. Without it, `req.body` is undefined.
2. **CORS middleware** — Allows browser‑based clients from any origin. In a real app you'd restrict this to your frontend domain.
3. **Route mounting** — We separate book routes (`/books/*`) from the stats route (`/stats`) for clarity, though both could live in one file.
4. **Error‑handling middleware** — Placed last so it catches errors from all preceding middleware and routes. Express requires exactly four parameters `(err, req, res, next)` to recognize it as error middleware.

