## File: `data.js`

```js
/**
 * data.js — In‑memory storage for books.
 *
 * We use a plain JavaScript array because:
 *   1. It keeps the example simple and dependency‑free.
 *   2. Arrays provide O(1) access by index and O(n) search, which is fine
 *      for a small educational dataset.
 *   3. No database setup is required to run this API.
 *
 * In a production system you would replace this with a database layer
 * (e.g., MongoDB, PostgreSQL) that provides persistence, concurrency control,
 * and query optimization.
 *
 * @module data
 */

/**
 * Array of book objects stored in memory.
 * Each book has the following shape:
 *   {
 *     id: number,          // Unique identifier (auto‑incremented)
 *     title: string,       // Book title
 *     author: string,      // Author name
 *     genre: string,       // Genre/category
 *     publishedYear: number,// Year of publication
 *     rating: number        // Rating from 1.0 to 5.0
 *   }
 */
let books = [
  { id: 1, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', genre: 'Fiction', publishedYear: 1925, rating: 4.5 },
  { id: 2, title: 'To Kill a Mockingbird', author: 'Harper Lee', genre: 'Fiction', publishedYear: 1960, rating: 4.8 },
  { id: 3, title: '1984', author: 'George Orwell', genre: 'Dystopian', publishedYear: 1949, rating: 4.7 },
  { id: 4, title: 'Pride and Prejudice', author: 'Jane Austen', genre: 'Romance', publishedYear: 1813, rating: 4.6 },
  { id: 5, title: 'The Catcher in the Rye', author: 'J.D. Salinger', genre: 'Fiction', publishedYear: 1951, rating: 4.0 },
];

/** Counter for generating unique IDs. */
let nextId = 6;

// ──────────────────────────────────────────────
// Exported functions
// ──────────────────────────────────────────────

/**
 * Retrieve all books, optionally filtered by query parameters.
 *
 * Supported filters (passed as query string):
 *   - genre: exact match on genre field
 *   - author: case‑insensitive substring match on author name
 *   - minRating: minimum rating (1.0–5.0)
 *   - search: case‑insensitive substring match on title or author
 *
 * @param {Object} filters — Query parameters to apply
 * @returns {Array<Object>} Filtered list of books
 */
function getAllBooks(filters = {}) {
  let result = [...books]; // Clone to avoid mutating the original array

  if (filters.genre) {
    result = result.filter(book => book.genre.toLowerCase() === filters.genre.toLowerCase());
  }
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter(book => book.author.toLowerCase().includes(authorLower));
  }
  if (filters.minRating) {
    const min = parseFloat(filters.minRating);
    if (!isNaN(min)) {
      result = result.filter(book => book.rating >= min);
    }
  }
  if (filters.search) {
    const searchLower = filters.search.toLowerCase();
    result = result.filter(book =>
      book.title.toLowerCase().includes(searchLower) ||
      book.author.toLowerCase().includes(searchLower)
    );
  }

  return result;
}

/**
 * Find a single book by its numeric ID.
 *
 * @param {number} id — The book's unique identifier
 * @returns {Object|undefined} The book object, or undefined if not found
 */
function getBookById(id) {
  return books.find(book => book.id === id);
}

/**
 * Create a new book and add it to the in‑memory store.
 *
 * @param {Object} bookData — Book properties (title, author, genre, publishedYear, rating)
 * @returns {Object} The newly created book object with an assigned ID
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,
    ...bookData,
  };
  books.push(newBook);
  return newBook;
}

/**
 * Update an existing book by ID with the provided data.
 * This performs a full replacement of the mutable fields (not a patch).
 *
 * @param {number} id — The book's unique identifier
 * @param {Object} updates — Fields to update
 * @returns {Object|undefined} The updated book, or undefined if not found
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return undefined;

  books[index] = { ...books[index], ...updates, id }; // Preserve the original ID
  return books[index];
}

/**
 * Delete a book by its ID.
 *
 * @param {number} id — The book's unique identifier
 * @returns {boolean} True if the book was found and deleted, false otherwise
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Compute aggregate statistics about the book collection.
 *
 * Statistics returned:
 *   - totalBooks: number of books in the store
 *   - averageRating: mean rating across all books (rounded to 2 decimals)
 *   - genreDistribution: object mapping each genre to its count
 *   - topRatedBook: the book with the highest rating (null if empty)
 *
 * @returns {Object} Statistics object
 */
function getStats() {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      averageRating: 0,
      genreDistribution: {},
      topRatedBook: null,
    };
  }

  const averageRating = parseFloat(
    (books.reduce((sum, b) => sum + b.rating, 0) / totalBooks).toFixed(2)
  );

  const genreDistribution = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  const topRatedBook = books.reduce((top, book) =>
    book.rating > (top?.rating ?? 0) ? book : top
  , null);

  return {
    totalBooks,
    averageRating,
    genreDistribution,
    topRatedBook,
  };
}

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

**Why an in‑memory array?**  
For an educational example, a database adds complexity (installation, connection strings, migrations). An array lets us focus on HTTP semantics, routing, and validation. In production you would swap this module for a database adapter while keeping the same function signatures — that’s the power of abstraction.

