## File: `errorHandler.js`

```js
/**
 * errorHandler.js — Custom error classes and Express error‑handling middleware.
 *
 * We define an AppError class so every recoverable error carries:
 *   - statusCode (HTTP status code)
 *   - isOperational (true for expected errors, false for bugs)
 *   - message (user‑friendly description)
 *
 * The global error middleware catches both synchronous throws and async rejections,
 * then returns a consistent JSON error response.
 *
 * @module errorHandler
 */

/**
 * Custom error class for application‑level errors.
 * Extends the built‑in Error so it works with instanceof checks and stack traces.
 */
class AppError extends Error {
  /**
   * @param {string} message — Human‑readable error description
   * @param {number} statusCode — HTTP status code (default 400)
   */
  constructor(message, statusCode = 400) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true; // Expected error, not a server bug
  }
}

/**
 * Global Express error‑handling middleware.
 * Must be registered after all routes and normal middleware.
 *
 * @param {Error} err — The error object (usually an AppError)
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function errorHandler(err, req, res, next) {
  // If the error is our custom AppError, use its statusCode and message.
  // Otherwise treat it as an unexpected server error (500).
  const statusCode = err instanceof AppError ? err.statusCode : 500;
  const message = err.message || 'Internal Server Error';

  console.error(`[ERROR] ${statusCode} — ${message}`);
  if (err.stack) console.error(err.stack);

  res.status(statusCode).json({
    success: false,
    error: {
      statusCode,
      message,
      // In production you might hide the stack from clients.
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    },
  });
}

module.exports = { AppError, errorHandler };
```

**Why custom error classes?**  
They give us a single place to attach metadata (status code, operational flag) and ensure every error response has the same shape. This makes client‑side error handling predictable.

