## File: `routes.js`

```js
/**
 * routes.js — Express Router for all /books endpoints.
 *
 * Each route handler is documented with JSDoc so that IDEs and tools
 * can provide autocomplete and inline documentation.
 *
 * @module routes
 */

const express = require('express');
const { AppError } = require('./errorHandler');
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
} = require('./data');

const router = express.Router();

// ──────────────────────────────────────────────
// Helper: validate book input for POST/PUT
// ──────────────────────────────────────────────

/**
 * Validate the fields required when creating or updating a book.
 * Throws an AppError with a 400 status if validation fails.
 *
 * @param {Object} body — The request body to validate
 */
function validateBookBody(body) {
  const errors = [];

  if (!body.title || typeof body.title !== 'string' || body.title.trim() === '') {
    errors.push('title is required and must be a non‑empty string');
  }
  if (!body.author || typeof body.author !== 'string' || body.author.trim() === '') {
    errors.push('author is required and must be a non‑empty string');
  }
  if (!body.genre || typeof body.genre !== 'string' || body.genre.trim() === '') {
    errors.push('genre is required and must be a non‑empty string');
  }
  if (body.publishedYear === undefined || body.publishedYear === null) {
    errors.push('publishedYear is required');
  } else if (!Number.isInteger(body.publishedYear)) {
    errors.push('publishedYear must be an integer');
  }
  if (body.rating === undefined || body.rating === null) {
    errors.push('rating is required');
  } else if (typeof body.rating !== 'number' || body.rating < 1 || body.rating > 5) {
    errors.push('rating must be a number between 1 and 5');
  }

  if (errors.length > 0) {
    throw new AppError(errors.join('; '), 400);
  }
}

// ──────────────────────────────────────────────
// GET /books — List all books with optional filtering
// ──────────────────────────────────────────────

/**
 * Retrieve a list of books. Supports query‑parameter filtering.
 *
 * @route GET /books
 * @query {string} [genre] — Filter by genre (exact match)
 * @query {string} [author] — Filter by author (substring, case‑insensitive)
 * @query {number} [minRating] — Minimum rating (1.0–5.0)
 * @query {string} [search] — Search title or author (substring, case‑insensitive)
 * @returns {Object} JSON response with success flag and books array
 *
 * @example
 * // curl http://localhost:3000/books?genre=Fiction&minRating=4.5
 */
router.get('/', (req, res) => {
  const filteredBooks = getAllBooks(req.query);
  res.json({ success: true, data: filteredBooks });
});

// ──────────────────────────────────────────────
// GET /books/:id — Get a single book by ID
// ──────────────────────────────────────────────

/**
 * Retrieve one book by its numeric ID.
 *
 * @route GET /books/:id
 * @param {number} id — Book identifier from URL path
 * @returns {Object} JSON response with the book object
 * @throws {AppError} 404 if the book is not found
 *
 * @example
 * // curl http://localhost:3000/books/1
 */
router.get('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    throw new AppError('Invalid book ID. Must be a number.', 400);
  }

  const book = getBookById(id);
  if (!book) {
    throw new AppError(`Book with id ${id} not found`, 404);
  }

  res.json({ success: true, data: book });
});

// ──────────────────────────────────────────────
// POST /books — Create a new book
// ──────────────────────────────────────────────

/**
 * Create a new book and return it with a 201 Created status.
 *
 * @route POST /books
 * @body {string} title — Book title (required)
 * @body {string} author — Author name (required)
 * @body {string} genre — Genre/category (required)
 * @body {number} publishedYear — Year of publication (required, integer)
 * @body {number} rating — Rating from 1.0 to 5.0 (required)
 * @returns {Object} JSON response with the newly created book
 * @throws {AppError} 400 if validation fails
 *
 * @example
 * // curl -X POST http://localhost:3000/books \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"Dune","author":"Frank Herbert","genre":"Sci‑Fi","publishedYear":1965,"rating":4.7}'
 */
router.post('/', (req, res) => {
  validateBookBody(req.body);
  const newBook = createBook(req.body);
  res.status(201).json({ success: true, data: newBook });
});

// ──────────────────────────────────────────────
// PUT /books/:id — Update an existing book
// ──────────────────────────────────────────────

/**
 * Replace all mutable fields of an existing book.
 * The ID is taken from the URL; it cannot be changed via the body.
 *
 * @route PUT /books/:id
 * @param {number} id — Book identifier from URL path
 * @body {string} title — New title
 * @body {string} author — New author
 * @body {string} genre — New genre
 * @body {number} publishedYear — New publication year
 * @body {number} rating — New rating (1.0–5.0)
 * @returns {Object} JSON response with the updated book
 * @throws {AppError} 404 if the book is not found; 400 if validation fails
 *
 * @example
 * // curl -X PUT http://localhost:3000/books/1 \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"The Great Gatsby (Updated)","rating":4.9}'
 */
router.put('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    throw new AppError('Invalid book ID. Must be a number.', 400);
  }

  validateBookBody(req.body);
  const updatedBook = updateBook(id, req.body);

  if (!updatedBook) {
    throw new AppError(`Book with id ${id} not found`, 404);
  }

  res.json({ success: true, data: updatedBook });
});

// ──────────────────────────────────────────────
// DELETE /books/:id — Delete a book
// ──────────────────────────────────────────────

/**
 * Remove a book by its ID. Returns 204 No Content on success.
 *
 * @route DELETE /books/:id
 * @param {number} id — Book identifier from URL path
 * @returns {null} Empty body with 204 status
 * @throws {AppError} 404 if the book is not found
 *
 * @example
 * // curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    throw new AppError('Invalid book ID. Must be a number.', 400);
  }

  const deleted = deleteBook(id);
  if (!deleted) {
    throw new AppError(`Book with id ${id} not found`, 404);
  }

  res.status(204).end();
});

module.exports = { bookRoutes: router };
```

**Design notes:**

- **`validateBookBody`** is extracted to avoid duplicating validation logic between `POST` and `PUT`.
- **Async/await** isn’t used here because the in‑memory operations are synchronous, but the pattern is ready for a database layer where async/await would be essential.
- **HTTP status codes** follow REST conventions: `200 OK` for reads, `201 Created` for creation, `204 No Content` for successful deletion, `400 Bad Request` for validation errors, and `404 Not Found` for missing resources.

