## Arquivo 2: `src/data/store.js`

```javascript
/**
 * @fileoverview Armazenamento em memória da API de livros.
 *
 * Escolha da estrutura de dados:
 * - Usamos um ARRAY para armazenar os livros porque o exemplo é educacional
 *   e a quantidade de registros é pequena. Arrays permitem iteração simples
 *   e são nativos do JavaScript, sem dependências externas.
 * - Cada livro é um OBJETO com propriedades tipadas (id: number, title: string,
 *   author: string, year: number) para garantir consistência dos dados.
 * - O ID é gerado automaticamente usando um contador sequencial (nextId),
 *   o que evita colisões e garante unicidade sem depender de bibliotecas
 *   como UUID. Em produção, recomenda-se usar timestamps ou UUIDs v4.
 *
 * Limitações conhecidas:
 * - Dados são perdidos ao reiniciar o servidor (sem persistência).
 * - Não há concorrência segura (sem locks); para múltiplas requisições
 *   simultâneas em produção, considere um banco com transações.
 */

// ──────────────────────────────────────────────
// Estado global do armazenamento
// ──────────────────────────────────────────────

/**
 * @type {Array<Object>} Lista de livros armazenados em memória.
 * Inicialmente vazia; os dados são populados via POST /books.
 */
const books = [];

/**
 * @type {number} Contador sequencial para geração de IDs únicos.
 * Começa em 1 e incrementa a cada novo livro criado.
 * Em um cenário real, esse contador seria substituído pelo auto-incremento
 * do banco de dados ou por uma função geradora de UUID.
 */
let nextId = 1;

// ──────────────────────────────────────────────
// Dados iniciais (seed) para facilitar testes
// ──────────────────────────────────────────────

/**
 * Popula o array com livros de exemplo na inicialização.
 * Isso permite testar os endpoints GET imediatamente após iniciar a API,
 * sem precisar fazer requisições POST primeiro.
 */
function seedData() {
  const initialBooks = [
    { id: 1, title: 'Dom Casmurro', author: 'Machado de Assis', year: 1899 },
    { id: 2, title: 'Memórias Póstumas de Brás Cubas', author: 'Machado de Assis', year: 1881 },
    { id: 3, title: 'O Cortiço', author: 'Aluísio Azevedo', year: 1890 },
  ];

  // Usamos spread (...) para não mutar o array original durante a iteração.
  initialBooks.forEach((book) => {
    books.push({ ...book, id: nextId++ });
  });
}

// Executa o seed assim que este módulo é importado.
seedData();

// ──────────────────────────────────────────────
// Funções de manipulação do store
// ──────────────────────────────────────────────

/**
 * Retorna todos os livros armazenados.
 * @returns {Array<Object>} Cópia rasa do array de livros para evitar
 *                          mutação acidental pelo chamador.
 */
function getAllBooks() {
  return [...books];
}

/**
 * Busca um livro pelo ID.
 * @param {number} id - ID numérico do livro.
 * @returns {Object|undefined} O livro encontrado ou undefined se não existir.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Cria um novo livro e o adiciona ao array.
 * @param {Object} bookData - Dados do livro a ser criado.
 * @returns {Object} O livro criado com ID atribuído.
 */
function createBook(bookData) {
  const newBook = { id: nextId++, ...bookData };
  books.push(newBook);
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} updates - Campos a serem atualizados (partial update).
 * @returns {Object|undefined} O livro atualizado ou undefined se não existir.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return undefined;

  // Mescla os dados existentes com as atualizações (partial update).
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Remove um livro pelo ID.
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} True se o livro foi encontrado e removido, false caso contrário.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 * @returns {Object} Estatísticas: total de livros, média de anos de publicação,
 *                   autor mais prolifico e lista de autores únicos.
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      totalBooks: 0,
      averageYear: null,
      topAuthors: [],
      uniqueAuthors: 0,
    };
  }

  // Calcula a média dos anos de publicação.
  const sumYears = books.reduce((acc, book) => acc + book.year, 0);
  const averageYear = Math.round((sumYears / total) * 100) / 100;

  // Conta ocorrências por autor para encontrar o mais prolifico.
  const authorCounts = {};
  books.forEach((book) => {
    authorCounts[book.author] = (authorCounts[book.author] || 0) + 1;
  });

  // Ordena autores por quantidade de livros (decrescente).
  const topAuthors = Object.entries(authorCounts)
    .map(([name, count]) => ({ author: name, bookCount: count }))
    .sort((a, b) => b.bookCount - a.bookCount);

  return {
    totalBooks: total,
    averageYear,
    topAuthors,
    uniqueAuthors: Object.keys(authorCounts).length,
  };
}

// ──────────────────────────────────────────────
// Exportações (Módulo CommonJS)
// ──────────────────────────────────────────────

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

> **Por que exportar funções e não o array diretamente?** Exportar funções de acesso (getters/setters) é um padrão de *encapsulamento*. Isso permite adicionar validações, logs ou transformações no futuro sem quebrar os módulos que consomem o store. Se expuséssemos o array bruto, qualquer módulo poderia mutá-lo livremente, violando o princípio da responsabilidade única.

