## Arquivo 3: `src/middleware/error-handler.js`

```javascript
/**
 * @fileoverview Middleware de tratamento de erros centralizado.
 *
 * Por que usar um middleware dedicado para erros?
 * - No Express, middlewares de erro têm 4 parâmetros (err, req, res, next).
 *   O framework os identifica automaticamente e os encadeia após qualquer
 *   erro não tratado nas rotas.
 * - Centralizar o tratamento evita repetição de lógica de resposta de erro
 *   em cada rota.
 * - Classes de erro personalizadas permitem distinguir tipos de falha
 *   (ex: recurso não encontrado vs. entrada inválida) e retornar status HTTP
 *   apropriados para cada caso.
 *
 * Convenção REST adotada:
 * - 400 Bad Request       → dados de entrada inválidos
 * - 404 Not Found         → recurso inexistente
 * - 500 Internal Server Error → erro inesperado no servidor
 */

// ──────────────────────────────────────────────
// Classes de Erro Personalizadas
// ──────────────────────────────────────────────

/**
 * @class NotFoundError
 * Representa um recurso solicitado que não foi encontrado.
 * Herda de Error para manter compatibilidade com o stack trace nativo do Node.js.
 */
class NotFoundError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro.
   */
  constructor(message) {
    super(message);
    this.statusCode = 404;
    // Mantém o nome da classe no stack trace (padrão ES2015+).
    Object.setPrototypeOf(this, NotFoundError.prototype);
  }
}

/**
 * @class ValidationError
 * Representa dados de entrada que não passam nas validações.
 */
class ValidationError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro.
   * @param {Array<Object>} details - Lista detalhada dos campos inválidos.
   */
  constructor(message, details = []) {
    super(message);
    this.statusCode = 400;
    this.details = details;
    Object.setPrototypeOf(this, ValidationError.prototype);
  }
}

// ──────────────────────────────────────────────
// Middleware de Tratamento de Erros
// ──────────────────────────────────────────────

/**
 * Middleware que captura erros não tratados e retorna respostas padronizadas.
 * Deve ser registrado APÓS todas as rotas no app Express.
 *
 * @param {Error} err - A instância de erro lançada em uma rota ou middleware anterior.
 * @param {import('express').Request} req - Objeto de requisição do Express.
 * @param {import('express').Response} res - Objeto de resposta do Express.
 * @param {import('express').NextFunction} next - Função next do Express (não usada aqui).
 */
function errorHandler(err, req, res, next) {
  // Se o erro não tiver statusCode definido, assume 500 (erro genérico do servidor).
  const statusCode = err.statusCode || 500;

  // Monta a resposta de erro com formato consistente.
  const errorResponse = {
    success: false,
    error: {
      message: err.message,
      statusCode,
    },
  };

  // Se for erro de validação, inclui os detalhes dos campos problemáticos.
  if (err.details && Array.isArray(err.details)) {
    errorResponse.error.details = err.details;
  }

  // Em desenvolvimento, logamos o stack trace completo para facilitar debugging.
  // Em produção, isso seria desativado para não expor informações sensíveis.
  if (process.env.NODE_ENV !== 'production') {
    console.error(`[Erro ${statusCode}] ${err.message}`);
    console.error(err.stack);
  }

  // Retorna a resposta com o formato padronizado e o status HTTP correto.
  res.status(statusCode).json(errorResponse);
}

// ──────────────────────────────────────────────
// Middleware de Validação de Entrada (Body Parser)
// ──────────────────────────────────────────────

/**
 * Middleware que valida os campos obrigatórios do corpo da requisição
 * ao criar ou atualizar um livro.
 *
 * @param {import('express').Request} req - Objeto de requisição.
 * @param {import('express').Response} res - Objeto de resposta.
 * @param {import('express').NextFunction} next - Função next.
 *
 * Regras de validação:
 * - title: string não vazio (mínimo 1 caractere)
 * - author: string não vazio
 * - year: número inteiro entre 0 e o ano atual + 1 (evita anos no futuro)
 */
function validateBookBody(req, res, next) {
  const { title, author, year } = req.body;

  // Array para acumular múltiplos erros de validação.
  const validationErrors = [];

  if (!title || typeof title !== 'string' || title.trim() === '') {
    validationErrors.push({ field: 'title', message: 'O título é obrigatório e deve ser uma string não vazia.' });
  }

  if (!author || typeof author !== 'string' || author.trim() === '') {
    validationErrors.push({ field: 'author', message: 'O autor é obrigatório e deve ser uma string não vazia.' });
  }

  // Verifica se year é um número válido.
  const bookYear = Number(year);
  if (!year || isNaN(bookYear) || !Number.isInteger(bookYear)) {
    validationErrors.push({ field: 'year', message: 'O ano deve ser um número inteiro.' });
  } else {
    const currentYear = new Date().getFullYear();
    if (bookYear < 0 || bookYear > currentYear + 1) {
      validationErrors.push({
        field: 'year',
        message: `O ano deve estar entre 0 e ${currentYear + 1}.`,
      });
    }
  }

  // Se houver erros, lança ValidationError com todos os detalhes.
  if (validationErrors.length > 0) {
    return next(new ValidationError('Validação falhou nos campos indicados.', validationErrors));
  }

  // Se a validação passou, continua para a próxima etapa.
  next();
}

// ──────────────────────────────────────────────
// Exportações
// ──────────────────────────────────────────────

module.exports = {
  NotFoundError,
  ValidationError,
  errorHandler,
  validateBookBody,
};
```

> **Por que usar classes de erro personalizadas em vez de apenas lançar `Error` genérico?** Classes customizadas permitem que o middleware de erros identifique o tipo de falha e responda com o código HTTP correto (404 vs. 400). Isso segue a convenção REST de usar códigos de status semânticos, facilitando o consumo da API por clientes que precisam tratar diferentes tipos de erro de forma distinta.

