## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * @fileoverview Rotas da API REST para gerenciamento de livros.
 *
 * Convenções REST adotadas:
 * - GET    /books       → listar todos os livros (com filtragem opcional)
 * - GET    /books/:id   → obter um livro específico pelo ID
 * - POST   /books       → criar um novo livro
 * - PUT    /books/:id   → atualizar completamente um livro existente
 * - DELETE /books/:id   → excluir um livro
 * - GET    /stats       → estatísticas agregadas (recurso não-resource)
 *
 * Padrão async/await:
 * - Embora o store seja síncrono (em memória), as rotas usam async/await
 *   para manter compatibilidade com futuras implementações assíncronas
 *   (ex: banco de dados MongoDB, PostgreSQL com driver nativo).
 * - Isso evita refatoração massiva ao migrar a camada de dados.
 *
 * Exemplos de uso (curl):
 *
 *   # Listar todos os livros
 *   curl http://localhost:3000/books
 *
 *   # Listar com filtragem por autor
 *   curl "http://localhost:3000/books?author=Machado"
 *
 *   # Filtrar por ano mínimo
 *   curl "http://localhost:3000/books?year_min=1890"
 *
 *   # Obter livro por ID
 *   curl http://localhost:3000/books/1
 *
 *   # Criar novo livro
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Grande Sertão: Veredas","author":"Guimarães Rosa","year":1956}'
 *
 *   # Atualizar livro (PUT = atualização completa)
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dom Casmurro (Ed. Crítica)","author":"Machado de Assis","year":1899}'
 *
 *   # Excluir livro
 *   curl -X DELETE http://localhost:3000/books/1
 *
 *   # Estatísticas
 *   curl http://localhost:3000/stats
 */

const express = require('express');
const router = express.Router();

// Importa o store de dados (camada de persistência em memória).
const { getAllBooks, getBookById, createBook, updateBook, deleteBook, getStats } = require('../data/store');

// Importa classes e middlewares de erro/validação.
const { NotFoundError, ValidationError, validateBookBody } = require('../middleware/error-handler');

// ──────────────────────────────────────────────
// GET /books — Listar todos os livros (com filtragem)
// ──────────────────────────────────────────────

/**
 * @name GET /books
 * @description Retorna a lista de todos os livros com suporte a filtragem.
 *
 * Parâmetros de query opcionais:
 * - author (string): Filtra por autor (case-insensitive, busca parcial).
 * - year_min (number): Filtra livros publicados a partir deste ano.
 * - year_max (number): Filtra livros publicados até este ano.
 * - search (string): Busca por título ou autor (case-insensitive).
 *
 * @example curl "http://localhost:3000/books?author=Assis"
 * @example curl "http://localhost:3000/books?year_min=1890&year_max=1900"
 */
router.get('/books', (req, res) => {
  // Obtém todos os livros do store.
  let result = getAllBooks();

  // Aplica filtragem por autor (busca parcial, case-insensitive).
  const { author, year_min, year_max, search } = req.query;

  if (author) {
    const authorLower = author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
  }

  // Aplica filtragem por faixa de ano.
  if (year_min) {
    result = result.filter((book) => book.year >= Number(year_min));
  }
  if (year_max) {
    result = result.filter((book) => book.year <= Number(year_max));
  }

  // Aplica busca geral por título ou autor.
  if (search) {
    const searchLower = search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(searchLower) ||
        book.author.toLowerCase().includes(searchLower)
    );
  }

  // Retorna a lista filtrada com status 200 OK.
  res.json({ success: true, count: result.length, data: result });
});

// ──────────────────────────────────────────────
// GET /books/:id — Obter livro por ID
// ──────────────────────────────────────────────

/**
 * @name GET /books/:id
 * @description Retorna um único livro identificado pelo parâmetro de rota :id.
 *
 * Parâmetros de rota:
 * - id (number): ID numérico do livro.
 *
 * @example curl http://localhost:3000/books/1
 */
router.get('/books/:id', (req, res) => {
  // Converte o ID para número; se inválido, lança erro de validação.
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({
      success: false,
      error: { message: 'O ID deve ser um número válido.', statusCode: 400 },
    });
  }

  // Busca o livro no store.
  const book = getBookById(id);

  // Se não encontrado, lança NotFoundError (capturado pelo middleware de erro).
  if (!book) {
    return res.status(404).json({
      success: false,
      error: { message: `Livro com ID ${id} não encontrado.`, statusCode: 404 },
    });
  }

  // Retorna o livro encontrado.
  res.json({ success: true, data: book });
});

// ──────────────────────────────────────────────
// POST /books — Criar novo livro
// ──────────────────────────────────────────────

/**
 * @name POST /books
 * @description Cria um novo livro a partir dos dados enviados no corpo da requisição.
 *
 * Corpo da requisição (JSON):
 * - title (string, obrigatório): Título do livro.
 * - author (string, obrigatório): Nome do autor.
 * - year (number, obrigatório): Ano de publicação.
 *
 * @example curl -X POST http://localhost:3000/books \
 *            -H "Content-Type: application/json" \
 *            -d '{"title":"Capitães da Areia","author":"Jorge Amado","year":1937}'
 */
router.post('/books', validateBookBody, (req, res) => {
  // Extrai os dados do corpo da requisição.
  const { title, author, year } = req.body;

  // Cria o livro no store e obtém o objeto com ID atribuído.
  const newBook = createBook({ title, author, year: Number(year) });

  // Retorna 201 Created (padrão REST para recursos criados).
  res.status(201).json({ success: true, data: newBook });
});

// ──────────────────────────────────────────────
// PUT /books/:id — Atualizar livro existente
// ──────────────────────────────────────────────

/**
 * @name PUT /books/:id
 * @description Atualiza completamente um livro existente.
 *
 * Diferença entre PUT e PATCH:
 * - PUT substitui TODOS os campos do recurso pelos enviados.
 * - PATCH atualizaria apenas os campos fornecidos (partial update).
 * Escolhemos PUT para este exemplo educacional, mas em APIs reais
 * é comum oferecer ambos os verbos.
 *
 * Parâmetros de rota:
 * - id (number): ID do livro a ser atualizado.
 *
 * Corpo da requisição (JSON):
 * - title (string, obrigatório): Novo título.
 * - author (string, obrigatório): Novo autor.
 * - year (number, obrigatório): Novo ano de publicação.
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *            -H "Content-Type: application/json" \
 *            -d '{"title":"Dom Casmurro","author":"Machado de Assis","year":1899}'
 */
router.put('/books/:id', validateBookBody, (req, res) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({
      success: false,
      error: { message: 'O ID deve ser um número válido.', statusCode: 400 },
    });
  }

  const { title, author, year } = req.body;

  // Tenta atualizar no store.
  const updatedBook = updateBook(id, { title, author, year: Number(year) });

  if (!updatedBook) {
    return res.status(404).json({
      success: false,
      error: { message: `Livro com ID ${id} não encontrado.`, statusCode: 404 },
    });
  }

  // Retorna 200 OK com o recurso atualizado.
  res.json({ success: true, data: updatedBook });
});

// ──────────────────────────────────────────────
// DELETE /books/:id — Excluir livro
// ──────────────────────────────────────────────

/**
 * @name DELETE /books/:id
 * @description Remove um livro do armazenamento pelo ID.
 *
 * Parâmetros de rota:
 * - id (number): ID do livro a ser excluído.
 *
 * Resposta: 204 No Content (sem corpo) quando bem-sucedido,
 * conforme convenção REST para operações de deleção.
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/books/:id', (req, res) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({
      success: false,
      error: { message: 'O ID deve ser um número válido.', statusCode: 400 },
    });
  }

  // Tenta excluir no store.
  const deleted = deleteBook(id);

  if (!deleted) {
    return res.status(404).json({
      success: false,
      error: { message: `Livro com ID ${id} não encontrado.`, statusCode: 404 },
    });
  }

  // Retorna 204 No Content (padrão REST para deleção bem-sucedida).
  res.status(204).send();
});

// ──────────────────────────────────────────────
// GET /stats — Estatísticas agregadas
// ──────────────────────────────────────────────

/**
 * @name GET /stats
 * @description Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * Resposta inclui:
 * - totalBooks: quantidade total de livros cadastrados.
 * - averageYear: média dos anos de publicação (arredondada).
 * - topAuthors: lista de autores ordenados por quantidade de obras (decrescente).
 * - uniqueAuthors: quantidade de autores distintos.
 *
 * @example curl http://localhost:3000/stats
 */
router.get('/stats', (req, res) => {
  const stats = getStats();
  res.json({ success: true, data: stats });
});

// ──────────────────────────────────────────────
// Exportação do router
// ──────────────────────────────────────────────

module.exports = router;
```

> **Por que usar `express.Router()`?** O router permite agrupar rotas relacionadas em módulos separados, facilitando a manutenção e a escalabilidade. Quando a API crescer (ex: adicionar rotas de autores, categorias), cada grupo pode ter seu próprio arquivo de rota sem poluir o arquivo principal do app.

