## Arquivo 5: `src/app.js`

```javascript
/**
 * @fileoverview Configuração da aplicação Express.
 *
 * Por que separar a configuração do Express do ponto de entrada?
 * - O arquivo `app.js` configura middlewares, rotas e o servidor em si.
 * - O arquivo `index.js` apenas inicia o servidor na porta configurada.
 * - Essa separação permite testar o app isoladamente (sem precisar iniciar o HTTP server).
 *
 * Middlewares utilizados:
 * - express.json(): Parser automático de corpos JSON nas requisições.
 *   Sem ele, req.body seria undefined em requisições POST/PUT.
 * - cors(): Permite requisições cross-origin (útil para desenvolvimento
 *   com frontends rodando em portas diferentes).
 * - helmet(): Adiciona headers de segurança HTTP (recomendado para produção).
 */

const express = require('express');
const cors = require('cors');
// const helmet = require('helmet'); // Descomentar para produção

const bookRoutes = require('./routes/books');

/**
 * Cria e configura a instância da aplicação Express.
 * @returns {import('express').Application} Instância do app configurada.
 */
function createApp() {
  const app = express();

  // ── Middlewares globais ──────────────────────────────

  /**
   * Habilita CORS para todas as origens.
   * Em produção, restrinja a origem usando { origin: 'https://seu-domínio.com' }.
   */
  app.use(cors());

  // Habilita headers de segurança (descomentar em produção).
  // app.use(helmet());

  /**
   * Parser de JSON com limite de 10kb por corpo.
   * O limite previne requisições maliciosas com payloads gigantes.
   */
  app.use(express.json({ limit: '10kb' }));

  // ── Rotas da API ─────────────────────────────────────

  /**
   * Registra as rotas de livros no path base /api/v1.
   * O prefixo /api/v1 permite versionamento futuro (v2, v3) sem quebrar clientes existentes.
   */
  app.use('/api/v1', bookRoutes);

  // ── Rota de health check ─────────────────────────────

  /**
   * @name GET /health
   * @description Endpoint de verificação de saúde da API.
   * Retornando 200 com timestamp indica que o servidor está respondendo.
   */
  app.get('/health', (req, res) => {
    res.json({
      success: true,
      service: 'book-api',
      uptime: process.uptime(),
      timestamp: new Date().toISOString(),
    });
  });

  // ── Rota 404 para caminhos inexistentes ──────────────

  /**
   * Captura requisições para rotas não definidas e retorna 404.
   * Deve ser registrada APÓS todas as rotas válidas.
   */
  app.use((req, res) => {
    res.status(404).json({
      success: false,
      error: { message: `Rota ${req.method} ${req.path} não encontrada.`, statusCode: 404 },
    });
  });

  // ── Middleware de tratamento de erros (deve ser o último) ──

  /**
   * Middleware de erro centralizado (definido em error-handler.js).
   * Express identifica middlewares de erro pelo número de parâmetros (4).
   */
  const { errorHandler } = require('./middleware/error-handler');
  app.use(errorHandler);

  return app;
}

module.exports = createApp;
```

> **Por que usar um prefixo `/api/v1` nas rotas?** Versionamento de API é uma prática essencial para APIs públicas. Se você precisar alterar o formato de resposta ou adicionar breaking changes no futuro, pode criar `/api/v2` e manter `/api/v1` funcionando para clientes antigos. Sem versionamento, qualquer mudança quebra consumidores da API.

