```javascript
/**
 * @fileoverview Ponto de entrada da aplicação.
 *
 * Responsabilidades:
 * - Criar a instância do app Express.
 * - Iniciar o servidor HTTP na porta configurada.
 * - Logar mensagem de inicialização com informações de acesso.
 */

const createApp = require('./app');

/**
 * Porta onde o servidor irá ouvir.
 * Prioriza variável de ambiente PORT, senão usa 3000 como padrão.
 * Em produção, orquestradores como Kubernetes ou PM2 definem essa variável.
 */
const PORT = process.env.PORT || 3000;

// Cria a aplicação Express.
const app = createApp();

// Inicia o servidor e loga informações de acesso.
const server = app.listen(PORT, () => {
  console.log(`╔══════════════════════════════════════════════════╗`);
  console.log(`║       Book API — Servidor rodando!              ║`);
  console.log(`╠══════════════════════════════════════════════════╣`);
  console.log(`║  Base URL:   http://localhost:${PORT}            ║`);
  console.log(`║  API Docs:   http://localhost:${PORT}/api/v1    ║`);
  console.log(`║  Health:     http://localhost:${PORT}/health    ║`);
  console.log(`╚══════════════════════════════════════════════════╝`);
  console.log('');
  console.log('Endpoints disponíveis:');
  console.log('  GET    /api/v1/books          — Listar livros (com filtragem)');
  console.log('  GET    /api/v1/books/:id      — Obter livro por ID');
  console.log('  POST   /api/v1/books          — Criar novo livro');
  console.log('  PUT    /api/v1/books/:id      — Atualizar livro');
  console.log('  DELETE /api/v1/books/:id      — Excluir livro');
  console.log('  GET    /api/v1/stats          — Estatísticas do acervo');
});

// Tratamento de erros não capturados no processo.
process.on('uncaughtException', (err) => {
  console.error('[Uncaught Exception]', err);
  server.close(() => process.exit(1));
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('[Unhandled Rejection]', reason);
});

module.exports = app;
